import net.runelite.api.WorldType;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.EnumSet;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DetectionGateTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void countsForTheBoundCharacterOnANormalWorld() throws Exception
    {
        FateLockedBundle rules = rulesBoundTo("Nubles");

        assertTrue(DetectionGate.allows(rules, "Nubles", EnumSet.of(WorldType.MEMBERS)));
        assertTrue(DetectionGate.allows(rules, " nubles ", EnumSet.noneOf(WorldType.class)));
        // PvP and high-risk worlds save to the account like any other.
        assertTrue(DetectionGate.allows(rules, "Nubles",
            EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HIGH_RISK)));
    }

    @Test
    public void notForAnotherCharacterOrAnUnboundProfile() throws Exception
    {
        assertFalse(DetectionGate.allows(rulesBoundTo("Nubles"), "Zezima",
            EnumSet.of(WorldType.MEMBERS)));
        assertFalse(DetectionGate.allows(rulesBoundTo("Nubles"), null,
            EnumSet.of(WorldType.MEMBERS)));
        assertFalse(DetectionGate.allows(rulesBoundTo(null), "Nubles",
            EnumSet.of(WorldType.MEMBERS)));
    }

    @Test
    public void notOnAWorldWhoseProgressIsNotTheAccountsOwn() throws Exception
    {
        FateLockedBundle rules = rulesBoundTo("Nubles");
        for (WorldType other : EnumSet.of(WorldType.SEASONAL, WorldType.DEADMAN,
            WorldType.TOURNAMENT_WORLD, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE,
            WorldType.FRESH_START_WORLD, WorldType.QUEST_SPEEDRUNNING,
            WorldType.LAST_MAN_STANDING, WorldType.PVP_ARENA))
        {
            assertFalse(other.name(), DetectionGate.allows(rules, "Nubles",
                EnumSet.of(WorldType.MEMBERS, other)));
        }
    }

    @Test
    public void notWithoutRulesForARun()
    {
        assertFalse(DetectionGate.allows(null, "Nubles", EnumSet.of(WorldType.MEMBERS)));
    }

    /** The v4 fixture, bound to this account, or to none. */
    private static FateLockedBundle rulesBoundTo(String account) throws Exception
    {
        JsonObject root;
        try (InputStream in = DetectionGateTest.class.getClassLoader()
            .getResourceAsStream("bundles/v4-rules.json"))
        {
            root = GSON.fromJson(new String(in.readAllBytes(), StandardCharsets.UTF_8),
                JsonObject.class);
        }
        if (account == null)
        {
            root.getAsJsonObject("rules").add("account", JsonNull.INSTANCE);
        }
        else
        {
            root.getAsJsonObject("rules").addProperty("account", account);
        }
        return FateLockedBundle.loadFromJson(GSON, root.toString());
    }
}

package com.fatelocked;

import org.junit.Test;

import java.lang.reflect.Field;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * The diary tiers are read through RuneLite's gameval ids. Their numbers must
 * stay the ones the deprecated Varbits constants had, in the order the tier
 * names use.
 */
public class DiaryVarbitIdsTest
{
    @Test
    public void diaryTiersKeepTheirVarbitIds() throws Exception
    {
        assertArrayEquals(new int[] {
            4458, 4459, 4460, 4461, // Ardougne
            4483, 4484, 4485, 4486, // Desert
            4462, 4463, 4464, 4465, // Falador
            4491, 4492, 4493, 4494, // Fremennik
            4475, 4476, 4477, 4478, // Kandarin
            3578, 3599, 3611, 4566, // Karamja
            7925, 7926, 7927, 7928, // Kourend & Kebos
            4495, 4496, 4497, 4498, // Lumbridge & Draynor
            4487, 4488, 4489, 4490, // Morytania
            4479, 4480, 4481, 4482, // Varrock
            4471, 4472, 4473, 4474, // Western Provinces
            4466, 4467, 4468, 4469, // Wilderness
        }, (int[]) staticField("DIARY_VARBITS"));
    }

    @Test
    public void eachTierIdNamesItsOwnTier() throws Exception
    {
        @SuppressWarnings("unchecked")
        Map<Integer, String> names = (Map<Integer, String>) staticField("DIARY_VARBIT_NAMES");
        assertEquals(48, names.size());
        assertEquals("Ardougne Easy", names.get(4458));
        assertEquals("Karamja Easy", names.get(3578));
        assertEquals("Karamja Elite", names.get(4566));
        assertEquals("Lumbridge & Draynor Easy", names.get(4495));
        assertEquals("Wilderness Elite", names.get(4469));
    }

    /**
     * Events name each tier by the tracker's id, the keys of DIARIES in the
     * web app's data/diaryData.ts; three regions there are shorter than
     * their full names. Tiers named otherwise matched no tracker task.
     */
    @Test
    public void eventsUseTheTrackersTierIds() throws Exception
    {
        @SuppressWarnings("unchecked")
        Map<Integer, String> ids = (Map<Integer, String>) staticField("DIARY_TIER_IDS");
        Set<String> tracker = new HashSet<>();
        for (String region : new String[] {"Ardougne", "Desert", "Falador", "Fremennik",
            "Kandarin", "Karamja", "Kourend", "Lumbridge", "Morytania", "Varrock", "Western",
            "Wilderness"})
        {
            for (String tier : new String[] {"Easy", "Medium", "Hard", "Elite"})
            {
                tracker.add(region + " " + tier);
            }
        }

        assertEquals(tracker, new HashSet<>(ids.values()));
        assertEquals("Lumbridge Easy", ids.get(4495));
        assertEquals("Kourend Elite", ids.get(7928));
        assertEquals("Western Hard", ids.get(4473));
    }

    private static Object staticField(String name) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(null);
    }
}

