package com.fatelocked;

import org.junit.Test;

import java.time.Instant;
import java.time.ZoneId;
import java.util.HashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SyncViewTest
{
    private static final ZoneId LONDON = ZoneId.of("Europe/London");
    /** 18:00 in London. */
    private static final Instant NOW = Instant.parse("2026-09-26T17:00:00Z");

    @Test
    public void connectedShowsWhenTheRulesWereLastConfirmedOnThePlayersClock()
    {
        SyncView view = view(TrackerConnectionSnapshot.connected(
            Instant.parse("2026-09-26T16:59:00Z"), "41"));

        assertEquals("Connected", view.status);
        assertEquals(SyncView.Tone.GREEN, view.tone);
        assertEquals("17:59", view.lastSync);
        assertNull(view.detail);
        assertEquals(SyncView.Action.CHECK_NOW, view.action);
    }

    @Test
    public void aFailedCheckSaysWhyAndWhenTheNextCheckIs()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE,
            Instant.parse("2026-09-26T16:30:00Z"), "41",
            SyncReason.UNREACHABLE, NOW.plusSeconds(120)));

        assertEquals("Could not reach tracker", view.status);
        assertEquals("RuneLite couldn't reach the tracker. Next check at 18:02.", view.detail);
        assertEquals("17:30", view.lastSync);
        assertEquals(SyncView.Action.CHECK_NOW, view.action);
    }

    @Test
    public void syncOffKeepsThePairingAndPointsToTheSetting()
    {
        SyncView view = view(SyncMachine.idle(false, true));

        assertEquals("Online sync is off", view.status);
        assertTrue(view.detail, view.detail.contains("Turn on online sync"));
        assertEquals(SyncView.Action.ENABLE_SYNC, view.action);
        assertEquals(SyncView.Connect.TURN_ON_SYNC, view.connect);
        assertEquals("\u2014", view.lastSync);
    }

    @Test
    public void withNoPairingTheActionIsConnect()
    {
        for (boolean allowed : new boolean[] {false, true})
        {
            SyncView view = view(SyncMachine.idle(allowed, false));
            assertEquals("Not connected", view.status);
            assertEquals(SyncView.Action.CONNECT, view.action);
        }
    }

    @Test
    public void aPairingThatTimedOutPointsToConnect()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.EXPIRED,
            null, null, SyncReason.NO_PROFILE, null));

        assertEquals(SyncView.Tone.RED, view.tone);
        assertEquals(SyncView.Action.CONNECT, view.action);
    }

    @Test
    public void aLapsedProfilePointsToTheWebTracker()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING,
            NOW.minusSeconds(3600), null, SyncReason.NO_RECENT_UPDATE, null));

        assertEquals(SyncView.Tone.AMBER, view.tone);
        assertEquals(SyncView.Action.OPEN_TRACKER, view.action);
    }

    @Test
    public void aNewerBundleFormatAsksForAPluginUpdate()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED,
            null, "41", SyncReason.FUTURE_FORMAT, null));

        assertEquals("Plugin update needed", view.status);
        assertEquals(SyncView.Tone.RED, view.tone);
        assertEquals(SyncView.Action.UPDATE_PLUGIN, view.action);
        assertTrue(view.detail, view.detail.contains("Plugin Hub"));
    }

    @Test
    public void rulesThatCannotBeUsedPointToTheWebTracker()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED,
            null, "41", SyncReason.INVALID_RULES, null));

        assertEquals(SyncView.Action.OPEN_TRACKER, view.action);
    }

    @Test
    public void checkNowIsOfferedOnlyWithAPairingAndSyncOn()
    {
        assertFalse(view(SyncMachine.idle(true, false)).canCheckNow);
        assertFalse(view(SyncMachine.idle(false, true)).canCheckNow);
        assertTrue(view(SyncMachine.idle(true, true)).canCheckNow);
        assertTrue(view(TrackerConnectionSnapshot.connected(NOW, "41")).canCheckNow);
        assertTrue(view(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE,
            null, null, SyncReason.BUSY, NOW.plusSeconds(120))).canCheckNow);
    }

    @Test
    public void theConnectButtonSaysWhatItWillDo()
    {
        assertEquals(SyncView.Connect.CONNECT, view(SyncMachine.idle(true, false)).connect);
        assertEquals(SyncView.Connect.TURN_ON_SYNC, view(SyncMachine.idle(false, true)).connect);
        // A first pairing that hasn't delivered has nothing to keep.
        assertEquals(SyncView.Connect.CONNECT, view(of(TrackerConnectionState.WAITING,
            SyncReason.CONFIRM_IN_BROWSER)).connect);
        assertEquals(SyncView.Connect.CONNECT, view(of(TrackerConnectionState.EXPIRED,
            SyncReason.NO_PROFILE)).connect);
        // A working pairing is kept: re-pairing asks first.
        assertEquals(SyncView.Connect.REPAIR,
            view(TrackerConnectionSnapshot.connected(NOW, "41")).connect);
        assertEquals(SyncView.Connect.REPAIR, view(of(TrackerConnectionState.OFFLINE,
            SyncReason.UNREACHABLE)).connect);
        assertEquals(SyncView.Connect.CANCEL_REPAIR, view(of(TrackerConnectionState.WAITING,
            SyncReason.CONFIRM_REPAIR)).connect);
        assertEquals("Re-pair tracker\u2026", SyncView.Connect.REPAIR.label);
    }

    private static TrackerConnectionSnapshot of(TrackerConnectionState state, SyncReason reason)
    {
        return TrackerConnectionSnapshot.of(state, null, null, reason, null);
    }

    @Test
    public void aCodeTheOwnerDisconnectedPointsToConnect()
    {
        SyncView view = view(of(TrackerConnectionState.EXPIRED, SyncReason.GONE));

        assertEquals("Disconnected in the web tracker", view.status);
        assertEquals(SyncView.Action.CONNECT, view.action);
        assertEquals(SyncView.Connect.CONNECT, view.connect);
        assertFalse(view.canCheckNow);
    }

    @Test
    public void thePairingShowsOnlyTheLastFourCharactersOfItsCode()
    {
        assertEquals("\u2026cdef", view(TrackerConnectionSnapshot.connected(NOW, "41")
            .forPairing("0123456789abcdef0123456789abcdef")).pairing);
        assertEquals("\u2014", view(SyncMachine.idle(true, false)).pairing);
    }

    @Test
    public void everyReasonHasItsOwnStatusAndExplanation()
    {
        Set<String> statuses = new HashSet<>();
        Set<String> details = new HashSet<>();
        for (SyncReason reason : SyncReason.values())
        {
            if (reason == SyncReason.NONE) continue;
            SyncView view = view(TrackerConnectionSnapshot.of(
                TrackerConnectionState.OFFLINE, null, null, reason, NOW.plusSeconds(30)));
            assertTrue(reason + " shares its status", statuses.add(view.status));
            if (reason == SyncReason.CHECKING)
            {
                // "Checking the tracker" says it all.
                assertNull(view.detail);
                continue;
            }
            assertNotNull(reason + " has no explanation", view.detail);
            assertTrue(reason + " shares its explanation", details.add(view.detail));
        }
    }

    private static SyncView view(TrackerConnectionSnapshot snapshot)
    {
        return SyncView.of(snapshot, NOW, LONDON);
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class AccountBindingTest
{
    @Test
    public void namesCompareAsTheTrackerComparesThem()
    {
        assertTrue(AccountBinding.sameAccount("Iron Example", "iron example"));
        assertTrue(AccountBinding.sameAccount("Iron Example", " Iron Example "));
        assertTrue(AccountBinding.sameAccount("Iron Example", "Iron  Example"));
        assertTrue(AccountBinding.sameAccount("Iron Example", "Iron Example"));
        assertFalse(AccountBinding.sameAccount("Iron Example", "Iron_Example"));
        assertFalse(AccountBinding.sameAccount("Iron Example", "Zezima"));
        assertFalse(AccountBinding.sameAccount("  ", "  "));
        assertFalse(AccountBinding.sameAccount(null, "Zezima"));
        assertFalse(AccountBinding.sameAccount("Iron Example", null));
    }

    @Test
    public void theRulesAccountIsTheBoundAccount() throws Exception
    {
        JsonObject root = fixture();
        root.getAsJsonObject("state").addProperty("linkedAccount", "Somebody Else");
        root.getAsJsonObject("rules").addProperty("account", " Nubles ");

        assertEquals("Nubles", AccountBinding.boundAccount(bundle(root)));
    }

    @Test
    public void aProfileWithoutAnAccountIsUnbound() throws Exception
    {
        JsonObject root = fixture();
        root.getAsJsonObject("rules").addProperty("account", "  ");

        // The rules decide, even when the older field still names someone.
        assertNull(AccountBinding.boundAccount(bundle(root)));
        assertNull(AccountBinding.boundAccount(FateLockedBundle.empty()));
        assertNull(AccountBinding.boundAccount(null));
    }

    @Test
    public void olderBundlesWithoutRulesUseTheLinkedAccount() throws Exception
    {
        FateLockedBundle legacy = FateLockedBundle.loadFromJson(new Gson(),
            resource("bundles/v3-standard.json"));

        assertEquals(legacy.getState() == null ? null : trimmedOrNull(
                legacy.getState().getLinkedAccount()),
            AccountBinding.boundAccount(legacy));
    }

    private static String trimmedOrNull(String name)
    {
        return name == null || name.trim().isEmpty() ? null : name.trim();
    }

    private static FateLockedBundle bundle(JsonObject root)
    {
        return FateLockedBundle.loadFromJson(new Gson(), root.toString());
    }

    private static JsonObject fixture() throws Exception
    {
        return new Gson().fromJson(resource("bundles/v4-rules.json"), JsonObject.class);
    }

    private static String resource(String name) throws Exception
    {
        try (InputStream in = AccountBindingTest.class.getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }
}

package com.fatelocked;

import java.awt.Color;
import java.awt.Component;
import java.awt.event.FocusEvent;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

public class FateLockedConfigBinderTest
{
    private ConfigManager configManager;
    private List<String> statuses;
    private FateLockedConfigBinder binder;

    @Before
    public void setUp()
    {
        configManager = mock(ConfigManager.class);
        statuses = new ArrayList<>();
        binder = new FateLockedConfigBinder(configManager, statuses::add);
    }

    @Test
    public void decliningWarningDoesNotSaveOrEnableTheSetting()
    {
        JCheckBox control = binder.booleanSetting(
            FateLockedConfig.NETWORK_ACCESS_KEY, "Enable online sync",
            () -> false, () -> false);
        control.doClick();
        assertFalse(control.isSelected());
        verifyNoInteractions(configManager);
    }

    @Test
    public void acceptedWarningEnablesSyncAndDisablingNeedsNoConfirmation()
    {
        int[] prompts = {0};
        JCheckBox control = binder.booleanSetting(
            FateLockedConfig.NETWORK_ACCESS_KEY, "Enable online sync",
            () -> false, () -> { prompts[0]++; return true; });
        control.doClick();
        assertTrue(control.isSelected());
        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY, true);
        control.doClick();
        assertFalse(control.isSelected());
        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY, false);
        assertEquals(1, prompts[0]);
    }

    @Test
    public void booleanControlPersistsUserChoiceAndRefreshesWithoutWritingAgain()
    {
        JCheckBox control = binder.booleanSetting(
            "showHud", "Show in-game HUD", () -> true);

        control.doClick();
        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, "showHud", false);

        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, "showHud", Boolean.class))
            .thenReturn(true);
        binder.refresh("showHud");

        assertTrue(control.isSelected());
        verify(configManager, times(1)).setConfiguration(
            FateLockedConfig.GROUP, "showHud", false);
    }

    @Test
    public void colourChoicePersistsSelectedColour()
    {
        Color chosen = new Color(16, 185, 129);
        FateLockedConfigBinder colorBinder = new FateLockedConfigBinder(
            configManager, statuses::add, (parent, title, initial) -> chosen);
        JComponent control = colorBinder.colorSetting(
            "unlockedColor", "Unlocked colour", () -> Color.BLUE);

        ((JButton) control).doClick();

        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, "unlockedColor", chosen);
        assertEquals(chosen, control.getBackground());
    }

    @Test
    public void translucentColoursUseOpaquePreviewsButPersistOriginalRgba()
    {
        Color initial = new Color(16, 185, 129, 90);
        Color chosen = new Color(239, 68, 68, 120);
        Color[] chooserInitial = new Color[1];
        FateLockedConfigBinder colorBinder = new FateLockedConfigBinder(
            configManager, statuses::add, (parent, title, supplied) -> {
                chooserInitial[0] = supplied;
                return chosen;
            });
        JButton control = (JButton) colorBinder.colorSetting(
            "unlockedColor", "Unlocked color", () -> initial);

        assertEquals(
            new Color(16, 185, 129), control.getBackground());
        control.doClick();

        assertSame(initial, chooserInitial[0]);
        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, "unlockedColor", chosen);
        assertEquals(
            new Color(239, 68, 68), control.getBackground());
        assertEquals(255, control.getBackground().getAlpha());
    }

    @Test
    public void escapeClearsKeybind()
    {
        JComponent control = binder.keybindSetting(
            "reimportHotkey", "Re-import hotkey", () -> new Keybind(
                keyPressed(new JButton(), KeyEvent.VK_F)));
        KeybindCaptureButton button = (KeybindCaptureButton) control;

        button.doClick();
        capture(button, keyPressed(button, KeyEvent.VK_ESCAPE));

        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, "reimportHotkey", Keybind.NOT_SET);
    }

    @Test
    public void capturedKeyEventPersistsEquivalentKeybind()
    {
        JComponent control = binder.keybindSetting(
            "reimportHotkey", "Re-import hotkey", () -> Keybind.NOT_SET);
        KeybindCaptureButton button = (KeybindCaptureButton) control;
        KeyEvent event = keyPressed(button, KeyEvent.VK_K);

        button.doClick();
        capture(button, event);

        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, "reimportHotkey", new Keybind(event));
    }

    @Test
    public void failedWriteRestoresLastConfirmedValueAndReportsStatus()
    {
        JCheckBox control = binder.booleanSetting(
            "showHud", "Show in-game HUD", () -> true);
        doThrow(new RuntimeException("no disk"))
            .when(configManager).setConfiguration(
                FateLockedConfig.GROUP, "showHud", false);
        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, "showHud", Boolean.class)).thenReturn(false);

        control.doClick();

        assertTrue(control.isSelected());
        assertEquals(Arrays.asList("couldn't save setting"), statuses);
        verify(configManager, times(1)).setConfiguration(
            FateLockedConfig.GROUP, "showHud", false);
    }

    @Test
    public void capturedSpaceDoesNotReenterCaptureOrSaveTwice()
    {
        DispatchableKeybindCaptureButton button =
            new DispatchableKeybindCaptureButton(Keybind.NOT_SET, value ->
                configManager.setConfiguration(
                    FateLockedConfig.GROUP, "reimportHotkey", value));
        KeyEvent pressed = spaceKeyEvent(button, KeyEvent.KEY_PRESSED, 100L);
        KeyEvent released = spaceKeyEvent(button, KeyEvent.KEY_RELEASED, 101L);

        button.doClick();
        button.processKeyEventForTest(pressed);
        button.processKeyEventForTest(released);

        verify(configManager, times(1)).setConfiguration(
            FateLockedConfig.GROUP, "reimportHotkey", new Keybind(pressed));
        assertFalse("Press a key\u2026".equals(button.getText()));
    }

    @Test
    public void focusLossCancelsCaptureAndRestoresConfirmedDisplay()
    {
        KeybindCaptureButton button = (KeybindCaptureButton) binder.keybindSetting(
            "reimportHotkey", "Re-import hotkey", () -> Keybind.NOT_SET);

        button.doClick();
        focusLost(button);

        assertEquals(Keybind.NOT_SET.toString(), button.getText());
        verifyNoInteractions(configManager);
    }
    @Test
    public void keysContainOnlyControlsCreatedByCaller()
    {
        binder.booleanSetting("showHud", "Show in-game HUD", () -> true);
        binder.keybindSetting("reimportHotkey", "Re-import hotkey", () -> Keybind.NOT_SET);
        binder.colorSetting("unlockedColor", "Unlocked colour", () -> Color.BLUE);

        assertEquals(new LinkedHashSet<>(Arrays.asList(
            "showHud", "reimportHotkey", "unlockedColor")), binder.keys());
        assertNotNull(binder.keys());
        assertFalse(binder.keys().contains("pairingCode"));
    }

    private static void capture(KeybindCaptureButton button, KeyEvent event)
    {
        button.getKeyListeners()[0].keyPressed(event);
    }
    private static void focusLost(KeybindCaptureButton button)
    {
        for (java.awt.event.FocusListener listener : button.getFocusListeners())
        {
            listener.focusLost(new FocusEvent(button, FocusEvent.FOCUS_LOST));
        }
    }

    private static KeyEvent spaceKeyEvent(Component source, int eventId, long when)
    {
        return new KeyEvent(source, eventId, when, 0, KeyEvent.VK_SPACE, ' ',
            KeyEvent.KEY_LOCATION_STANDARD)
        {
            @Override
            public int getExtendedKeyCode()
            {
                return getKeyCode();
            }
        };
    }
    private static KeyEvent keyPressed(Component source, int keyCode)
    {
        return new KeyEvent(source, KeyEvent.KEY_PRESSED, 0L, 0, keyCode,
            KeyEvent.CHAR_UNDEFINED)
        {
            @Override
            public int getExtendedKeyCode()
            {
                return getKeyCode();
            }
        };
    }
    private static final class DispatchableKeybindCaptureButton
        extends KeybindCaptureButton
    {
        private DispatchableKeybindCaptureButton(Keybind keybind,
            java.util.function.Consumer<Keybind> captureListener)
        {
            super(keybind, captureListener);
        }

        private void processKeyEventForTest(KeyEvent event)
        {
            processKeyEvent(event);
        }
    }
}

