import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.InputStream;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Local files are written by one background worker, never on the game
 * thread: the history, the Strict Mode audit log and the Slayer assignment
 * all wait for it.
 */
public class FateLockedPluginLocalWritesTest
{
    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    private final List<Runnable> background = new ArrayList<>();
    private final FateLockedPanel panel = mock(FateLockedPanel.class);
    private FateLockedPlugin plugin;
    private Path dir;

    @Before
    public void setUp() throws Exception
    {
        dir = folder.newFolder("local-writes").toPath();
        plugin = new FateLockedPlugin();
        Gson gson = new Gson();
        Client client = mock(Client.class);
        Player player = mock(Player.class);
        when(player.getName()).thenReturn("Nubles");
        when(client.getLocalPlayer()).thenReturn(player);

        // The client thread runs at once; background work waits here.
        PluginTestSupport.runQueuedWorkInline(plugin);
        ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
        doAnswer(invocation -> {
            background.add(invocation.getArgument(0));
            return null;
        }).when(executor).execute(any(Runnable.class));
        set("executor", executor);

        set("client", client);
        set("config", mock(FateLockedConfig.class));
        set("panel", panel);
        set("gson", gson);
        set("worldMapPointManager", mock(WorldMapPointManager.class));
        set("connectionSettings", new TrackerConnectionSettings(mock(ConfigManager.class)));
        set("active", new ActiveRules(
            FateLockedBundle.loadFromJson(gson, fixture("bundles/v4-rules.json")),
            FateLockedPlugin.RulesSource.NONE));
        set("eventHistory", new FateEventHistory(
            gson, history(), dir.resolve("event-outbox.json")));
        set("strictAuditLog", new StrictModeAuditLog(gson, audit()));
        set("slayerTaskDetector", new SlayerTaskDetector(gson, slayer()));
    }

    @Test
    public void aDetectedEventIsWrittenInTheBackground() throws Exception
    {
        invoke("record", DetectedEvent.class, DetectedEvent.builder()
            .type(FateEventType.QUEST)
            .canonicalLabel("Dragon Slayer")
            .confidence(EventConfidence.EXACT)
            .detectorId("quest-widget-v1")
            .detectorVersion(1)
            .evidence(Collections.<String, Object>emptyMap())
            .build());

        assertFalse(Files.exists(history()));
        verify(panel, never()).updateRollInboxStatus(
            anyInt(), anyInt(), anyInt(), anyBoolean());

        runBackground();

        assertTrue(Files.exists(history()));
        verify(panel).updateRollInboxStatus(1, 0, 0, false);
    }

    @Test
    public void aStrictModeAuditEntryIsWrittenInTheBackground() throws Exception
    {
        invoke("writeTravelAudit", StrictModeAuditEntry.class, new StrictModeAuditEntry(
            1_790_000_000_000L, "TRAVEL", "Teleport falador", "46,52",
            "Locked destination", "BLOCKED", false, false));

        assertFalse(Files.exists(audit()));
        verify(panel, never()).updateRecentPrevented(anyList());

        runBackground();

        assertTrue(Files.exists(audit()));
        verify(panel).updateRecentPrevented(anyList());
    }

    @Test
    public void aSlayerAssignmentIsWrittenInTheBackground()
    {
        ChatMessage message = new ChatMessage();
        message.setType(ChatMessageType.GAMEMESSAGE);
        message.setMessage("You're assigned to kill goblins; only 20 more to go.");

        plugin.onChatMessage(message);
        assertFalse(Files.exists(slayer()));

        runBackground();
        assertTrue(Files.exists(slayer()));
    }

    private void runBackground()
    {
        while (!background.isEmpty())
        {
            background.remove(0).run();
        }
    }

    private Path history()
    {
        return dir.resolve("event-history.json");
    }

    private Path audit()
    {
        return dir.resolve("strict-mode-events.json");
    }

    private Path slayer()
    {
        return dir.resolve("slayer-assignment.json");
    }

    private <T> void invoke(String name, Class<T> type, T argument) throws Exception
    {
        Method method = FateLockedPlugin.class.getDeclaredMethod(name, type);
        method.setAccessible(true);
        method.invoke(plugin, argument);
    }

    private void set(String name, Object value) throws Exception
    {
        PluginTestSupport.set(plugin, name, value);
    }

    private static String fixture(String name) throws Exception
    {
        try (InputStream in = FateLockedPluginLocalWritesTest.class
            .getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }
}

package com.fatelocked;

import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import java.lang.reflect.Method;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class FateLockedConfigTest
{
    @Test
    public void strictModeDefaultsOff()
    {
        FateLockedConfig config = new FateLockedConfig() {};
        assertFalse(config.strictMode());
    }

    @Test
    public void configRetainsSettingsAndAddsDefaultOffNetworkConsent()
    {
        Map<String, ConfigItem> items = configItemsByKey();
        assertEquals(30, items.size());
        assertFalse(new FateLockedConfig() { }.trackerNetworkAccess());
        assertEquals(FateLockedConfig.NETWORK_WARNING,
            items.get(FateLockedConfig.NETWORK_ACCESS_KEY).warning());
        assertFalse(items.containsKey("onlineSync"));
        assertFalse(items.containsKey("syncCode"));
        assertFalse(items.containsKey("relayUrl"));
        // Owner decision 3: the folder watcher and its setting are gone.
        assertFalse(items.containsKey("autoReload"));
        assertEquals("Strict Mode", items.get("strictMode").name());
    }

    @Test
    public void configSurfaceHasOneStrictToggleAndNoTravelGuardianItem()
    {
        int strictModeItems = 0;
        for (Method method : FateLockedConfig.class.getDeclaredMethods())
        {
            ConfigItem item = method.getAnnotation(ConfigItem.class);
            if (item == null) continue;
            String surface = (item.keyName() + " " + item.name() + " "
                + item.description()).toLowerCase(Locale.ROOT);
            String compact = surface.replaceAll("[^a-z0-9]", "");
            assertFalse(compact.contains("travelguardian"));
            assertFalse(surface.contains("travel")
                && surface.contains("guardian"));
            if ("strictMode".equals(item.keyName()))
            {
                strictModeItems++;
                assertEquals("Strict Mode", item.name());
            }
        }
        assertEquals(1, strictModeItems);
    }

    private static Map<String, ConfigItem> configItemsByKey()
    {
        Map<String, ConfigItem> items = new LinkedHashMap<>();
        for (Method method : FateLockedConfig.class.getDeclaredMethods())
        {
            ConfigItem item = method.getAnnotation(ConfigItem.class);
            if (item != null)
            {
                items.put(item.keyName(), item);
            }
        }
        return items;
    }
}

package com.fatelocked;

import com.fatelocked.guardian.travel.TravelBlockNoticeStore;
import org.junit.Test;

import java.awt.Canvas;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class FateLockedTravelBlockOverlayTest
{
    @Test
    public void rendersOnlyForAnActiveNoticeWhileStrictModeIsEnabledAndUnpaused()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean enabled = new AtomicBoolean(true);
        AtomicBoolean paused = new AtomicBoolean(false);
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, enabled::get, paused::get, () -> {});

        assertEquals(null, render(overlay));

        store.show("boat:port", "Travel blocked - Boat", "Port is locked", "Varrock tablet");
        Dimension rendered = render(overlay);
        assertNotNull(rendered);
        assertNotNull(overlay.getPauseButtonBounds());

        enabled.set(false);
        assertEquals(null, render(overlay));
        enabled.set(true);
        paused.set(true);
        assertEquals(null, render(overlay));
    }

    @Test
    public void onlyLeftPressInsidePauseButtonInvokesTheSuppliedCallbackAndConsumesTheEvent()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);

        Rectangle button = overlay.getPauseButtonBounds();
        MouseEvent inside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x + button.width / 2, button.y + button.height / 2, MouseEvent.BUTTON1);
        MouseEvent outside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x - 1, button.y - 1, MouseEvent.BUTTON1);
        MouseEvent rightInside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x + button.width / 2, button.y + button.height / 2, MouseEvent.BUTTON3);

        assertNull(overlay.mousePressed(inside));
        assertEquals(1, pauses.get());
        assertSame(outside, overlay.mousePressed(outside));
        assertSame(rightInside, overlay.mousePressed(rightInside));
        assertEquals(1, pauses.get());
    }

    @Test
    public void pausesForTheVisibleCanvasRelativeButtonAndNotItsOldLocalCoordinates()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        overlay.setBounds(new Rectangle(120, 70, 0, 0));
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);

        Rectangle localButton = overlay.getPauseButtonBounds();
        MouseEvent visibleButton = mouse(MouseEvent.MOUSE_PRESSED,
            120 + localButton.x + localButton.width / 2,
            70 + localButton.y + localButton.height / 2, MouseEvent.BUTTON1);
        MouseEvent oldLocalCoordinates = mouse(MouseEvent.MOUSE_PRESSED,
            localButton.x + localButton.width / 2,
            localButton.y + localButton.height / 2, MouseEvent.BUTTON1);

        assertNull(overlay.mousePressed(visibleButton));
        assertEquals(1, pauses.get());
        assertSame(oldLocalCoordinates, overlay.mousePressed(oldLocalCoordinates));
        assertEquals(1, pauses.get());
    }

    @Test
    public void passesThroughWhenStrictModeIsDisabledAfterRendering()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean enabled = new AtomicBoolean(true);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, enabled::get, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        enabled.set(false);

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void passesThroughWhenStrictModeIsPausedAfterRendering()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean paused = new AtomicBoolean(false);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, paused::get, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        paused.set(true);

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void passesThroughWhenTheNoticeExpiresAfterRendering()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        clock.advance(Duration.ofSeconds(4));

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void nonPressMouseEventsAlwaysPassThroughUnchanged()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, () -> {});
        MouseEvent event = mouse(MouseEvent.MOUSE_MOVED, 4, 5, MouseEvent.NOBUTTON);

        assertSame(event, overlay.mouseClicked(event));
        assertSame(event, overlay.mouseReleased(event));
        assertSame(event, overlay.mouseEntered(event));
        assertSame(event, overlay.mouseExited(event));
        assertSame(event, overlay.mouseDragged(event));
        assertSame(event, overlay.mouseMoved(event));
    }

    private static Dimension render(FateLockedTravelBlockOverlay overlay)
    {
        BufferedImage image = new BufferedImage(500, 250, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            return overlay.render(graphics);
        }
        finally
        {
            graphics.dispose();
        }
    }

    private static MouseEvent mouse(int id, int x, int y, int button)
    {
        return new MouseEvent(new Canvas(), id, 0L, 0, x, y, 1, false, button);
    }

    private static MouseEvent insideButton(FateLockedTravelBlockOverlay overlay)
    {
        Rectangle button = overlay.getPauseButtonBounds();
        Rectangle overlayBounds = overlay.getBounds();
        return mouse(MouseEvent.MOUSE_PRESSED,
            overlayBounds.x + button.x + button.width / 2,
            overlayBounds.y + button.y + button.height / 2, MouseEvent.BUTTON1);
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration)
        {
            now = now.plus(duration);
        }

        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

