        + "\"chunks\":{\"Misthalin\":[{\"cx\":50,\"cy\":50}],"
        + "\"Asgarnia\":[{\"cx\":46,\"cy\":52},{\"cx\":47,\"cy\":52}]},"
        + "\"unlockedRegions\":[\"Misthalin\"]}";
