        loadRules();

        walk(UNMAPPED);
        verify(chat, never()).queue(any(QueuedMessage.class));

        walk(LUMBRIDGE);
        verify(chat, times(1)).queue(any(QueuedMessage.class));
    }

    @Test
    public void theLockedWarningSoundsOnceOnTheWayIn() throws Exception
    {
        loadRules();

        walk(LUMBRIDGE, FALADOR, FALADOR_EAST, FALADOR);
        verify(client, times(1)).playSoundEffect(LOCKED_SOUND);
        verify(notifier, times(1)).notify("Entered LOCKED chunk: Asgarnia");

        walk(LUMBRIDGE, FALADOR);
        verify(client, times(2)).playSoundEffect(LOCKED_SOUND);
    }

    @Test
    public void theLockedWarningDoesNotNeedChunkChat() throws Exception
    {
        loadRules();
        when(config.chatOnEnter()).thenReturn(false);

        walk(LUMBRIDGE, FALADOR);

        verify(chat, never()).queue(any(QueuedMessage.class));
        verify(client).playSoundEffect(LOCKED_SOUND);
        verify(notifier).notify("Entered LOCKED chunk: Asgarnia");
    }

    @Test
    public void turningTheWarningOffSilencesIt() throws Exception
    {
        loadRules();
        when(config.warnOnLocked()).thenReturn(false);

        walk(LUMBRIDGE, FALADOR);

        verify(client, never()).playSoundEffect(anyInt());
        verify(notifier, never()).notify(anyString());
    }

    @Test
    public void theWarningsCountFollowsThePlayer() throws Exception
    {
        loadRules();

        walk(LUMBRIDGE);
        verify(panel, times(1)).updateRollInboxStatus(0, 0, 0, false);
        walk(FALADOR);
        verify(panel, times(1)).updateRollInboxStatus(0, 0, 1, false);
        walk(FALADOR_EAST);
        verify(panel, times(1)).updateRollInboxStatus(0, 0, 1, false);
        walk(LUMBRIDGE);
        verify(panel, times(2)).updateRollInboxStatus(0, 0, 0, false);
    }

    private void loadRules() throws Exception
    {
        FateLockedBundle rules = FateLockedBundle.loadFromJson(new Gson(), RULES);
        assertFalse(rules.isEmpty());
        assertEquals(FateLockedBundle.LockState.UNLOCKED, rules.lockStateAt(LUMBRIDGE));
        assertEquals(FateLockedBundle.LockState.LOCKED, rules.lockStateAt(FALADOR));
        assertEquals(FateLockedBundle.LockState.LOCKED, rules.lockStateAt(FALADOR_EAST));
        assertEquals(FateLockedBundle.LockState.UNAUTHORED, rules.lockStateAt(UNMAPPED));
        set("active", new ActiveRules(rules, FateLockedPlugin.RulesSource.NONE));
    }

    /** Stand in each chunk for one game tick. */
    private void walk(CanonicalChunk... chunks)
    {
        for (CanonicalChunk chunk : chunks)
        {
            when(player.getWorldLocation()).thenReturn(
                new WorldPoint((chunk.getCx() << 6) + 8, (chunk.getCy() << 6) + 8, 0));
            // The tick event carries nothing the plugin reads.
            plugin.onGameTick(null);
        }
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.client.config.ConfigManager;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Every reply in the relay fixture, through the real connection controller
 * and a real socket, ends in a state the sidebar explains: Stage 1's "every
 * relay outcome maps to a visible state". RelayTransportFixtureTest runs the
 * transport cases.
 */
public class RelayFixtureStatesTest
{
    private static final String CODE = "0123456789abcdef0123456789abcdef";
    /** "a 304 for a version the plugin does not hold": nothing changes on screen. */
    private static final String NOTHING_CHANGES = "unconfirmed";
    /** The state and reason each outcome shows. */
    private static final Map<String, Shown> SHOWS = Map.of(
        "rules", new Shown(TrackerConnectionState.CONNECTED, SyncReason.NONE),
        "unchanged", new Shown(TrackerConnectionState.CONNECTED, SyncReason.NONE),
        "stale", new Shown(TrackerConnectionState.WAITING, SyncReason.OLDER_RULES),
        "missing", new Shown(TrackerConnectionState.WAITING, SyncReason.NO_RECENT_UPDATE),
        "gone", new Shown(TrackerConnectionState.EXPIRED, SyncReason.GONE),
        "unreadable", new Shown(TrackerConnectionState.OFFLINE, SyncReason.UNREADABLE),
        "busy", new Shown(TrackerConnectionState.OFFLINE, SyncReason.BUSY),
        "unavailable", new Shown(TrackerConnectionState.OFFLINE, SyncReason.UNAVAILABLE),
        "unreachable", new Shown(TrackerConnectionState.OFFLINE, SyncReason.UNREACHABLE));

    private final Gson gson = new Gson();

    @Test
    public void everyOutcomeInTheFixtureHasAState() throws Exception
    {
        for (String outcome : RelayContractFixtureTest.fixture().getAsJsonObject("outcomes").keySet())
        {
            assertTrue(outcome + " has no state",
                SHOWS.containsKey(outcome) || outcome.equals(NOTHING_CHANGES));
        }
    }

    @Test
    public void everyReplyEndsInTheStateItsOutcomeShows() throws Exception
    {
        List<String> mismatches = new ArrayList<>();
        for (JsonElement element : RelayContractFixtureTest.fixture().getAsJsonArray("cases"))
        {
            JsonObject relayCase = element.getAsJsonObject();
            if (relayCase.get("from").getAsString().equals("transport")) continue;
            String name = relayCase.get("name").getAsString();
            String outcome = relayCase.get("outcome").getAsString();
            TrackerConnectionSnapshot[] beforeAndAfter = replay(relayCase);
            TrackerConnectionSnapshot after = beforeAndAfter[1];

            if (outcome.equals(NOTHING_CHANGES))
            {
                if (!after.equals(beforeAndAfter[0])) mismatches.add(name + ": the status changed");
                continue;
            }
            Shown expected = SHOWS.get(outcome);
            if (expected.state != after.getState() || expected.reason != after.getReason())
            {
                mismatches.add(name + ": " + after.getState() + "/" + after.getReason());
            }
            SyncView view = SyncView.of(after, Instant.now(), ZoneId.of("UTC"));
            if (view.status == null || view.status.isEmpty())
            {
                mismatches.add(name + ": no status");
            }
            if (after.getState() != TrackerConnectionState.CONNECTED && view.detail == null)
            {
                mismatches.add(name + ": nothing says why");
            }
        }
        assertEquals(List.of(), mismatches);
    }

    /** The status before and after the plugin's check gets this case's reply. */
    private TrackerConnectionSnapshot[] replay(JsonObject relayCase) throws Exception
    {
        Map<String, String> configuration = new ConcurrentHashMap<>();
        configuration.put(TrackerConnectionSettings.PAIRING_CODE_KEY, CODE);
        configuration.put(FateLockedConfig.NETWORK_ACCESS_KEY, "true");
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString()))
            .thenAnswer(invocation -> configuration.get(invocation.getArgument(1)));

        MockWebServer server = new MockWebServer();
        server.start();
        Interceptor redirectToServer = chain -> {
            Request original = chain.request();
            return chain.proceed(original.newBuilder()
                .url(server.url(original.url().encodedPath()))
                .build());
        };
        OkHttpClient http = new OkHttpClient.Builder().addInterceptor(redirectToServer).build();
        TrackerConnectionController controller = new TrackerConnectionController(
            http, gson, new TrackerConnectionSettings(configManager), Clock.systemUTC(),
            Runnable::run, new AcceptingImporter(), snapshot -> { });
        try
        {
            if (relayCase.has("held") && !relayCase.get("held").isJsonNull())
            {
                controller.seedAcceptedVersion(relayCase.get("held").getAsString());
            }
            TrackerConnectionSnapshot before = controller.snapshot();
            server.enqueue(response(relayCase.getAsJsonObject("response")));
            controller.poll();
            assertNotNull(server.takeRequest(2, TimeUnit.SECONDS));
            waitFor(() -> !controller.pollInFlight());
            return new TrackerConnectionSnapshot[] {before, controller.snapshot()};
        }
        finally
        {
            controller.stop();
            server.shutdown();
        }
    }

    private static MockResponse response(JsonObject reply)
    {
        MockResponse response = new MockResponse().setResponseCode(reply.get("status").getAsInt());
        if (reply.has("headers"))
        {
            for (Map.Entry<String, JsonElement> header : reply.getAsJsonObject("headers").entrySet())
            {
                response.addHeader(header.getKey(), header.getValue().getAsString());
            }
        }
        if (reply.has("body") && !reply.get("body").isJsonNull())
        {
            response.setBody(reply.get("body").getAsString());
        }
        return response;
    }

    private static void waitFor(BooleanSupplier condition) throws Exception
    {
        for (int attempt = 0; attempt < 300; attempt++)
        {
            if (condition.getAsBoolean()) return;
            Thread.sleep(10);
        }
        throw new AssertionError("condition was not reached");
    }

    /** Takes whatever rules the relay sends: this test is about the connection. */
    private static final class AcceptingImporter
        implements TrackerConnectionController.RelayBundleImporter<String>
    {
        @Override
        public TrackerConnectionController.Prepared<String> prepare(String payload)
        {
            return TrackerConnectionController.Prepared.ok(payload);
        }

        @Override
        public boolean commit(String payload, String version)
        {
            return true;
        }
    }

    private static final class Shown
    {
        private final TrackerConnectionState state;
        private final SyncReason reason;

        private Shown(TrackerConnectionState state, SyncReason reason)
        {
            this.state = state;
            this.reason = reason;
        }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PluginHubNetworkBoundaryTest
{
    private static final String[] LEGACY_TOKEN_PREFIXES = {
        "eventToken.", "stateToken.", "suggestToken.", "ackToken."
    };

    @Test
    public void productionSourceHasOneFixedInboundRequestBoundary()
        throws Exception
    {
        Map<Path, String> sources = productionSources();
        String allSource = String.join("\n", sources.values());
        String controllerSource = sourceNamed(
            sources, "TrackerConnectionController.java");
        String compactController =
            controllerSource.replaceAll("\\s+", " ");

        assertEquals(1, occurrences(allSource, "new Request.Builder()"));
        assertTrue(compactController.contains(
            "TrackerConnectionSettings.RELAY_BASE_URL"
                + " + \"/r/\" + token.code"));
        assertTrue(controllerSource.contains(".get()"));
        assertFalse(controllerSource.contains(".post("));
        assertFalse(controllerSource.contains(".put("));
        assertFalse(controllerSource.contains(".patch("));
        assertFalse(controllerSource.contains(".delete("));

        assertAbsent(allSource,
            "/events",
            "/acks",
            "/suggest",
            "/state",
            "RequestBody",
            "FateEventRelayClient",
            "FateEventOutbox",
            "localhost",
            "127.0.0.1",
            "ProcessBuilder",
            "Runtime.getRuntime().exec",
            "Class.forName",
            "java.lang.reflect",
            "ServerSocket",
            "HttpServer",
            "HttpsServer");

        assertEquals(1, occurrences(allSource, "@PluginDescriptor("));
        assertEquals(1, occurrences(allSource, "NavigationButton.builder()"));
    }

    @Test
    public void legacyTokenNamesExistOnlyInOneWayCleanup()
        throws Exception
    {
        Map<Path, String> sources = productionSources();
        String settingsSource = sourceNamed(
            sources, "TrackerConnectionSettings.java");
        StringBuilder otherSource = new StringBuilder();
        for (Map.Entry<Path, String> entry : sources.entrySet())
        {
            if (!entry.getKey().getFileName().toString()
                .equals("TrackerConnectionSettings.java"))
            {
                otherSource.append(entry.getValue()).append('\n');
            }
        }

        for (String prefix : LEGACY_TOKEN_PREFIXES)
        {
            assertTrue(settingsSource.contains("\"" + prefix + "\""));
            assertFalse(otherSource.toString().contains(prefix));
        }
        assertFalse(settingsSource.contains("String token("));
        assertFalse(settingsSource.contains("void saveToken("));
        assertAbsent(otherSource.toString(),
            "TokenResponse",
            "saveToken(",
            "loadRelayToken(",
            "tokenRequest",
            "requestToken");
    }

    private static Map<Path, String> productionSources()
        throws IOException
    {
        Path root = Paths.get("src", "main", "java");
        Map<Path, String> sources = new LinkedHashMap<>();
        try (Stream<Path> paths = Files.walk(root))
        {
            paths.filter(path -> path.toString().endsWith(".java"))
                .sorted()
                .forEach(path -> sources.put(
                    path, read(path)));
        }
        return sources;
    }

    private static String sourceNamed(
        Map<Path, String> sources, String fileName)
    {
        for (Map.Entry<Path, String> entry : sources.entrySet())
        {
            if (entry.getKey().getFileName().toString().equals(fileName))
            {
                return entry.getValue();
            }
        }
        throw new AssertionError("missing production source " + fileName);
    }

    private static String read(Path path)
    {
        try
        {
            return new String(
                Files.readAllBytes(path), StandardCharsets.UTF_8);
        }
        catch (IOException ex)
        {
            throw new AssertionError("could not read " + path, ex);
        }
    }

    private static void assertAbsent(
        String source, String... forbidden)
    {
        for (String value : forbidden)
        {
            assertFalse(
                "forbidden production source value: " + value,
                source.contains(value));
        }
    }

    private static int occurrences(String text, String value)
    {
        int count = 0;
        int offset = 0;
        while ((offset = text.indexOf(value, offset)) >= 0)
        {
            count++;
            offset += value.length();
        }
        return count;
    }
}

