        FateLockedBundle tracker = v4Bundle(Instant.now());
        h.setRules(tracker, FateLockedPlugin.RulesSource.RELAY);

        h.invoke("loadSavedRules");

        assertSame(tracker, h.plugin.getBundle());
        assertEquals(FateLockedPlugin.RulesSource.RELAY, h.source());
    }

    @Test
    public void savedTrackerRulesAskTheRelayOnlyWhetherTheyAreCurrent() throws Exception
    {
        Harness h = new Harness(folder.newFolder("same-pairing"));
        h.save(FateLockedPlugin.RulesSource.RELAY, "41", PairingSupport.tag(CODE));
        when(h.settings.pairingCode()).thenReturn(CODE);

        h.invoke("loadSavedRules");

        assertEquals(FateLockedPlugin.RulesSource.RELAY, h.source());
        verify(h.controller).seedAcceptedVersion("41");
        // Not fresh for Strict Mode until the relay confirms them.
        h.paired(true);
        assertFalse(h.plugin.rulesAreFresh());
    }

    @Test
    public void savedRulesFromAnotherPairingAreFetchedAfresh() throws Exception
    {
        Harness h = new Harness(folder.newFolder("other-pairing"));
        h.save(FateLockedPlugin.RulesSource.RELAY, "41",
            PairingSupport.tag("fedcba9876543210fedcba9876543210"));
        when(h.settings.pairingCode()).thenReturn(CODE);

        h.invoke("loadSavedRules");

        assertFalse(h.plugin.getBundle().getRegionChunks().isEmpty());
        verify(h.controller, never()).seedAcceptedVersion(anyString());
    }

    @Test
    public void nothingImportedIsNeverFresh() throws Exception
    {
        Harness h = new Harness(folder.newFolder("nothing"));
        assertFalse(h.plugin.rulesAreFresh());
    }

    @Test
    public void fileAndClipboardRulesCountFromTheirExportTime() throws Exception
    {
        Harness h = new Harness(folder.newFolder("export-time"));
        Instant now = Instant.now();
        for (FateLockedPlugin.RulesSource local : new FateLockedPlugin.RulesSource[] {
            FateLockedPlugin.RulesSource.FILE, FateLockedPlugin.RulesSource.IMPORT })
        {
            h.setRules(v4Bundle(now.minus(Duration.ofMinutes(2))), local);
            assertTrue(local + " exported 2 minutes ago", h.plugin.rulesAreFresh());

            // Loaded just now, but exported two weeks ago: never fresh.
            h.setRules(v4Bundle(now.minus(Duration.ofDays(14))), local);
            assertFalse(local + " exported two weeks ago", h.plugin.rulesAreFresh());

            h.setRules(v4Bundle(now.plus(Duration.ofHours(1))), local);
            assertFalse(local + " exported in the future", h.plugin.rulesAreFresh());

            h.setRules(fixtureBundle("bundles/v3-standard.json"), local);
            assertFalse(local + " without an export time", h.plugin.rulesAreFresh());
        }
    }

    @Test
    public void trackerRulesStayFreshWhileTheRelayConfirmsThem() throws Exception
    {
        Harness h = new Harness(folder.newFolder("relay"));
        Instant now = Instant.now();
        // Exported long ago, but confirmed by the relay a minute ago.
        h.setRules(v4Bundle(now.minus(Duration.ofDays(2))),
            FateLockedPlugin.RulesSource.RELAY);
        h.paired(true);

        h.lastSync(now.minus(Duration.ofMinutes(1)));
        assertTrue(h.plugin.rulesAreFresh());

        h.lastSync(now.minus(Duration.ofMinutes(20)));
        assertFalse(h.plugin.rulesAreFresh());

        // Online sync turned off: nothing confirms them, so fall back to the
        // export time, which is two days old.
        h.lastSync(now.minus(Duration.ofMinutes(1)));
        h.paired(false);
        assertFalse(h.plugin.rulesAreFresh());
    }

    private static FateLockedBundle v4Bundle(Instant exportedAt) throws Exception
    {
        return FateLockedBundle.loadFromJson(new Gson(), v4Json(exportedAt));
    }

    private static String v4Json(Instant exportedAt) throws Exception
    {
        JsonObject root = new Gson().fromJson(
            fixture("bundles/v4-rules.json"), JsonObject.class);
        root.getAsJsonObject("rules").addProperty("exportedAt", exportedAt.toString());
        return root.toString();
    }

    private static FateLockedBundle fixtureBundle(String name) throws Exception
    {
        return FateLockedBundle.loadFromJson(new Gson(), fixture(name));
    }

    private static String fixture(String name) throws Exception
    {
        try (InputStream in = FateLockedRulesSourceTest.class.getClassLoader()
            .getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    private static final class Harness
    {
        private final FateLockedPlugin plugin;
        private final FateLockedPanel panel = mock(FateLockedPanel.class);
        private final TrackerConnectionController controller =
            mock(TrackerConnectionController.class);
        private final TrackerConnectionSettings settings =
            mock(TrackerConnectionSettings.class);
        private final ScheduledExecutorService executor;
        private final Path savedRulesPath;

        private Harness(File dataDirectory) throws Exception
        {
            plugin = new FateLockedPlugin()
            {
                @Override
                File dataDirectory()
                {
                    return dataDirectory;
                }
            };
            PluginTestSupport.runQueuedWorkInline(plugin);
            executor = (ScheduledExecutorService) PluginTestSupport.get(plugin, "executor");
            savedRulesPath = dataDirectory.toPath().resolve(SavedRulesStore.FILE_NAME);
            set("savedRules", new SavedRulesStore(new Gson(), savedRulesPath));
            set("client", mock(Client.class));
            set("config", mock(FateLockedConfig.class));
            set("panel", panel);
            set("gson", new Gson());
            set("worldMapPointManager", mock(WorldMapPointManager.class));
            set("connectionController", controller);
            set("connectionSettings", settings);
            when(controller.snapshot()).thenReturn(TrackerConnectionSnapshot.disconnected());
        }

        /** Rules a previous start saved: the v4 fixture, exported just now. */
        void save(FateLockedPlugin.RulesSource source, String version, String pairingTag)
            throws Exception
        {
            new SavedRulesStore(new Gson(), savedRulesPath).save(new SavedRules(
                v4Json(Instant.now()), source, Instant.now(), version, pairingTag));
        }

        /** What the next start would find. */
        SavedRules savedRules()
        {
            SavedRules saved = new SavedRulesStore(new Gson(), savedRulesPath).load();
            assertNotNull("no saved rules", saved);
            return saved;
        }

        void setRules(FateLockedBundle bundle, FateLockedPlugin.RulesSource source)
            throws Exception
        {
            set("active", new ActiveRules(bundle, source));
        }

        FateLockedPlugin.RulesSource source() throws Exception
        {
            Field field = FateLockedPlugin.class.getDeclaredField("active");
            field.setAccessible(true);
            return ((ActiveRules) field.get(plugin)).getSource();
        }

        void paired(boolean paired)
        {
            when(settings.networkAccessAllowed()).thenReturn(paired);
            when(settings.isPaired()).thenReturn(paired);
        }

        void lastSync(Instant at)
        {
            when(controller.snapshot()).thenReturn(
                TrackerConnectionSnapshot.connected(at, "5"));
        }

        void invoke(String method) throws Exception
        {
            Method declared = FateLockedPlugin.class.getDeclaredMethod(method);
            declared.setAccessible(true);
            declared.invoke(plugin);
        }

        void loadBackupFileAtStartup() throws Exception
        {
            Method declared = FateLockedPlugin.class.getDeclaredMethod(
                "loadBackupFile", boolean.class);
            declared.setAccessible(true);
            declared.invoke(plugin, false);
        }

        private void set(String name, Object value) throws Exception
        {
            Field field = FateLockedPlugin.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(plugin, value);
        }
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import java.util.Arrays;
import java.util.Collection;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

@RunWith(Parameterized.class)
public class GuardedActionFactoryTravelDestinationIsolationTest
{
    private final GuardedActionFactory factory = new GuardedActionFactory();
    private final Client client = mock(Client.class);
    private final String option;
    private final String target;
    private final GuardedAction.Kind kind;
    private final CanonicalChunk destination;

    public GuardedActionFactoryTravelDestinationIsolationTest(String name,
        String option, String target, GuardedAction.Kind kind,
        CanonicalChunk destination)
    {
        this.option = option;
        this.target = target;
        this.kind = kind;
        this.destination = destination;
    }

    @Parameterized.Parameters(name = "{0}")
    public static Collection<Object[]> cases()
    {
        return Arrays.asList(new Object[][] {
            unknown("lunar-isle", "Teleport", "Lunar Isle"),
            unknown("zanaris", "Travel", "Fairy ring — Zanaris"),
            unknown("prifddinas", "Travel", "Spirit tree — Prifddinas"),
            unknown("lovakengj", "Travel", "Mine cart — Lovakengj"),
            unknown("nardah", "Pay-fare", "Magic carpet to Nardah"),
            unknown("taverley", "Travel", "Balloon — Taverley"),
            unknown("eagles-peak", "Travel", "Eagle — Eagles' Peak"),
            unknown("nightmare-zone", "Minigame teleport", "Nightmare Zone"),
            unknown("hunter-guild", "Travel", "Quetzal — Hunter Guild"),
            known("port-khazard-existing-legacy-match", "Charter", "Port Khazard", 41, 49)
        });
    }

    @Test
    public void preservesThePreTaskSevenLegacyClassification()
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        when(entry.getItemId()).thenReturn(-1);

        GuardedAction action = factory.from(entry, client);

        assertEquals(kind, action.getKind());
        if (destination == null)
        {
            assertNull(action.getChunk());
        }
        else
        {
            assertEquals(destination, action.getChunk());
        }
    }

    private static Object[] unknown(String name, String option, String target)
    {
        return new Object[] { name, option, target, GuardedAction.Kind.UNKNOWN, null };
    }

    private static Object[] known(String name, String option, String target, int cx, int cy)
    {
        return new Object[] { name, option, target, GuardedAction.Kind.TELEPORT,
            new CanonicalChunk(cx, cy) };
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class StrictModePauseTest
{
    @Test
    public void pausesForExactlySixtySeconds()
    {
        MutableClock clock = new MutableClock();
        StrictModePause pause = new StrictModePause(clock);
        pause.pauseFor(Duration.ofSeconds(60));
        assertEquals(60, pause.remainingSeconds());
        clock.advance(Duration.ofSeconds(17));
        assertEquals(43, pause.remainingSeconds());
        clock.advance(Duration.ofSeconds(43));
        assertFalse(pause.isPaused());
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration) { now = now.plus(duration); }
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

package com.fatelocked.guardian;

import com.google.gson.Gson;
import org.junit.Test;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StrictModeAuditLogTest
{
    @Test
    public void twoClientsKeepEachOthersEntries() throws Exception
    {
        Path file = Files.createTempDirectory("fate-strict-log").resolve("events.json");
        StrictModeAuditLog main = new StrictModeAuditLog(new Gson(), file);
        StrictModeAuditLog second = new StrictModeAuditLog(new Gson(), file);

        main.append(new StrictModeAuditEntry(1, "TRAVEL", "from-main", "50,50", "locked"));
        second.append(new StrictModeAuditEntry(2, "TRAVEL", "from-second", "50,50", "locked"));

        StrictModeAuditLog reloaded = new StrictModeAuditLog(new Gson(), file);
        assertEquals("from-second", reloaded.recent(2).get(0).getTarget());
        assertEquals("from-main", reloaded.recent(2).get(1).getTarget());
    }

    @Test
    public void aDamagedLogIsKeptAsideNotWrittenOver() throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-log");
        Path file = directory.resolve("events.json");
        Files.writeString(file, "{damaged");

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        log.append(new StrictModeAuditEntry(1, "TRAVEL", "goblin", "50,50", "locked"));

        assertEquals(1, new StrictModeAuditLog(new Gson(), file).recent(10).size());
        try (java.util.stream.Stream<Path> files = Files.list(directory))
        {
            Path kept = files.filter(path -> path.getFileName().toString()
                .startsWith("events.json.corrupt-")).findFirst().orElse(null);
            assertTrue("the damaged log was kept", kept != null);
            assertEquals("{damaged", Files.readString(kept));
        }
    }

    @Test
    public void persistsOnlyNewestHundredWithoutSensitiveFields() throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-log");
        Path file = directory.resolve("events.json");
        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        for (int i = 0; i < 101; i++)
        {
            log.append(new StrictModeAuditEntry(
                i, "TRAVEL", "goblin-" + i, "50,50", "locked",
                "BLOCKED", false, i == 100));
        }

        StrictModeAuditLog reloaded = new StrictModeAuditLog(new Gson(), file);
        assertEquals(100, reloaded.recent(200).size());
        StrictModeAuditEntry latest = reloaded.recent(1).get(0);
        assertEquals("goblin-100", latest.getTarget());
        assertEquals("BLOCKED", latest.getOutcome());
        assertFalse(latest.isPaused());
        assertTrue(latest.isAlternativeAvailable());
        String json = Files.readString(file);
        assertFalse(json.contains("account"));
        assertFalse(json.contains("inventory"));
        assertFalse(json.contains("chat"));
        assertFalse(json.contains("token"));
        assertFalse(json.contains("route"));
    }

    @Test
    public void loadsSafeLegacyEntriesAsBlockedWithoutLosingFields()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-legacy");
        Path file = directory.resolve("events.json");
        try (InputStream input = getClass().getClassLoader()
            .getResourceAsStream("audit/strict-mode-events-v1.json"))
        {
            Files.copy(input, file);
        }

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        StrictModeAuditEntry entry = log.recent(1).get(0);

        assertEquals(1721815200000L, entry.getTimestamp());
        assertEquals("OBJECT", entry.getActionKind());
        assertEquals("Ancient gate", entry.getTarget());
        assertEquals("50,50", entry.getChunk());
        assertEquals("is locked", entry.getReason());
        assertEquals("BLOCKED", entry.getOutcome());
        assertFalse(entry.isPaused());
        assertFalse(entry.isAlternativeAvailable());
    }

    @Test
    public void normalizedLegacyBlockRemainsVisibleInRecentPreventedLines()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-visible");
        Path file = directory.resolve("events.json");
        try (InputStream input = getClass().getClassLoader()
            .getResourceAsStream("audit/strict-mode-events-v1.json"))
        {
            Files.copy(input, file);
        }
        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);

        assertEquals(
            Collections.singletonList("Ancient gate \u2014 is locked"),
            StrictModeAuditPresenter.recentPrevented(log.recent(5)));
    }

    @Test
    public void doesNotPromoteSensitiveOrPartialRecordsToLegacyBlocks()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-malformed");
        Path file = directory.resolve("events.json");
        Files.writeString(file,
            "{\"entries\":["
                + "{\"timestamp\":1,\"actionKind\":\"OBJECT\","
                + "\"target\":\"Gate\",\"chunk\":\"50,50\","
                + "\"reason\":\"locked\",\"account\":\"secret\"},"
                + "{\"timestamp\":2,\"actionKind\":\"TRAVEL\","
                + "\"target\":\"Walk here\",\"chunk\":\"51,51\","
                + "\"reason\":\"locked\",\"paused\":true},"
                + "{\"timestamp\":\"3\",\"actionKind\":42,"
                + "\"target\":99,\"chunk\":\"51,51\","
                + "\"reason\":\"locked\"}]}"
        );

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);

        assertTrue(log.recent(10).isEmpty());
    }
}

