public class GuardedActionFactoryTest
{
    private final GuardedActionFactory factory = new GuardedActionFactory();
    private final Client client = mock(Client.class);

    @Test
    public void normalizesNpcAndBankActors()
    {
        NPC npc = mock(NPC.class);
        when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
        MenuEntry attack = entry("Attack", "<col=ffff00>Goblin</col>");
        when(attack.getNpc()).thenReturn(npc);
        assertEquals(GuardedAction.Kind.NPC,
            factory.from(attack, client).getKind());
        assertEquals("goblin", factory.from(attack, client).getTarget());

        MenuEntry bank = entry("Bank", "Banker");
        when(bank.getNpc()).thenReturn(npc);
        assertEquals(GuardedAction.Kind.BANK,
            factory.from(bank, client).getKind());
    }

    @Test
    public void walkingHasNoDestinationWhileTeleportAndEquipmentAreRecognized()
    {
        // "Walk here" carries viewport pixel coordinates, not a scene tile,
        // so it is never given a chunk (and never tagged).
        MenuEntry walk = entry("Walk here", "");
        when(walk.getType()).thenReturn(MenuAction.WALK);
        when(walk.getParam0()).thenReturn(10);
        when(walk.getParam1()).thenReturn(20);
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(walk, client).getKind());
        assertNull(factory.from(walk, client).getChunk());

        MenuEntry teleport = entry("Teleport", "Falador");
        assertEquals(GuardedAction.Kind.TELEPORT,
            factory.from(teleport, client).getKind());

        MenuEntry wield = entry("Wield", "Abyssal whip");
        when(wield.getItemId()).thenReturn(4151);
        assertEquals(GuardedAction.Kind.EQUIPMENT,
            factory.from(wield, client).getKind());
        assertEquals(Integer.valueOf(4151),
            factory.from(wield, client).getItemId());
    }

    @Test
    public void examineAndUnrelatedWidgetsStayUnknown()
    {
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(entry("Examine", "Goblin"), client).getKind());
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(entry("Continue", ""), client).getKind());
    }

    @Test
    public void newNonTeleportTransportFormsRemainUnknownUntilTravelGuardianIntegrates()
    {
        String[] transports = {
            "mine cart", "magic carpet", "balloon", "eagle"
        };
        for (String transport : transports)
        {
            assertEquals(GuardedAction.Kind.UNKNOWN,
                factory.from(entry("Travel via " + transport, "Falador"), client).getKind());
        }
    }

    @Test
    public void minigameTeleportRetainsLegacyTeleportClassification()
    {
        assertEquals(GuardedAction.Kind.TELEPORT,
            factory.from(entry("Travel via minigame teleport", "Falador"), client).getKind());
    }

    private static MenuEntry entry(String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        when(entry.getItemId()).thenReturn(-1);
        return entry;
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class StrictModeReadinessTest
{
    @Test
    public void activeOnlyWhenEveryTrustFactHolds()
    {
        StrictModeReadiness ready = evaluate(true, false, true, "Nubles", "Nubles", true, true);
        assertEquals(StrictModeReadiness.State.ACTIVE, ready.getState());
        assertNull(ready.getReason());
    }

    @Test
    public void offAndPausedNeedNoReason()
    {
        assertEquals(StrictModeReadiness.State.OFF,
            evaluate(false, false, false, null, null, false, false).getState());
        StrictModeReadiness paused = evaluate(true, true, false, null, null, false, false);
        assertEquals(StrictModeReadiness.State.PAUSED, paused.getState());
        assertNull(paused.getReason());
    }

    @Test
    public void inactiveNamesTheFirstMissingFact()
    {
        assertInactive("no tracker rules are loaded",
            evaluate(true, false, false, "Nubles", "Nubles", true, true));
        assertInactive("the tracker profile has no linked account",
            evaluate(true, false, true, "  ", "Nubles", false, true));
        assertInactive("you are not logged in",
            evaluate(true, false, true, "Nubles", null, false, true));
        assertInactive("the profile is for Nubles; you're logged in as Zezima",
            evaluate(true, false, true, " Nubles ", "Zezima", false, true));
        assertInactive("the rules are more than 15 minutes old",
            evaluate(true, false, true, "Nubles", "Nubles", true, false));
    }

    private static void assertInactive(String reason, StrictModeReadiness readiness)
    {
        assertEquals(StrictModeReadiness.State.INACTIVE, readiness.getState());
        assertEquals(reason, readiness.getReason());
    }

    private static StrictModeReadiness evaluate(
        boolean enabled, boolean paused, boolean rules, String bound, String player,
        boolean matches, boolean fresh)
    {
        return StrictModeReadiness.evaluate(enabled, paused, rules, bound, player, matches, fresh);
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

public class StrictModeClickHandlerTest
{
    @Test
    public void travelConsumesExactlyOnceOnlyForFreshExactLockedDecisions()
    {
        StrictModeClickHandler handler =
            new StrictModeClickHandler(new StrictModeGuard());
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        MenuOptionClicked lockedEvent = mock(MenuOptionClicked.class);
        handler.handleTravel(lockedEvent, exact, locked, enabled());
        verify(lockedEvent, times(1)).consume();

        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.ALLOWED),
            enabled());
        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.NOT_READY),
            enabled());
        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.UNKNOWN),
            enabled());
        assertNotConsumed(handler, exact, locked, disabled());
        assertNotConsumed(handler, exact, locked, paused());
        assertNotConsumed(handler, exact, locked, stale());
        assertNotConsumed(handler, exact, locked, wrongAccount());
        assertNotConsumed(handler, unknownTravel(), locked, enabled());
        assertNotConsumed(handler, null, locked, enabled());
        assertNotConsumed(handler, exact, null, enabled());
        assertNotConsumed(handler, exact, locked, null);
    }

    private static void assertNotConsumed(
        StrictModeClickHandler handler,
        TravelAction action,
        TravelDecision decision,
        GuardContext context)
    {
        MenuOptionClicked event = mock(MenuOptionClicked.class);
        GuardResult result = handler.handleTravel(
            event, action, decision, context);
        assertEquals(GuardResult.Outcome.ALLOW,
            result.getOutcome());
        verify(event, never()).consume();
    }

    private static TravelAction exactTravel()
    {
        return new TravelAction(
            TravelAction.Family.SPELL_OR_ITEM, "named-teleport", "Teleport falador", null,
            new CanonicalChunk(51, 51), null,
            TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownTravel()
    {
        return new TravelAction(
            TravelAction.Family.UNKNOWN, "unknown", "Unknown", null,
            null, null, TravelAction.Confidence.UNKNOWN);
    }

    private static TravelDecision travelDecision(PermissionStatus status)
    {
        return new TravelDecision(status, "Destination", "not unlocked");
    }

    private static GuardContext enabled()
    {
        return new GuardContext(true, false, true, true, null);
    }

    private static GuardContext disabled()
    {
        return new GuardContext(false, false, true, true, null);
    }

    private static GuardContext paused()
    {
        return new GuardContext(true, true, true, true, null);
    }

    private static GuardContext stale()
    {
        return new GuardContext(true, false, true, false, null);
    }

    private static GuardContext wrongAccount()
    {
        return new GuardContext(true, false, false, true, null);
