        when(rules.areaLabel(VARROCK)).thenReturn("varrock");
        when(rules.areaLabel(FALADOR)).thenReturn("Falador");
        when(availability.hasAnyItem(setOf(8007))).thenReturn(true);
        when(availability.hasAnyItem(setOf(8009))).thenReturn(true);

        Optional<TravelAlternative> result = new TravelAlternativeFinder(
            Arrays.asList(
                tablet("falador", "Falador", FALADOR, 8009),
                tablet("varrock", "Varrock", VARROCK, 8007)))
            .find(exactAction(new CanonicalChunk(49, 53)), rules, availability);

        assertTrue(result.isPresent());
        assertEquals("Varrock", result.get().getLabel());
        assertEquals(VARROCK, result.get().getDestination());
    }

    @Test
    public void rejectsLockedUnknownNotReadyAndUnavailableAlternatives()
    {
        CanonicalChunk locked = new CanonicalChunk(50, 53);
        CanonicalChunk unknown = new CanonicalChunk(50, 52);
        CanonicalChunk notReady = new CanonicalChunk(50, 51);
        CanonicalChunk absent = new CanonicalChunk(50, 50);
        when(rules.entry(locked)).thenReturn(decision(PermissionStatus.LOCKED));
        when(rules.entry(unknown)).thenReturn(decision(PermissionStatus.UNKNOWN));
        when(rules.entry(notReady)).thenReturn(decision(PermissionStatus.NOT_READY));
        when(rules.entry(absent)).thenReturn(allowed("Lumbridge"));
        when(availability.hasAnyItem(any())).thenReturn(false);

        List<TravelAlternative> catalog = Arrays.asList(
            tablet("locked", "Locked", locked, 8007),
            tablet("unknown", "Unknown", unknown, 8008),
            tablet("not-ready", "Not ready", notReady, 8009),
            tablet("absent", "Absent", absent, 8010));

        assertFalse(new TravelAlternativeFinder(catalog)
            .find(exactAction(new CanonicalChunk(51, 53)), rules, availability)
            .isPresent());
    }

    @Test
    public void tabletMobilityMustBeExplicitlyAllowed()
    {
        TravelAlternative candidate =
            TravelAlternativeCatalog.alternatives().get(0);
        for (TravelAlternative tablet :
            TravelAlternativeCatalog.alternatives())
        {
            assertEquals("Teleport Tablets", tablet.getRequiredUnlock());
        }
        when(rules.entry(candidate.getDestination()))
            .thenReturn(allowed("Varrock"));
        when(availability.hasAnyItem(candidate.getRequiredItemIds()))
            .thenReturn(true);

        when(rules.mobility("Teleport Tablets")).thenReturn(null);
        assertFalse(new TravelAlternativeFinder(
            Collections.singletonList(candidate))
            .find(exactAction(VARROCK), rules, availability).isPresent());

        for (PermissionStatus status : Arrays.asList(
            PermissionStatus.UNKNOWN,
            PermissionStatus.NOT_READY,
            PermissionStatus.LOCKED))
        {
            when(rules.mobility("Teleport Tablets"))
                .thenReturn(decision(status));
            assertFalse(new TravelAlternativeFinder(
                Collections.singletonList(candidate))
                .find(exactAction(VARROCK), rules, availability).isPresent());
        }

        when(rules.mobility("Teleport Tablets"))
            .thenReturn(decision(PermissionStatus.ALLOWED));
        assertEquals(candidate, new TravelAlternativeFinder(
            Collections.singletonList(candidate))
            .find(exactAction(VARROCK), rules, availability).get());
    }

    @Test
    public void requiresEveryDeclaredLocalRequirement()
    {
        TravelAlternative alternative = new TravelAlternative(
            "verified", "Verified", VARROCK, "Teleport Tablets", setOf(8007),
            Skill.MAGIC, 45, 0);
        TravelAlternativeFinder finder = new TravelAlternativeFinder(
            Collections.singletonList(alternative));
        when(rules.entry(VARROCK)).thenReturn(allowed("Varrock"));
        when(availability.hasAnyItem(setOf(8007))).thenReturn(true);

        when(availability.realLevel(Skill.MAGIC)).thenReturn(44);
        when(availability.spellbook()).thenReturn(0);
        assertFalse(finder.find(exactAction(VARROCK), rules, availability).isPresent());

        when(availability.realLevel(Skill.MAGIC)).thenReturn(45);
        when(availability.spellbook()).thenReturn(1);
        assertFalse(finder.find(exactAction(VARROCK), rules, availability).isPresent());

        when(availability.spellbook()).thenReturn(0);
        assertEquals(alternative,
            finder.find(exactAction(VARROCK), rules, availability).get());
    }

    @Test
    public void adjacentRankOutranksOtherBeforeDistance()
    {
        CanonicalChunk destination = new CanonicalChunk(50, 50);
        CanonicalChunk adjacent = new CanonicalChunk(50, 51);
        TravelAlternative zeroDistanceOther = tablet(
            "a-zero-distance", "Zero distance other", destination, 8008);
        TravelAlternative adjacentCandidate = tablet(
            "z-adjacent", "Adjacent", adjacent, 8007);
        when(rules.entry(destination)).thenReturn(allowed("Destination"));
        when(rules.entry(adjacent)).thenReturn(allowed("Adjacent"));
        when(availability.hasAnyItem(any())).thenReturn(true);

        Optional<TravelAlternative> result = new TravelAlternativeFinder(
            Arrays.asList(zeroDistanceOther, adjacentCandidate))
            .find(exactAction(destination), rules, availability);

        assertEquals(adjacentCandidate, result.get());
    }

    @Test
    public void normalizedStableIdBreaksEqualRankAndDistanceTies()
    {
        CanonicalChunk destination = new CanonicalChunk(50, 50);
        CanonicalChunk east = new CanonicalChunk(51, 50);
        CanonicalChunk north = new CanonicalChunk(50, 51);
        TravelAlternative catalogFirst = tablet(
            " Z-last-ID ", "Catalog first", east, 8008);
        TravelAlternative lexicographicFirst = tablet(
            "a-first-id", "Lexicographic first", north, 8007);
        when(rules.entry(east)).thenReturn(allowed("East"));
        when(rules.entry(north)).thenReturn(allowed("North"));
        when(availability.hasAnyItem(any())).thenReturn(true);

        Optional<TravelAlternative> result = new TravelAlternativeFinder(
            Arrays.asList(catalogFirst, lexicographicFirst))
            .find(exactAction(destination), rules, availability);

        assertEquals(lexicographicFirst, result.get());
    }

    @Test
    public void catalogAndAlternativesAreImmutableCheckedData()
    {
        List<TravelAlternative> alternatives = TravelAlternativeCatalog.alternatives();
        assertEquals(6, alternatives.size());
        assertEquals("varrock-tablet", alternatives.get(0).getId());
        assertEquals("watchtower-tablet", alternatives.get(5).getId());
        assertThrows(UnsupportedOperationException.class,
            () -> alternatives.add(alternatives.get(0)));

        Set<Integer> mutableIds = new LinkedHashSet<>(setOf(8007));
        TravelAlternative copied = new TravelAlternative(
            "copy", "Copy", VARROCK, "Teleport Tablets", mutableIds,
            null, 0, null);
        mutableIds.clear();
        assertEquals(setOf(8007), copied.getRequiredItemIds());
        assertThrows(UnsupportedOperationException.class,
            () -> copied.getRequiredItemIds().add(8008));
    }

    @Test
    public void unresolvedInputsAndEmptyItemRequirementsNeverProduceAGuess()
    {
        when(rules.entry(VARROCK)).thenReturn(allowed("Varrock"));
        when(availability.hasAnyItem(any())).thenReturn(true);
        TravelAlternativeFinder finder = new TravelAlternativeFinder(
            Collections.singletonList(new TravelAlternative(
                "none", "None", VARROCK, "Teleport Tablets",
                Collections.emptySet(), null, 0, null)));

        assertFalse(finder.find(null, rules, availability).isPresent());
        assertFalse(finder.find(unknownAction(), rules, availability).isPresent());
        assertFalse(finder.find(exactAction(VARROCK), null, availability).isPresent());
        assertFalse(finder.find(exactAction(VARROCK), rules, null).isPresent());
        assertFalse(finder.find(exactAction(VARROCK), rules, availability).isPresent());
    }

    @Test
    public void finderExposesDataSelectionOnly()
    {
        for (Method method : TravelAlternativeFinder.class.getDeclaredMethods())
        {
            assertFalse(method.getName().matches(
                "(?i).*(click|move|invoke|interact|menu|activate).*"));
            assertFalse(Client.class.isAssignableFrom(method.getReturnType()));
            for (Class<?> parameterType : method.getParameterTypes())
            {
                assertFalse(Client.class.isAssignableFrom(parameterType));
            }
        }
        assertNull(TravelAlternative.class.getSuperclass().getSuperclass());
    }

    private static TravelAlternative tablet(
        String id, String label, CanonicalChunk destination, int itemId)
    {
        return new TravelAlternative(
            id, label, destination, "Teleport Tablets", setOf(itemId),
            null, 0, null);
    }

    private static TravelAction exactAction(CanonicalChunk destination)
    {
        return new TravelAction(
            TravelAction.Family.WALK, "walk", "Walk here",
            new CanonicalChunk(49, 50), destination, null,
            TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownAction()
    {
        return new TravelAction(
            TravelAction.Family.UNKNOWN, "unknown", "Unknown",
            new CanonicalChunk(49, 50), null, null,
            TravelAction.Confidence.UNKNOWN);
    }

    private static Set<Integer> setOf(Integer... values)
    {
        return Collections.unmodifiableSet(
            new LinkedHashSet<>(Arrays.asList(values)));
    }

    private static RuleDecision allowed(String label)
    {
        return new RuleDecision(PermissionStatus.ALLOWED, label, null);
    }

    private static RuleDecision decision(PermissionStatus status)
    {
        return new RuleDecision(status, status.name(), null);
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.guardian.GuardContext;
import com.fatelocked.guardian.StrictModeClickHandler;
import com.fatelocked.guardian.StrictModeGuard;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;
import org.mockito.MockedStatic;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TravelGuardianCoordinatorTest
{
    private static final CanonicalChunk ORIGIN = new CanonicalChunk(50, 51);
    /** Where "Teleport" on "Falador" lands: the exact-travel example below. */
    private static final CanonicalChunk DESTINATION = new CanonicalChunk(46, 52);

    private final Client client = mock(Client.class);
    private final TravelAvailability availability = mock(TravelAvailability.class);
    private final TravelBlockNoticeStore noticeStore = new TravelBlockNoticeStore(
        Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
    private final TravelAlternativeFinder finder = mock(TravelAlternativeFinder.class);
    private final TravelGuardianCoordinator coordinator = new TravelGuardianCoordinator(
        new TravelActionResolver(),
        new TravelRuleEvaluator(),
        finder,
        noticeStore,
        new StrictModeClickHandler(new StrictModeGuard()));

    @Test
    public void provenLockedTravelIsConsumedEachTimeButExplainedAndRecordedOnce()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult first = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);
        TravelGuardianResult repeated = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        verify(click, times(2)).consume();
        assertEquals("Travel blocked \u2014 Teleport falador",
            noticeStore.current().get().getHeadline());
        assertTrue(first.isWriteChat());
        assertFalse(repeated.isWriteChat());
        assertTrue(first.isWriteBlockedAudit());
        assertFalse(repeated.isWriteBlockedAudit());
        assertFalse(first.isWritePausedAudit());
    }

    @Test
    public void pausedTravelIsAllowedAndRecordedOnceForLocalAudit()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, true, true, true, rules), rules, availability);
        TravelGuardianResult repeated = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, true, true, true, rules), rules, availability);

        verify(click, never()).consume();
        assertFalse(noticeStore.current().isPresent());
        assertFalse(result.isWriteChat());
        assertFalse(result.isWriteBlockedAudit());
        assertTrue(result.isWritePausedAudit());
        assertFalse(repeated.isWritePausedAudit());
    }

    @Test
    public void pausedTravelTheRulesAllowIsNotRecorded()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.ALLOWED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, true, true, true, rules), rules, availability);

        verify(click, never()).consume();
        assertFalse(result.isWriteChat());
        assertFalse(result.isWriteBlockedAudit());
        assertFalse(result.isWritePausedAudit());
    }

    @Test
    public void strictModeOffLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(false, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
    }

    @Test
    public void staleRulesLeaveTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, false, rules), rules, availability);

        assertFailOpen(click, result);
    }

    @Test
    public void wrongAccountLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, false, true, rules), rules, availability);

        assertFailOpen(click, result);
    }

    @Test
    public void legacyRulesLeaveTravelUnconsumedAndUnrecorded() throws Exception
    {
        MenuOptionClicked click = namedTeleportClick("Teleport", "Falador");
        FateRuleEngine legacy = new FateRuleEngine(
            fixture("bundles/v3-standard.json"), true, false);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, legacy), legacy, availability);

        assertFailOpen(click, result);
    }

    @Test
    public void unknownTravelLeavesTheClickForTheGenericPath()
    {
        MenuOptionClicked click = namedTeleportClick("Continue", "");
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
    }

    @Test
    public void genericTravelWordsWithoutADestinationStayFailOpen()
    {
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        assertGenericTravelWordFailsOpen("Travel", rules);
        assertGenericTravelWordFailsOpen("Enter", rules);
        assertGenericTravelWordFailsOpen("Teleport", rules);
    }

    @Test
    public void mappedNonActivationActionsStayUnknownAndUnconsumed()
    {
        FateRuleEngine rules = rulesAt(
            new CanonicalChunk(50, 53), PermissionStatus.LOCKED);

        assertMappedNonActivationFailsOpen(
            "Drop", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Examine", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Destroy", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Check", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Configure", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Cancel", "Varrock teleport", rules);
    }

    @Test
    public void notReadyDestinationLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.NOT_READY);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(PermissionStatus.UNKNOWN, result.getDecision().getStatus());
    }

    @Test
    public void walkingIsNeverConsumedOrRecorded()
    {
        // Every chunk is locked, and walking is still left alone.
        FateRuleEngine rules = lockedEverywhere();
        MenuOptionClicked click = walkClick();

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }

    @Test
    public void doorsAndLaddersAreNeverConsumedOrRecorded()
    {
        FateRuleEngine rules = lockedEverywhere();
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn("Climb-down");
        when(entry.getTarget()).thenReturn("Ladder");
        when(entry.getType()).thenReturn(MenuAction.GAME_OBJECT_FIRST_OPTION);
        when(entry.getParam0()).thenReturn(10);
        when(entry.getParam1()).thenReturn(20);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
    }

    @Test
    public void alternativeLookupFailureNeverCancelsAProvenBlock()
    {
        MenuOptionClicked click = travelClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);
        when(finder.find(any(), any(), any()))
            .thenThrow(new IllegalStateException("inventory unavailable"));

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        verify(click).consume();
        assertTrue(result.isWriteBlockedAudit());
        assertNull(result.getAlternative());
        assertNull(noticeStore.current().get().getAlternative());
    }

    private void assertFailOpen(
        MenuOptionClicked click, TravelGuardianResult result)
    {
        verify(click, never()).consume();
        assertFalse(noticeStore.current().isPresent());
        assertFalse(result.isWriteChat());
        assertFalse(result.isWriteBlockedAudit());
        assertFalse(result.isWritePausedAudit());
    }

    private MenuOptionClicked walkClick()
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn("Walk here");
        when(entry.getTarget()).thenReturn("");
        when(entry.getType()).thenReturn(MenuAction.WALK);
        when(entry.getParam0()).thenReturn(10);
        when(entry.getParam1()).thenReturn(20);
        when(client.getPlane()).thenReturn(0);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    /** An exact travel click: "Teleport" on "Falador" lands in DESTINATION. */
    private static MenuOptionClicked travelClick()
    {
        return namedTeleportClick("Teleport", "Falador");
    }

    private static FateRuleEngine lockedEverywhere()
    {
        FateRuleEngine rules = mock(FateRuleEngine.class);
        when(rules.entry(any())).thenReturn(
            new RuleDecision(PermissionStatus.LOCKED, "Locked destination", null));
        return rules;
    }

    private static MenuOptionClicked namedTeleportClick(
        String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    private void assertGenericTravelWordFailsOpen(String option, FateRuleEngine rules)
    {
        MenuOptionClicked click = namedTeleportClick(option, "New destination");
        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }
    private void assertMappedNonActivationFailsOpen(
        String option, String target, FateRuleEngine rules)
    {
        MenuOptionClicked click = namedTeleportClick(option, target);
        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Family.UNKNOWN,
            result.getAction().getFamily());
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }
    private MockedStatic<WorldPoint> walkDestination()
    {
        return walkDestination(DESTINATION);
    }

    private MockedStatic<WorldPoint> walkDestination(CanonicalChunk destination)
    {
        MockedStatic<WorldPoint> points = mockStatic(WorldPoint.class);
        points.when(() -> WorldPoint.fromScene(client, 10, 20, 0))
            .thenReturn(new WorldPoint(destination.getCx() << 6,
                destination.getCy() << 6, 0));
        return points;
    }

    private static GuardContext context(
        boolean enabled,
        boolean paused,
        boolean accountMatches,
        boolean freshRules,
        FateRuleEngine rules)
    {
        return new GuardContext(
            enabled, paused, accountMatches, freshRules, rules);
    }

    private static FateRuleEngine rules(PermissionStatus status)
    {
        return rulesAt(DESTINATION, status);
    }

    private static FateRuleEngine rulesAt(
        CanonicalChunk destination, PermissionStatus status)
    {
        FateRuleEngine rules = mock(FateRuleEngine.class);
        when(rules.entry(destination)).thenReturn(
            new RuleDecision(status, "Locked destination", null));
        return rules;
    }

    private FateLockedBundle fixture(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            return FateLockedBundle.loadFromJson(
                new Gson(),
                new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
    }
}

package com.fatelocked.guardian.travel;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class RuneLiteTravelAvailabilityTest
{
    private final Client client = mock(Client.class);
    private final ItemContainer inventory = mock(ItemContainer.class);
    private final ItemContainer equipment = mock(ItemContainer.class);
    private final RuneLiteTravelAvailability availability =
        new RuneLiteTravelAvailability(client);

    @Test
    public void readsOnlyCarriedAndEquippedItems()
    {
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        when(client.getItemContainer(InventoryID.WORN)).thenReturn(equipment);
        when(inventory.getItems()).thenReturn(new Item[]{new Item(8007, 1)});
        when(equipment.getItems()).thenReturn(new Item[]{new Item(8009, 1)});

        assertTrue(availability.hasAnyItem(setOf(8007)));
        assertTrue(availability.hasAnyItem(setOf(8009)));
        assertFalse(availability.hasAnyItem(setOf(8010)));
        verify(client, never()).getItemContainer(InventoryID.BANK);
    }

    @Test
    public void missingOrUnreadableContainersFailClosed()
    {
        when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
        when(client.getItemContainer(InventoryID.WORN)).thenReturn(equipment);
        when(equipment.getItems()).thenReturn(null);

        assertFalse(availability.hasAnyItem(setOf(8007)));
        assertFalse(availability.hasAnyItem(new LinkedHashSet<>()));
        assertFalse(availability.hasAnyItem(null));
    }

    @Test
    public void readsRealLevelsAndCurrentSpellbookDirectly()
    {
        when(client.getRealSkillLevel(Skill.MAGIC)).thenReturn(67);
        when(client.getVarbitValue(VarbitID.SPELLBOOK)).thenReturn(2);

        assertEquals(67, availability.realLevel(Skill.MAGIC));
        assertEquals(2, availability.spellbook());
    }

    private static Set<Integer> setOf(Integer... values)
    {
        return new LinkedHashSet<>(Arrays.asList(values));
    }
}

package com.fatelocked.guardian.travel;

import org.junit.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TravelBlockNoticeStoreTest
{
    @Test
    public void noticeExpiresAtTheFourSecondBoundaryAndChatDeduplicatesForTenSeconds()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("fairy-rings:canifis", "Travel blocked - Fairy ring to Canifis",
            "Morytania is locked", "Varrock teleport tablet");

        assertTrue(store.current().isPresent());
        assertTrue(store.shouldWriteChat("fairy-rings:canifis"));
        assertFalse(store.shouldWriteChat("fairy-rings:canifis"));

        clock.advance(Duration.ofSeconds(4));
        assertFalse(store.current().isPresent());

        clock.advance(Duration.ofSeconds(5).plusMillis(999));
        assertFalse(store.shouldWriteChat("fairy-rings:canifis"));
        clock.advance(Duration.ofMillis(1));
        assertTrue(store.shouldWriteChat("fairy-rings:canifis"));
    }

    @Test
    public void repeatedShowRefreshesOnlyTheBannerExpiry()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        assertTrue(store.shouldWriteChat("walk:locked"));
        clock.advance(Duration.ofSeconds(3));

        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        clock.advance(Duration.ofSeconds(1));
        assertTrue(store.current().isPresent());
        assertFalse(store.shouldWriteChat("walk:locked"));

        clock.advance(Duration.ofSeconds(3));
        assertFalse(store.current().isPresent());
        clock.advance(Duration.ofSeconds(3));
        assertTrue(store.shouldWriteChat("walk:locked"));
    }

    @Test
    public void chatFingerprintsAreBoundedToThirtyTwoEntries()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        for (int index = 0; index < 33; index++)
        {
            assertTrue(store.shouldWriteChat("fingerprint-" + index));
        }

        assertTrue(store.shouldWriteChat("fingerprint-0"));
        assertFalse(store.shouldWriteChat("fingerprint-32"));
    }

    @Test
    public void noticeIsAnImmutableSnapshotWithAnExactExpiry()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("boat:port", "Travel blocked - Boat", "Locked", null);

        TravelBlockNotice notice = store.current().get();
        assertEquals("boat:port", notice.getFingerprint());
        assertEquals("Travel blocked - Boat", notice.getHeadline());
        assertEquals("Locked", notice.getReason());
        assertEquals(Instant.parse("2026-07-24T10:00:04Z"), notice.getExpiresAt());
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration)
        {
            now = now.plus(duration);
        }

        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PluginSessionTest
{
    @Test
    public void guardedWorkRunsWhileTheSessionLasts()
    {
        PluginSession session = new PluginSession();
        AtomicInteger runs = new AtomicInteger();

        session.guard(runs::incrementAndGet).run();

        assertTrue(session.isActive());
        assertEquals(1, runs.get());
    }

    @Test
    public void workQueuedBeforeTheSessionEndedDoesNothing()
    {
        PluginSession session = new PluginSession();
        AtomicInteger runs = new AtomicInteger();
        Runnable queued = session.guard(runs::incrementAndGet);

        session.end();
        queued.run();

        assertFalse(session.isActive());
        assertEquals(0, runs.get());
    }

    @Test
    public void aLaterStartDoesNotReviveWorkQueuedByAnEarlierOne()
    {
        PluginSession first = new PluginSession();
        AtomicInteger runs = new AtomicInteger();
        Runnable queued = first.guard(runs::incrementAndGet);
        first.end();

        PluginSession second = new PluginSession();
        queued.run();

        assertTrue(second.isActive());
        assertEquals(0, runs.get());
    }

    @Test
    public void aPluginThatIsNotRunningHasNoActiveSession()
    {
        AtomicInteger runs = new AtomicInteger();

        PluginSession.ended().guard(runs::incrementAndGet).run();

        assertEquals(0, runs.get());
    }
}

