package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.client.config.ConfigManager;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.SocketPolicy;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.time.Clock;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The relay fixture's transport cases, through the real connection
 * controller and a real socket: a reset connection, no answer in time, and
 * a reply larger than any real bundle.
 */
public class RelayTransportFixtureTest
{
    private static final String CODE = "0123456789abcdef0123456789abcdef";

    private final List<String> prepared = new CopyOnWriteArrayList<>();
    private final List<TrackerConnectionSnapshot> published = new CopyOnWriteArrayList<>();
    private MockWebServer server;
    private TrackerConnectionController controller;

    @Before
    public void setUp() throws Exception
    {
        Map<String, String> configuration = new ConcurrentHashMap<>();
        configuration.put(TrackerConnectionSettings.PAIRING_CODE_KEY, CODE);
        configuration.put(FateLockedConfig.NETWORK_ACCESS_KEY, "true");
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString()))
            .thenAnswer(invocation -> configuration.get(invocation.getArgument(1)));

        server = new MockWebServer();
        server.start();
        Interceptor redirectToServer = chain -> {
            Request original = chain.request();
            return chain.proceed(original.newBuilder()
                .url(server.url(original.url().encodedPath()))
                .build());
        };
        OkHttpClient http = new OkHttpClient.Builder()
            .addInterceptor(redirectToServer)
            .readTimeout(500, TimeUnit.MILLISECONDS)
            .build();
        controller = new TrackerConnectionController(
            http, new Gson(), new TrackerConnectionSettings(configManager),
            Clock.systemUTC(), Runnable::run,
            new TrackerConnectionController.RelayBundleImporter<String>()
            {
                @Override
                public TrackerConnectionController.Prepared<String> prepare(String payload)
                {
                    prepared.add(payload);
                    return TrackerConnectionController.Prepared.ok(payload);
                }

                @Override
                public boolean commit(String payload, String version)
                {
                    return true;
                }
            },
            published::add);
    }

    @After
    public void tearDown() throws Exception
    {
        controller.stop();
        server.shutdown();
    }

    @Test
    public void everyTransportCaseIsCovered() throws Exception
    {
        for (JsonElement element : RelayContractFixtureTest.fixture().getAsJsonArray("cases"))
        {
            JsonObject relayCase = element.getAsJsonObject();
            if (!relayCase.get("from").getAsString().equals("transport")) continue;
            String transport = relayCase.get("transport").getAsString();
            assertTrue(relayCase.get("name").getAsString(),
                List.of("reset", "timeout", "oversized").contains(transport));
        }
    }

    @Test
    public void aResetConnectionIsUnreachable() throws Exception
    {
        JsonObject relayCase = transportCase("reset");
        server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AT_START));

        poll(relayCase);

        assertEquals("unreachable", relayCase.get("outcome").getAsString());
        waitFor(this::unreachable);
    }

    @Test
    public void noAnswerInTimeIsUnreachable() throws Exception
    {
        JsonObject relayCase = transportCase("timeout");
        server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));

        poll(relayCase);

        assertEquals("unreachable", relayCase.get("outcome").getAsString());
        waitFor(this::unreachable);
    }

    @Test
    public void aReplyLargerThanAnyRealBundleIsUnreadable() throws Exception
    {
        JsonObject relayCase = transportCase("oversized");
        int bodyBytes = relayCase.get("bodyBytes").getAsInt();
        StringBuilder payload = new StringBuilder(bodyBytes);
        while (payload.length() < bodyBytes) payload.append('x');
        server.enqueue(new MockResponse()
            .setResponseCode(200)
            .addHeader("ETag", "42")
            .setBody("{\"version\":42,\"payload\":\"" + payload + "\"}"));

        poll(relayCase);

        assertEquals("unreadable", relayCase.get("outcome").getAsString());
        waitFor(() -> shown(SyncReason.UNREADABLE.status));
        assertTrue(prepared.isEmpty());
    }

    private void poll(JsonObject relayCase)
    {
        controller.seedAcceptedVersion(relayCase.get("held").getAsString());
        controller.poll();
    }

    private boolean unreachable()
    {
        return shown(SyncReason.UNREACHABLE.status);
    }

    private boolean shown(String offlineMessage)
    {
        return published.stream().anyMatch(snapshot ->
            snapshot.getState() == TrackerConnectionState.OFFLINE
                && offlineMessage.equals(snapshot.getMessage()));
    }

    private static JsonObject transportCase(String transport) throws Exception
    {
        for (JsonElement element : RelayContractFixtureTest.fixture().getAsJsonArray("cases"))
        {
            JsonObject relayCase = element.getAsJsonObject();
            if (relayCase.has("transport")
                && relayCase.get("transport").getAsString().equals(transport))
            {
                return relayCase;
            }
        }
        throw new AssertionError("the relay fixture has no " + transport + " case");
    }

    private static void waitFor(BooleanSupplier condition) throws Exception
    {
        for (int attempt = 0; attempt < 300; attempt++)
        {
            if (condition.getAsBoolean()) return;
            Thread.sleep(10);
        }
        throw new AssertionError("condition was not reached");
    }
}

package com.fatelocked;

import com.fatelocked.panel.LocalTimeText;

import java.time.Instant;
import java.time.ZoneId;

/**
 * What the sidebar shows for the tracker connection: a short status in a
 * tone, one line saying why and what to do about it, and times on the
 * player's own clock. Pure: made from a snapshot, the time now and the
 * player's time zone.
 */
final class SyncView
{
    enum Tone
    {
        GREEN,
        AMBER,
        RED,
        GRAY
    }

    /** The one thing the player can do about the state. */
    enum Action
    {
        /** Nothing: it sorts itself out. */
        NONE,
        /** Press Check now. */
        CHECK_NOW,
        /** Press Connect tracker. */
        CONNECT,
        /** Tick "Enable online sync"; the pairing is kept. */
        ENABLE_SYNC,
        /** Open the web tracker, which sends the rules again. */
        OPEN_TRACKER,
        /** Update Fate Locked in the Plugin Hub. */
        UPDATE_PLUGIN
    }

    final String status;
    final Tone tone;
    /** Why, and what to do; null when the status says it all. */
    final String detail;
    final Action action;
    /** When the relay last delivered or confirmed the rules, or a dash. */
    final String lastSync;
    /** Whether Check now has anything to check: a pairing, with online sync on. */
    final boolean canCheckNow;
    /** What the connect button says and does. */
    final Connect connect;
    /** The code in use, as its last four characters, or a dash. */
    final String pairing;

    /** The connect button's job in each state. */
    enum Connect
    {
        /** No working pairing: pair, asking for consent first if need be. */
        CONNECT("Connect tracker"),
        /** Paired with online sync off: turn it on and use that pairing. */
        TURN_ON_SYNC("Turn on online sync"),
        /** A working pairing: ask, then pair again, keeping it until the new one delivers. */
        REPAIR("Re-pair tracker\u2026"),
        /** A re-pairing is waiting: go back to the working pairing. */
        CANCEL_REPAIR("Cancel re-pairing");

        final String label;

        Connect(String label)
        {
            this.label = label;
        }
    }

    private SyncView(String status, Tone tone, String detail, Action action,
        String lastSync, boolean canCheckNow, Connect connect, String pairing)
    {
        this.pairing = pairing;
        this.status = status;
        this.tone = tone;
        this.detail = detail;
        this.action = action;
        this.lastSync = lastSync;
        this.canCheckNow = canCheckNow;
        this.connect = connect;
    }

    static SyncView of(TrackerConnectionSnapshot snapshot, Instant now, ZoneId zone)
    {
        String lastSync = snapshot.getLastSync() == null
            ? "\u2014" : LocalTimeText.of(snapshot.getLastSync(), now, zone);
        String nextCheck = snapshot.getNextCheck() == null
            ? "" : " Next check at " + LocalTimeText.of(snapshot.getNextCheck(), now, zone) + ".";
        Tone tone = tone(snapshot.getState());
        TrackerConnectionState state = snapshot.getState();
        Action action = state == TrackerConnectionState.CONNECTED
            || state == TrackerConnectionState.OFFLINE
            ? Action.CHECK_NOW : Action.NONE;
        String detail;
        switch (snapshot.getReason())
        {
            case NOT_PAIRED:
                detail = "Press Connect tracker to get your rules from the web tracker.";
                action = Action.CONNECT;
                break;
            case SYNC_OFF:
                detail = "Your pairing is kept. Press Turn on online sync to pick it"
                    + " up again.";
                action = Action.ENABLE_SYNC;
                break;
            case CONFIRM_REPAIR:
                detail = "Confirm the profile in the browser tab RuneLite opened."
                    + " Until it arrives, RuneLite keeps your current pairing.";
                break;
            case GONE:
                detail = "The tracker's owner pressed Disconnect in the web tracker,"
                    + " so it sends no more rules to this pairing. Press Connect"
                    + " tracker to pair again.";
                action = Action.CONNECT;
                break;
            case REPAIR_ABANDONED:
                detail = "No new profile arrived within 10 minutes, so RuneLite kept"
                    + " your current pairing.";
                break;
            case CONFIRM_IN_BROWSER:
                detail = "Confirm the profile in the browser tab RuneLite opened."
                    + " RuneLite checks every few seconds.";
                break;
            case NO_PROFILE:
                detail = "No profile arrived within 10 minutes."
                    + " Press Connect tracker to try again.";
                action = Action.CONNECT;
                break;
            case NO_RECENT_UPDATE:
                detail = "The tracker hasn't sent your rules in the last 24 hours."
                    + " Open the web tracker to send them again.";
                action = Action.OPEN_TRACKER;
                break;
            case OLDER_RULES:
                detail = "The relay sent older rules than yours, so yours stay in use."
                    + " Open the web tracker to send yours again." + nextCheck;
                action = Action.OPEN_TRACKER;
                break;
            case UNREACHABLE:
                detail = "RuneLite couldn't reach the tracker." + nextCheck;
                break;
            case UNREADABLE:
                detail = "Something other than the tracker answered, such as a Wi-Fi"
                    + " sign-in page." + nextCheck;
                break;
            case BUSY:
                detail = "The tracker asked RuneLite to check less often." + nextCheck;
                break;
            case UNAVAILABLE:
                detail = "The tracker had a problem." + nextCheck;
                break;
            case FUTURE_FORMAT:
                detail = "Your tracker sent rules in a newer format than this version"
                    + " of Fate Locked reads. Update it in the Plugin Hub.";
                action = Action.UPDATE_PLUGIN;
                break;
            case INVALID_RULES:
                detail = "The tracker sent rules RuneLite couldn't use."
                    + " Open the web tracker to send them again.";
                action = Action.OPEN_TRACKER;
                break;
            default:
                if (state == TrackerConnectionState.IMPORT_FAILED)
                {
                    detail = "RuneLite couldn't apply the tracker's rules." + nextCheck;
                    action = Action.CHECK_NOW;
                }
                else
                {
                    detail = null;
                }
                break;
        }
        boolean canCheckNow = snapshot.getReason() != SyncReason.NOT_PAIRED
            && snapshot.getReason() != SyncReason.SYNC_OFF
            && snapshot.getReason() != SyncReason.GONE;
        String pairing = snapshot.getPairingEnding() == null
            ? "\u2014" : "\u2026" + snapshot.getPairingEnding();
        return new SyncView(snapshot.getMessage(), tone, detail, action, lastSync, canCheckNow,
            connect(snapshot.getReason()), pairing);
    }

    private static Connect connect(SyncReason reason)
    {
        switch (reason)
        {
            case NOT_PAIRED:
            case CONFIRM_IN_BROWSER:
            case NO_PROFILE:
            case GONE:
                // Nothing that works to keep: pair from scratch.
                return Connect.CONNECT;
            case SYNC_OFF:
                return Connect.TURN_ON_SYNC;
            case CONFIRM_REPAIR:
                return Connect.CANCEL_REPAIR;
            default:
                return Connect.REPAIR;
        }
    }

    private static Tone tone(TrackerConnectionState state)
    {
        switch (state)
        {
            case CONNECTED:
                return Tone.GREEN;
            case WAITING:
            case IMPORTING:
                return Tone.AMBER;
            case EXPIRED:
            case IMPORT_FAILED:
                return Tone.RED;
            default:
                return Tone.GRAY;
        }
    }
}

package com.fatelocked;

