    static String newCode()
    {
        return UUID.randomUUID().toString().replace("-", "");
    }

    static String trackerPairingUrl(String code)
    {
        return TRACKER_URL + "#runelite-pair=" + code;
    }

    /**
     * Names a pairing in local files without writing the code: the first 16
     * hex digits of its SHA-256. Null when there is no pairing.
     */
    static String tag(String code)
    {
        if (code == null || code.trim().isEmpty())
        {
            return null;
        }
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(code.trim().getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (int i = 0; i < 8; i++)
            {
                hex.append(String.format("%02x", digest[i]));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException ex)
        {
            // Every Java runtime provides SHA-256.
            throw new IllegalStateException(ex);
        }
    }
}

package com.fatelocked;

import lombok.extern.slf4j.Slf4j;

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.Executor;

/**
 * Runs local file writes one at a time and in the order they were asked
 * for, off the game and Swing threads, on RuneLite's shared executor. A
 * write queued before the plugin stops still finishes, so nothing already
 * recorded is lost; anything a write reports back to plugin state goes
 * through the client-thread gate.
 */
@Slf4j
final class SerialFileWriter
{
    private final Executor executor;
    private final Queue<Runnable> queue = new ArrayDeque<>();
    private boolean draining;

    SerialFileWriter(Executor executor)
    {
        this.executor = executor;
    }

    void submit(Runnable write)
    {
        synchronized (queue)
        {
            queue.add(write);
            if (draining)
            {
                return;
            }
            draining = true;
        }
        try
        {
            executor.execute(this::drain);
        }
        catch (RuntimeException ex)
        {
            // The executor refused (the client is closing): let the next
            // write try again rather than wait for a drain that never runs.
            synchronized (queue)
            {
                draining = false;
            }
            log.warn("Could not queue a local file write: {}", ex.getMessage());
        }
    }

    private void drain()
    {
        while (true)
        {
            Runnable write;
            synchronized (queue)
            {
                write = queue.poll();
                if (write == null)
                {
                    draining = false;
                    return;
                }
            }
            try
            {
                write.run();
            }
            catch (RuntimeException ex)
            {
                log.warn("A local file write failed", ex);
            }
        }
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.RenderOverview;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Rectangle2D;
import java.util.Map;
import java.util.Set;

/**
 * Draws tinted rectangles on the world map widget for every authored chunk:
 * green for chunks in an unlocked region, red for locked, grey for unauthored
 * (only when the camera is zoomed close enough that an unauthored overlay isn't
 * visually overwhelming).
 *
 * The render math mirrors RuneLite's built-in WorldMapOverlay — we translate
 * world tile coords to world-map viewport pixels via RenderOverview's zoom
 * level and the centre of the currently-displayed map tile.
 */
public class FateLockedWorldMapOverlay extends Overlay
{
    private static final BasicStroke BORDER = new BasicStroke(1f);

    @Inject private Client client;
    @Inject private FateLockedPlugin plugin;
    @Inject private FateLockedConfig config;
    @Inject private TooltipManager tooltipManager;

    @Inject
    FateLockedWorldMapOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.WORLD_MAP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawWorldMap()) return null;
        FateLockedBundle bundle = plugin.getBundle();
        if (bundle.getRegionChunks().isEmpty()) return null;

        Widget worldMap = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
        if (worldMap == null) return null;
        RenderOverview ro = client.getRenderOverview();
        if (ro == null) return null;

        Rectangle bounds = worldMap.getBounds();
        if (bounds == null) return null;

        Shape prevClip = graphics.getClip();
        graphics.setClip(bounds);
        graphics.setStroke(BORDER);

        // Clipping region on the world map
        Area clip = new Area(bounds);

        for (Map.Entry<String, Set<CanonicalChunk>> entry : bundle.getRegionChunks().entrySet())
        {
            for (CanonicalChunk chunk : entry.getValue())
            {
                // Sub-area-aware per-chunk colouring (Falador vs the rest of
                // Asgarnia), matching the web app's map exactly.
                Color fill = bundle.lockStateAt(chunk) == FateLockedBundle.LockState.UNLOCKED
                    ? config.unlockedColor()
                    : bundle.isFrontierChunk(chunk) ? config.frontierColor() : config.lockedColor();
                Rectangle2D rect = worldMapRectForChunk(chunk, bounds, ro);
                if (rect == null) continue;
                if (!clip.intersects(rect)) continue;

                graphics.setColor(fill);
                graphics.fill(rect);
                graphics.setColor(fill.darker());
                graphics.draw(rect);
            }
        }

        if (config.worldMapTooltip())
        {
            addHoverTooltip(bundle, bounds, ro);
        }

        graphics.setClip(prevClip);
        return null;
    }

    /** Show the area name + lock status for the authored chunk under the cursor. */
    private void addHoverTooltip(FateLockedBundle bundle, Rectangle bounds, RenderOverview ro)
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null || !bounds.contains(mouse.getX(), mouse.getY())) return;

        float pixelsPerTile = ro.getWorldMapZoom();
        if (pixelsPerTile <= 0) return;
        Point centre = ro.getWorldMapPosition();
        if (centre == null) return;

        // Invert worldMapRectForChunk: pixel → world tile → chunk.
        double tileX = centre.getX() + (mouse.getX() - bounds.getCenterX()) / pixelsPerTile;
        double tileY = centre.getY() - (mouse.getY() - bounds.getCenterY()) / pixelsPerTile;
        CanonicalChunk hovered = new CanonicalChunk(
            ((int) Math.floor(tileX)) >> 6, ((int) Math.floor(tileY)) >> 6);

        String label = bundle.labelAt(hovered);
        if (label == null) return; // unauthored — nothing to say

        String status = bundle.lockStateAt(hovered) == FateLockedBundle.LockState.UNLOCKED
            ? "<col=2ee59d>Unlocked</col>"
            : bundle.isFrontierChunk(hovered)
                ? "<col=f59e0b>Locked — rollable next</col>" : "<col=ef4444>Locked</col>";
        StringBuilder tip = new StringBuilder(label).append("</br>").append(status);
        if (config.worldMapTooltipContent())
        {
            // Per-chunk "what's here" from the app's chunk-content dataset —
            // capped per category so dense chunks stay a tooltip, not a page.
            for (String line : bundle.contentAt(hovered, 4))
            {
                tip.append("</br><col=a8a8a8>").append(line).append("</col>");
            }
        }
        tooltipManager.add(new Tooltip(tip.toString()));
    }

    /**
     * Translate a canonical chunk into world-map pixel coordinates inside the
     * world-map widget's bounds.
     */
    private Rectangle2D worldMapRectForChunk(CanonicalChunk chunk, Rectangle bounds, RenderOverview ro)
    {
        float pixelsPerTile = ro.getWorldMapZoom();
        // RuneLite's RenderOverview.getWorldMapPosition() returns a Point whose
        // (x, y) are world-tile coordinates of the map centre (not a WorldPoint).
        Point centre = ro.getWorldMapPosition();
        if (centre == null) return null;

        // The world-map widget shows a rectangular view of world tiles, centered
        // on `centre`. For a tile at world (tx, ty), its x-pixel on the widget is:
        //   px = widget.centerX + (tx - centre.x) * pixelsPerTile
        // y-axis is flipped (increasing y = northward in world, upward on screen):
        //   py = widget.centerY - (ty - centre.y) * pixelsPerTile
        double cx = bounds.getCenterX();
        double cy = bounds.getCenterY();

        int tileX = chunk.getCx() << 6;
        int tileY = chunk.getCy() << 6;

        double x0 = cx + (tileX - centre.getX()) * pixelsPerTile;
        double y1 = cy - (tileY - centre.getY()) * pixelsPerTile;
        double x1 = cx + (tileX + 64 - centre.getX()) * pixelsPerTile;
        double y0 = cy - (tileY + 64 - centre.getY()) * pixelsPerTile;

        return new Rectangle2D.Double(x0, y0, x1 - x0, y1 - y0);
    }
}

package com.fatelocked;

import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.function.Consumer;
import javax.swing.JButton;
import net.runelite.client.config.Keybind;

class KeybindCaptureButton extends JButton
{
    private Consumer<Keybind> captureListener;
    private Keybind keybind;
    private boolean capturing;

    KeybindCaptureButton(Keybind keybind, Consumer<Keybind> captureListener)
    {
        this.captureListener = captureListener;
        setKeybind(keybind);
        addActionListener(event -> beginCapture());
        addFocusListener(new FocusAdapter()
        {
            @Override
            public void focusLost(FocusEvent event)
            {
                cancelCapture();
            }
        });
        addKeyListener(new KeyAdapter()
        {
            @Override
            public void keyPressed(KeyEvent event)
            {
                capture(event);
            }
        });
    }

    void setCaptureListener(Consumer<Keybind> captureListener)
    {
        this.captureListener = captureListener;
    }

    void setKeybind(Keybind keybind)
    {
        this.keybind = keybind == null ? Keybind.NOT_SET : keybind;
        setText(this.keybind.toString());
    }

    private void beginCapture()
    {
        capturing = true;
        setText("Press a key…");
        requestFocusInWindow();
    }

    private void cancelCapture()
    {
        if (capturing)
        {
            capturing = false;
            setKeybind(keybind);
        }
    }

    private void capture(KeyEvent event)
    {
        if (!capturing)
        {
            return;
        }

        event.consume();
        capturing = false;
        Keybind captured = event.getKeyCode() == KeyEvent.VK_ESCAPE
            ? Keybind.NOT_SET : new Keybind(event);
        setKeybind(captured);
        captureListener.accept(captured);
    }
}

package com.fatelocked;

import com.fatelocked.panel.ChunkPanelViewModel;
import com.fatelocked.rules.PermissionStatus;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/** Optional draggable compact twin of the category-first side panel. */
public class FateLockedContentOverlay extends OverlayPanel
{
    private static final Color AMBER = new Color(245, 158, 11);
    private static final Color GREEN = new Color(16, 185, 129);
    private static final Color RED = new Color(239, 68, 68);
    private static final Color GRAY = new Color(156, 163, 175);
    private static final Color WHITE = new Color(229, 231, 235);

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedContentOverlay(
        Client client,
        FateLockedPlugin plugin,
        FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showChunkContentBox()) return null;
        Player local = client.getLocalPlayer();
        WorldPoint point = local == null ? null : local.getWorldLocation();
        if (point == null) return null;

        FateLockedBundle bundle = plugin.getBundle();
        if (bundle.isEmpty()) return null; // no rules yet: nothing to list
        CanonicalChunk chunk = CanonicalChunk.of(point);
        ChunkPanelViewModel view = plugin.viewModelFor(bundle, chunk);
        if (view == null) return null;

        panelComponent.setPreferredSize(new Dimension(210, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(view.getName())
            .color(AMBER)
            .build());
        panelComponent.getChildren().add(LineComponent.builder()
            .left((view.getRegion() == null ? "Unknown region" : view.getRegion())
                + " · " + view.getCoordinates())
            .leftColor(GRAY)
            .build());
        panelComponent.getChildren().add(LineComponent.builder()
            .left(statusText(view.getEntryStatus()) + " · " + view.getFreshnessLabel())
            .leftColor(statusColor(view.getEntryStatus()))
            .build());

        for (ChunkPanelViewModel.CategoryView category : view.getCategories())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(category.getTitle())
                .leftColor(AMBER)
                .build());
            int visible = Math.min(5, category.getRows().size());
            for (int i = 0; i < visible; i++)
            {
                ChunkPanelViewModel.RowView row = category.getRows().get(i);
                panelComponent.getChildren().add(LineComponent.builder()
                    .left(row.getStatusGlyph() + " " + row.getName())
                    .leftColor(statusColor(row.getStatus()))
                    .build());
            }
            int more = category.getRows().size() - visible;
            if (more > 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("+" + more + " more")
                    .leftColor(GRAY)
                    .build());
            }
        }

        if (view.getCategories().isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("No mapped permissions here")
                .leftColor(WHITE)
                .build());
        }
        return super.render(graphics);
    }

    private static Color statusColor(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return GREEN;
        if (status == PermissionStatus.NOT_READY) return AMBER;
        if (status == PermissionStatus.LOCKED) return RED;
        return GRAY;
    }

    private static String statusText(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return "Available";
        if (status == PermissionStatus.NOT_READY) return "Not ready";
        if (status == PermissionStatus.LOCKED) return "Locked";
        return "Unknown";
    }
}

package com.fatelocked;

import java.awt.Color;

import java.awt.Dimension;
import java.awt.Font;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JComponent;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

final class CollapsiblePanelSection extends JPanel
{
    private final String title;
    private final JButton header = new JButton();
    private final JPanel body = new JPanel();
    private boolean expanded;

    CollapsiblePanelSection(String title, boolean expanded)
    {
        this.title = title;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(JComponent.LEFT_ALIGNMENT);

        header.setFont(header.getFont().deriveFont(Font.BOLD, 10f));
        header.setForeground(Color.LIGHT_GRAY);
        header.setContentAreaFilled(false);
        header.setBorder(new EmptyBorder(0, 0, 4, 0));
        header.setFocusPainted(false);
        header.setHorizontalAlignment(JButton.LEFT);
        header.addActionListener(event -> setExpanded(!this.expanded));

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);
        body.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        fullWidthAndGrow(body);

        add(header);
        add(body);
        setExpanded(expanded);
    }

    JPanel body()
    {
        return body;
    }

    boolean isExpanded()
    {
        return expanded;
    }

    void setExpanded(boolean expanded)
    {
        this.expanded = expanded;
        body.setVisible(expanded);
        updateHeader();
        revalidate();
        repaint();
    }

    private void updateHeader()
    {
        header.setText((expanded ? "▼ " : "▶ ") + title);
        fullWidth(header);
    }

    JButton headerForTest()
    {
        return header;
    }

    private static void fullWidth(JComponent component)
    {
        component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(
            Integer.MAX_VALUE, component.getPreferredSize().height));
    }
    private static void fullWidthAndGrow(JComponent component)
    {
        component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import lombok.extern.slf4j.Slf4j;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.Base64;
import java.util.zip.GZIPOutputStream;

/**
 * Keeps the last accepted rules in saved-rules.json at the root of the data
 * folder, so they survive a restart and an offline start. They belong to
 * the pairing, not the OSRS account, because they must load before login,
 * and the file names the pairing only by its tag, never the code. The
 * bundle is kept compressed ("FLGZ:"), the form the bundle loader reads.
 */
@Slf4j
final class SavedRulesStore
{
    static final String FILE_NAME = "saved-rules.json";
    private static final int FORMAT = 1;
    private static final String GZ_PREFIX = "FLGZ:";

    private final Gson gson;
    private final Path path;

    SavedRulesStore(Gson gson, Path path)
    {
        this.gson = gson;
        this.path = path;
    }

    /**
     * The saved rules, or null when there are none. A damaged file is moved
     * aside as {@code .corrupt-<millis>}; a file from a newer plugin is left
     * alone. Never throws.
     */
    SavedRules load()
    {
        try
        {
            if (!Files.exists(path))
            {
                return null;
            }
            State state = gson.fromJson(
                new String(Files.readAllBytes(path), StandardCharsets.UTF_8),
                State.class);
            if (state != null && state.format > FORMAT)
            {
                return null;
            }
            SavedRules rules = state == null ? null : state.toRules();
            if (rules == null)
            {
                throw new JsonParseException("incomplete saved rules");
            }
            return rules;
        }
        catch (IOException | RuntimeException ex)
        {
            log.warn("Saved rules could not be read: {}", ex.getMessage());
            moveAside();
            return null;
        }
    }

    void save(SavedRules rules) throws IOException
    {
        State state = new State();
        state.format = FORMAT;
        state.source = rules.getSource().name();
        state.savedAt = rules.getSavedAt().toString();
        state.relayVersion = rules.getRelayVersion();
        state.pairingTag = rules.getPairingTag();
        state.payload = compress(rules.getPayload());
        byte[] bytes = gson.toJson(state).getBytes(StandardCharsets.UTF_8);

        Path parent = path.toAbsolutePath().getParent();
        if (parent != null)
        {
            Files.createDirectories(parent);
        }
        Path temporary = path.resolveSibling(path.getFileName() + ".tmp");
        Files.write(temporary, bytes);
        try
        {
            Files.move(temporary, path, StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING);
        }
        catch (AtomicMoveNotSupportedException ex)
        {
            Files.move(temporary, path, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    /** The bundle compressed as the web app compresses it, unless it already is. */
    static String compress(String bundle)
    {
        String trimmed = bundle.trim();
        if (trimmed.startsWith(GZ_PREFIX))
        {
            return trimmed;
        }
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(bytes))
        {
            gzip.write(trimmed.getBytes(StandardCharsets.UTF_8));
        }
        catch (IOException ex)
        {
            // Writing to memory does not fail.
            throw new IllegalStateException(ex);
        }
        return GZ_PREFIX + Base64.getEncoder().encodeToString(bytes.toByteArray());
    }

    private void moveAside()
    {
        try
        {
            if (Files.exists(path))
            {
                Files.move(path, path.resolveSibling(path.getFileName()
                    + ".corrupt-" + System.currentTimeMillis()),
                    StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException ex)
        {
            log.warn("Could not move damaged saved rules aside: {}", ex.getMessage());
        }
    }

    private static final class State
    {
        int format;
        String source;
        String savedAt;
        String relayVersion;
        String pairingTag;
        String payload;

        SavedRules toRules()
        {
            if (format != FORMAT || payload == null || source == null || savedAt == null)
            {
                return null;
            }
            try
            {
                return new SavedRules(payload,
                    FateLockedPlugin.RulesSource.valueOf(source),
                    Instant.parse(savedAt), relayVersion, pairingTag);
            }
            catch (IllegalArgumentException | DateTimeParseException ex)
            {
                return null;
            }
        }
    }
}

package com.fatelocked;

import java.util.Objects;

final class RepeatedValueLimiter
{
    private final long windowMillis;
    private String lastValue;
    private long lastReportedAt;
    private boolean hasReported;

    RepeatedValueLimiter(long windowMillis)
    {
        this.windowMillis = windowMillis;
    }

    synchronized boolean shouldReport(String value, long nowMillis)
    {
        if (!hasReported
            || !Objects.equals(lastValue, value)
            || nowMillis - lastReportedAt >= windowMillis)
        {
            hasReported = true;
            lastValue = value;
            lastReportedAt = nowMillis;
            return true;
        }
        return false;
    }
}

package com.fatelocked.panel;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.Locale;

/**
 * A moment as the player's own clock shows it: "18:03" today, "Mon 18:03"
 * within a week either side, "27 Jul 18:03" further off. An absolute time,
 * unlike "5m ago", stays true however long the sidebar goes unrefreshed.
 */
public final class LocalTimeText
{
    private static final DateTimeFormatter TIME =
        DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter DAY_AND_TIME =
        DateTimeFormatter.ofPattern("EEE HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter DATE_AND_TIME =
        DateTimeFormatter.ofPattern("d MMM HH:mm", Locale.ENGLISH);

    private LocalTimeText()
    {
    }

    public static String of(Instant at, Instant now, ZoneId zone)
    {
        ZonedDateTime local = at.atZone(zone);
        long days = Math.abs(ChronoUnit.DAYS.between(
            now.atZone(zone).toLocalDate(), local.toLocalDate()));
        if (days == 0)
        {
            return TIME.format(local);
        }
        return (days < 7 ? DAY_AND_TIME : DATE_AND_TIME).format(local);
    }

    /** For the player's own clock. */
    public static String of(Instant at)
    {
        return of(at, Instant.now(), ZoneId.systemDefault());
    }
}

