    private final int unknownCount;
    private final List<CategoryView> categories;

    ChunkPanelViewModel(
        String name,
        String region,
        String coordinates,
        PermissionStatus entryStatus,
        String freshnessLabel,
        int allowedCount,
        int notReadyCount,
        int lockedCount,
        int unknownCount,
        List<CategoryView> categories)
    {
        this.name = name;
        this.region = region;
        this.coordinates = coordinates;
        this.entryStatus = entryStatus;
        this.freshnessLabel = freshnessLabel;
        this.allowedCount = allowedCount;
        this.notReadyCount = notReadyCount;
        this.lockedCount = lockedCount;
        this.unknownCount = unknownCount;
        this.categories = Collections.unmodifiableList(categories);
    }

    public CategoryView category(String id)
    {
        for (CategoryView category : categories)
        {
            if (category.getId().equals(id)) return category;
        }
        return null;
    }

    @Getter
    public static final class CategoryView
    {
        private final String id;
        private final String title;
        private final List<RowView> rows;

        CategoryView(String id, String title, List<RowView> rows)
        {
            this.id = id;
            this.title = title;
            this.rows = Collections.unmodifiableList(rows);
        }
    }

    @Getter
    public static final class RowView
    {
        private final String name;
        private final PermissionStatus status;
        private final String statusGlyph;
        private final String statusText;
        private final String detail;

        RowView(
            String name,
            PermissionStatus status,
            String statusGlyph,
            String statusText,
            String detail)
        {
            this.name = name;
            this.status = status;
            this.statusGlyph = statusGlyph;
            this.statusText = statusText;
            this.detail = detail;
        }
    }
}

package com.fatelocked.panel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.rules.ChunkPermissionRow;
import com.fatelocked.rules.ChunkPermissionSnapshot;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ChunkPanelViewModelFactory
{
    private static final List<String> ORDER = Arrays.asList(
        "SKILLING", "BANKS", "SHOPS", "QUESTS", "COMBAT",
        "TRAVEL", "FARMING", "ACTIVITIES");

    private static final Map<String, String> TITLES;
    static
    {
        Map<String, String> titles = new LinkedHashMap<>();
        titles.put("SKILLING", "Skilling");
        titles.put("BANKS", "Banks");
        titles.put("SHOPS", "Shops");
        titles.put("QUESTS", "Quests");
        titles.put("COMBAT", "Combat");
        titles.put("TRAVEL", "Travel");
        titles.put("FARMING", "Farming");
        titles.put("ACTIVITIES", "Activities");
        TITLES = Collections.unmodifiableMap(titles);
    }

    public ChunkPanelViewModel create(
        FateLockedBundle bundle,
        CanonicalChunk chunk,
        boolean accountMatches,
        Instant importedAt)
    {
        RuleDecision entry = new FateRuleEngine(
            bundle, accountMatches, false).entry(chunk);
        ChunkPermissionSnapshot snapshot = accountMatches
            ? bundle.permissionsAt(chunk).orElse(null) : null;
        List<ChunkPanelViewModel.CategoryView> categories = new ArrayList<>();
        int allowed = 0;
        int notReady = 0;
        int locked = 0;
        int unknown = 0;

        if (snapshot != null)
        {
            for (String id : ORDER)
            {
                List<ChunkPermissionRow> source = snapshot.getCategories().get(id);
                if (source == null || source.isEmpty()) continue;
                List<ChunkPanelViewModel.RowView> rows = new ArrayList<>();
                for (ChunkPermissionRow row : source)
                {
                    PermissionStatus status = row.getStatus();
                    if (status == PermissionStatus.ALLOWED) allowed++;
                    else if (status == PermissionStatus.NOT_READY) notReady++;
                    else if (status == PermissionStatus.LOCKED) locked++;
                    else unknown++;
                    rows.add(new ChunkPanelViewModel.RowView(
                        row.getName(),
                        status,
                        glyph(id, status),
                        statusText(id, status),
                        keepsDetail(id) ? row.getDetail() : null));
                }
                categories.add(new ChunkPanelViewModel.CategoryView(
                    id, TITLES.get(id), rows));
            }
        }
        else if (accountMatches && bundle.isLegacyRules())
        {
            Map<String, List<String>> legacy = bundle.legacyContentAt(chunk);
            Map<String, String> legacyCategories = new LinkedHashMap<>();
            legacyCategories.put("mon", "COMBAT");
            legacyCategories.put("shop", "SHOPS");
            legacyCategories.put("farm", "FARMING");
            legacyCategories.put("poi", "ACTIVITIES");
            for (String id : ORDER)
            {
                List<ChunkPanelViewModel.RowView> rows = new ArrayList<>();
                for (Map.Entry<String, String> mapping : legacyCategories.entrySet())
                {
                    if (!id.equals(mapping.getValue())) continue;
                    for (String name : legacy.getOrDefault(
                        mapping.getKey(), Collections.emptyList()))
                    {
                        rows.add(new ChunkPanelViewModel.RowView(
                            name,
                            PermissionStatus.UNKNOWN,
                            "?",
                            statusText(id, PermissionStatus.UNKNOWN),
                            null));
                        unknown++;
                    }
                }
                if (!rows.isEmpty())
                {
                    categories.add(new ChunkPanelViewModel.CategoryView(
                        id, TITLES.get(id), rows));
                }
            }
        }

        String name = snapshot == null ? bundle.labelAt(chunk) : snapshot.getName();
        if (name == null || name.trim().isEmpty()) name = "Unknown chunk";
        String region = snapshot == null ? bundle.regionAt(chunk) : snapshot.getRegion();
        return new ChunkPanelViewModel(
            name,
            region,
            chunk.getCx() + ", " + chunk.getCy(),
            entry.getStatus(),
            freshness(importedAt),
            allowed,
            notReady,
            locked,
            unknown,
            categories);
    }

    private static boolean keepsDetail(String category)
    {
        return "SKILLING".equals(category) || "TRAVEL".equals(category);
    }

    private static String glyph(String category, PermissionStatus status)
    {
        if (status == PermissionStatus.UNKNOWN) return "?";
        if ("COMBAT".equals(category))
        {
            return status == PermissionStatus.ALLOWED ? "✓" : "✕";
        }
        if (status == PermissionStatus.ALLOWED) return "✓";
        if (status == PermissionStatus.NOT_READY) return "○";
        return "✕";
    }

    private static String statusText(String category, PermissionStatus status)
    {
        if ("QUESTS".equals(category) || "COMBAT".equals(category)) return null;
        if (status == PermissionStatus.ALLOWED) return "Available";
        if (status == PermissionStatus.NOT_READY) return "Not ready";
        if (status == PermissionStatus.LOCKED) return "Locked";
        return "Unknown";
    }

    /**
     * When the tracker last confirmed the rules, on the player's clock. The
     * card is rebuilt only when the player changes chunk, so "5m ago" went
     * stale where it stood; a time of day stays true.
     */
    private static String freshness(Instant importedAt)
    {
        return importedAt == null ? "Offline snapshot" : "Synced " + LocalTimeText.of(importedAt);
    }
}

package com.fatelocked.events;

import com.fatelocked.storage.LocalFileMerge;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * The newest 250 detected events, kept in a local file that another
 * RuneLite on this computer may share: each write merges into what is on
 * disk rather than replacing it (LocalFileMerge).
 */
public final class FateEventHistory
{
    static final int MAX_EVENTS = 250;

    interface Persistence
    {
        void write(Path target, byte[] bytes) throws IOException;
    }

    private final Gson gson;
    private final Path historyPath;
    private final Persistence persistence;
    private final List<FateEvent> events = new ArrayList<>();

    public FateEventHistory(
        Gson gson, Path historyPath, Path legacyOutboxPath)
        throws IOException
    {
        this(gson, historyPath, legacyOutboxPath, LocalFileMerge::replace);
    }

    FateEventHistory(
        Gson gson,
        Path historyPath,
        Path legacyOutboxPath,
        Persistence persistence)
        throws IOException
    {
        if (gson == null || historyPath == null || persistence == null)
        {
            throw new IllegalArgumentException(
                "History dependencies are required");
        }
        this.gson = gson;
        this.historyPath = historyPath;
        this.persistence = persistence;
        load(legacyOutboxPath);
    }

    public synchronized boolean record(FateEvent event) throws IOException
    {
        if (event == null || event.getEventId() == null
            || event.getEventId().trim().isEmpty()
            || contains(event.getEventId()))
        {
            return false;
        }

        List<FateEvent> candidate = new ArrayList<>(events);
        candidate.add(event);
        List<FateEvent> merged = persist(candidate);
        // Only once written: a failed write leaves memory as it was.
        events.clear();
        events.addAll(merged);
        return true;
    }

    public synchronized List<FateEvent> events()
    {
        return Collections.unmodifiableList(new ArrayList<>(events));
    }

    /** Add events from elsewhere, such as an older shared history, merged as any write is. */
    public synchronized void adopt(List<FateEvent> adopted) throws IOException
    {
        List<FateEvent> candidate = new ArrayList<>(events);
        candidate.addAll(adopted);
        List<FateEvent> merged = persist(candidate);
        events.clear();
        events.addAll(merged);
    }

    /**
     * The events in a history file, or in the older outbox file when there
     * is no history, without writing, moving or repairing either. None when
     * neither can be read.
     */
    public static List<FateEvent> readOnly(Gson gson, Path historyPath, Path legacyOutboxPath)
    {
        try
        {
            if (Files.exists(historyPath))
            {
                State state = gson.fromJson(new String(
                    Files.readAllBytes(historyPath), StandardCharsets.UTF_8), State.class);
                return state == null || state.events == null
                    ? Collections.emptyList() : withoutNulls(state.events);
            }
            if (legacyOutboxPath != null && Files.exists(legacyOutboxPath))
            {
                LegacyState legacy = gson.fromJson(new String(
                    Files.readAllBytes(legacyOutboxPath), StandardCharsets.UTF_8), LegacyState.class);
                return legacy == null || legacy.pending == null
                    ? Collections.emptyList() : withoutNulls(legacy.pending);
            }
        }
        catch (IOException | RuntimeException error)
        {
            // Unreadable: nothing comes from it, and it is left as it is.
        }
        return Collections.emptyList();
    }

    private static List<FateEvent> withoutNulls(List<FateEvent> source)
    {
        List<FateEvent> valid = new ArrayList<>();
        for (FateEvent event : source)
        {
            if (event != null) valid.add(event);
        }
        return valid;
    }

    private boolean contains(String eventId)
    {
        for (FateEvent event : events)
        {
            if (eventId.equals(event.getEventId()))
            {
                return true;
            }
        }
        return false;
    }

    private void load(Path legacyOutboxPath) throws IOException
    {
        if (Files.exists(historyPath))
        {
            loadHistory();
            return;
        }
        if (legacyOutboxPath != null && Files.exists(legacyOutboxPath))
        {
            migrateLegacy(legacyOutboxPath);
        }
    }

    private void loadHistory() throws IOException
    {
        try
        {
            State state = gson.fromJson(
                new String(
                    Files.readAllBytes(historyPath),
                    StandardCharsets.UTF_8),
                State.class);
            if (state == null || state.events == null)
            {
                throw new JsonParseException("invalid event history");
            }
            events.addAll(boundedUnique(state.events));
        }
        catch (RuntimeException error)
        {
            Path corrupt = historyPath.resolveSibling(
                historyPath.getFileName() + ".corrupt-"
                    + System.currentTimeMillis());
            Files.move(historyPath, corrupt,
                StandardCopyOption.REPLACE_EXISTING);
            events.clear();
        }
    }

    private void migrateLegacy(Path legacyOutboxPath) throws IOException
    {
        LegacyState legacy;
        try
        {
            legacy = gson.fromJson(
                new String(
                    Files.readAllBytes(legacyOutboxPath),
                    StandardCharsets.UTF_8),
                LegacyState.class);
        }
        catch (RuntimeException error)
        {
            return;
        }
        if (legacy == null || legacy.pending == null)
        {
            return;
        }
        events.addAll(persist(boundedUnique(legacy.pending)));
    }

    private List<FateEvent> boundedUnique(List<FateEvent> source)
    {
        List<FateEvent> bounded = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int index = source.size() - 1; index >= 0; index--)
        {
            FateEvent event = source.get(index);
            String eventId = event == null ? null : event.getEventId();
            if (eventId == null || eventId.trim().isEmpty()
                || !seen.add(eventId))
            {
                continue;
            }
            bounded.add(event);
            if (bounded.size() == MAX_EVENTS)
            {
                break;
            }
        }
        Collections.reverse(bounded);
        return bounded;
    }

    /**
     * Write these events merged with those on disk now, which another
     * RuneLite may have added since this one loaded: the newest 250, oldest
     * first. A damaged file is moved aside first. Returns what was written.
     */
    private List<FateEvent> persist(List<FateEvent> ours) throws IOException
    {
        List<FateEvent> merged = new ArrayList<>();
        LocalFileMerge.update(historyPath, current -> {
            List<FateEvent> all = new ArrayList<>(onDisk(current));
            all.addAll(ours);
            all.sort(Comparator.comparingLong(FateEvent::getOccurredAt));
            merged.clear();
            merged.addAll(boundedUnique(all));
            State state = new State();
            state.events = new ArrayList<>(merged);
            return gson.toJson(state).getBytes(StandardCharsets.UTF_8);
        }, persistence::write);
        return merged;
    }

    /** The events in the file's current contents; none if there is no file, or it is damaged. */
    private List<FateEvent> onDisk(byte[] current) throws IOException
    {
        if (current == null)
        {
            return Collections.emptyList();
        }
        try
        {
            State state = gson.fromJson(new String(current, StandardCharsets.UTF_8), State.class);
            if (state != null && state.events != null)
            {
                List<FateEvent> valid = new ArrayList<>();
                for (FateEvent event : state.events)
                {
                    if (event != null) valid.add(event);
                }
                return valid;
            }
        }
        catch (RuntimeException error)
        {
            // Damaged: kept aside below, and not written over.
        }
        LocalFileMerge.moveAside(historyPath);
        return Collections.emptyList();
    }

    private static final class State
    {
        private List<FateEvent> events;
    }

    private static final class LegacyState
    {
        private List<FateEvent> pending;
    }
}

