        p("draynor village", 48, 50);
        p("al kharid", 51, 49);
        // Ring of dueling
        p("castle wars", 38, 48);
        p("duel arena", 51, 50);
        p("pvp arena", 51, 50);
        p("emir's arena", 51, 50);
        p("ferox enclave", 49, 56);
        // Games necklace
        p("burthorpe", 45, 55);
        p("barbarian outpost", 39, 55);
        p("wintertodt", 25, 61);
        p("tournament", 34, 44);
        p("soul wars", 34, 44);
        // Combat bracelet
        p("warriors' guild", 45, 55);
        p("champions' guild", 49, 52);
        p("monastery", 47, 54);
