        p("xeric's lookout", 24, 55);

        // Spirit tree network (right-click options are destination names)
        p("tree gnome stronghold", 38, 53);
        p("gnome stronghold", 38, 53);
        p("tree gnome village", 39, 49);
        p("battlefield of khazard", 41, 49);
        p("etceteria", 40, 60);
        p("brimhaven", 43, 50);
        p("hosidius", 24, 53);
        // Gnome glider network
        p("sindarpos", 44, 54);
        p("ta quir priw", 38, 53);
        p("lemanto andra", 51, 53);
        p("kar-hewo", 51, 50);
        p("gandius", 46, 46);
        p("lemantolly undri", 39, 46);
        p("ookookolly undri", 43, 43);

        // Checked named destinations for travel-network menus.
        t("lunar isle", 33, 61);
        t("zanaris", 37, 69);
        t("prifddinas", 51, 95);
        t("lovakengj", 23, 58);
        t("nardah", 53, 45);
        t("taverley", 45, 53);
        t("eagles' peak", 36, 54);
        t("nightmare zone", 40, 48);
        t("hunter guild", 24, 47);
        t("port khazard", 41, 49);

        List<String> keys = new ArrayList<>(PLACES.keySet());
        keys.sort((a, b) -> b.length() - a.length()); // longest first for specificity
        KEYS_BY_LEN = keys;

        List<String> checkedTravelKeys = new ArrayList<>(keys);
        checkedTravelKeys.addAll(CHECKED_TRAVEL_PLACES.keySet());
        checkedTravelKeys.sort((a, b) -> b.length() - a.length());
        CHECKED_TRAVEL_KEYS_BY_LEN = checkedTravelKeys;
    }

    /**
     * Destination chunk for a teleport menu entry, or null when the entry isn't a
     * recognised teleport or its destination is unknown.
     */
    public static CanonicalChunk destinationChunk(String option, String target)
    {
        return destinationChunk(option, target, false);
    }

    public static CanonicalChunk destinationChunk(String option, String target,
        boolean includeTravelTransportItems)
    {
        String text = normalize(option) + " " + normalize(target);
        boolean looksTele = contains(text, TELE_ITEMS);
        if (!looksTele && includeTravelTransportItems)
        {
            looksTele = contains(text, TRAVEL_TRANSPORT_ITEMS);
        }
        return looksTele
            ? destinationFromText(text, includeTravelTransportItems) : null;
    }

    /**
     * Destination for a checked travel activation. This is the authoritative
     * activation classifier shared by Travel Guardian and the legacy guard.
     */
    public static CanonicalChunk checkedTravelDestinationChunk(
        String option, String target, boolean includeTravelTransportItems)
    {
        String cleanOption = normalize(option);
        String cleanTarget = normalize(target);
        CanonicalChunk destination = destinationChunk(
            cleanOption, cleanTarget, includeTravelTransportItems);
        if (destination == null) return null;
        if (isActivationOption(cleanOption)) return destination;

        CanonicalChunk namedDestination = destinationFromText(
            cleanOption, includeTravelTransportItems);
        return namedDestination != null
            && namedDestination.equals(destination)
            && contains(cleanTarget, NAMED_DESTINATION_CARRIERS)
            ? destination : null;
    }

    private static CanonicalChunk destinationFromText(
        String text, boolean includeTravelTransportItems)
    {
        List<String> keys = includeTravelTransportItems
            ? CHECKED_TRAVEL_KEYS_BY_LEN : KEYS_BY_LEN;
        for (String key : keys)
        {
            if (text.contains(key))
            {
                int[] c = PLACES.get(key);
                if (c == null) c = CHECKED_TRAVEL_PLACES.get(key);
                return new CanonicalChunk(c[0], c[1]);
            }
        }
        return null;
    }

    private static boolean isActivationOption(String option)
    {
        return option.equals("teleport") || option.equals("cast")
            || option.equals("break") || option.equals("rub")
            || option.equals("travel") || option.startsWith("travel via ")
            || option.equals("charter") || option.equals("pay-fare")
            || option.equals("minigame teleport");
    }

    private static String normalize(String value)
    {
        return (value == null ? "" : value)
            .toLowerCase()
            .replaceAll("<[^>]*>", " ")
            .replaceAll("\\s+", " ")
            .trim();
    }
    private static boolean contains(String text, String[] items)
    {
        for (String item : items)
        {
            if (text.contains(item)) return true;
        }
        return false;
    }

    public static Map<String, CanonicalChunk> destinations()
    {
        Map<String, CanonicalChunk> result = new LinkedHashMap<>();
        for (Map.Entry<String, int[]> entry : PLACES.entrySet())
        {
            result.put(entry.getKey(),
                new CanonicalChunk(entry.getValue()[0], entry.getValue()[1]));
        }
        return Collections.unmodifiableMap(result);
    }
}

package com.fatelocked;

import java.time.Instant;
import java.util.Objects;

final class TrackerConnectionSnapshot
{
    private final TrackerConnectionState state;
    private final Instant lastSync;
    private final String acceptedVersion;
    private final SyncReason reason;
    /** When the next check is due, for states that say so; null otherwise. */
    private final Instant nextCheck;
    /** The last four characters of the code in use, or null: all the sidebar shows of it. */
    private final String pairingEnding;

    private TrackerConnectionSnapshot(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        SyncReason reason,
        Instant nextCheck,
        String pairingEnding)
    {
        this.state = state;
        this.lastSync = lastSync;
        this.acceptedVersion = acceptedVersion;
        this.reason = reason == null ? SyncReason.NONE : reason;
        this.nextCheck = nextCheck;
        this.pairingEnding = pairingEnding;
    }

    TrackerConnectionState getState()
    {
        return state;
    }

    Instant getLastSync()
    {
        return lastSync;
    }

    String getAcceptedVersion()
    {
        return acceptedVersion;
    }

    SyncReason getReason()
    {
        return reason;
    }

    Instant getNextCheck()
    {
        return nextCheck;
    }

    String getPairingEnding()
    {
        return pairingEnding;
    }

    /** This snapshot for the pairing whose code this is. */
    TrackerConnectionSnapshot forPairing(String code)
    {
        String ending = code == null || code.length() < 4 ? null : code.substring(code.length() - 4);
        return new TrackerConnectionSnapshot(
            state, lastSync, acceptedVersion, reason, nextCheck, ending);
    }

    /** The short status: the reason's, or the state's own. */
    String getMessage()
    {
        return reason.status != null ? reason.status : stateStatus(state);
    }

    static TrackerConnectionSnapshot disconnected()
    {
        return of(TrackerConnectionState.DISCONNECTED, null, null, SyncReason.NOT_PAIRED, null);
    }

    static TrackerConnectionSnapshot waiting()
    {
        return of(TrackerConnectionState.WAITING, null, null, SyncReason.NONE, null);
    }

    static TrackerConnectionSnapshot connected(
        Instant at, String version)
    {
        return of(TrackerConnectionState.CONNECTED, at, version, SyncReason.NONE, null);
    }

    static TrackerConnectionSnapshot of(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        SyncReason reason,
        Instant nextCheck)
    {
        return new TrackerConnectionSnapshot(
            state, lastSync, acceptedVersion, reason, nextCheck, null);
    }

    private static String stateStatus(TrackerConnectionState state)
    {
        switch (state)
        {
            case DISCONNECTED:
                return "Not connected";
            case WAITING:
                return "Waiting for tracker";
            case IMPORTING:
                return "Importing tracker data";
            case CONNECTED:
                return "Connected";
            case EXPIRED:
                return "Pairing request expired";
            case OFFLINE:
                return "Tracker is offline";
            case IMPORT_FAILED:
                return "Could not import tracker data";
            default:
                return "";
        }
    }

    /** Two snapshots that would show the same thing are equal, so nothing republishes it. */
    @Override
    public boolean equals(Object other)
    {
        if (this == other) return true;
        if (!(other instanceof TrackerConnectionSnapshot)) return false;
        TrackerConnectionSnapshot that = (TrackerConnectionSnapshot) other;
        return state == that.state
            && Objects.equals(lastSync, that.lastSync)
            && Objects.equals(acceptedVersion, that.acceptedVersion)
            && reason == that.reason
            && Objects.equals(nextCheck, that.nextCheck)
            && Objects.equals(pairingEnding, that.pairingEnding);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(state, lastSync, acceptedVersion, reason, nextCheck, pairingEnding);
    }
}

