package com.fatelocked;

import com.fatelocked.guardian.GuardContext;
import com.fatelocked.guardian.StrictModeAuditEntry;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelAlternative;
import com.fatelocked.guardian.travel.TravelAvailability;
import com.fatelocked.guardian.travel.TravelGuardianCoordinator;
import com.fatelocked.guardian.travel.TravelGuardianResult;
import com.fatelocked.rules.FateRuleEngine;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;

import java.time.Clock;

/**
 * Thin plugin boundary for coordinator routing and post-enforcement side
 * effects. It never repeats travel recognition, evaluation, or presentation.
 * Clicks that are not exactly matched travel are left alone.
 */
final class TravelGuardianPluginShell
{
    enum Route
    {
        EXACT_TRAVEL,
        NOT_TRAVEL,
        FAIL_OPEN
    }

    @FunctionalInterface
    interface ChatSink
    {
        void write(String message);
    }

    @FunctionalInterface
    interface AuditSink
    {
        void write(StrictModeAuditEntry entry) throws Exception;
    }

    @FunctionalInterface
    interface DiagnosticSink
    {
        void record(String stage, Exception error);
    }

    private final TravelGuardianCoordinator coordinator;
    private final TravelAvailability availability;
    private final ChatSink chatSink;
    private final AuditSink auditSink;
    private final DiagnosticSink diagnosticSink;
    private final Clock clock;

    TravelGuardianPluginShell(
        TravelGuardianCoordinator coordinator,
        TravelAvailability availability,
        ChatSink chatSink,
        AuditSink auditSink,
        DiagnosticSink diagnosticSink,
        Clock clock)
    {
        this.coordinator = coordinator;
        this.availability = availability;
        this.chatSink = chatSink;
        this.auditSink = auditSink;
        this.diagnosticSink = diagnosticSink;
        this.clock = clock;
    }

    Route handle(
        MenuOptionClicked event,
        Client client,
        CanonicalChunk origin,
        GuardContext travelContext,
        FateRuleEngine travelRules)
    {
        TravelGuardianResult result;
        try
        {
            result = coordinator.handle(
                event, event.getMenuEntry(), client, origin,
                travelContext, travelRules, availability);
        }
        catch (RuntimeException ex)
        {
            diagnose("coordinator", ex);
            return Route.FAIL_OPEN;
        }

        if (result == null)
        {
            diagnose("coordinator",
                new IllegalStateException("coordinator returned no result"));
            return Route.FAIL_OPEN;
        }

        TravelAction action = result.getAction();
        if (action == null
            || action.getConfidence() != TravelAction.Confidence.EXACT)
        {
            return Route.NOT_TRAVEL;
        }

        if (result.isWriteChat())
        {
            try
            {
                chatSink.write(chatMessage(result));
            }
            catch (RuntimeException ex)
            {
                diagnose("chat", ex);
            }
        }
        if (result.isWriteBlockedAudit() || result.isWritePausedAudit())
        {
            try
            {
                auditSink.write(auditEntry(result));
            }
            catch (Exception ex)
            {
                diagnose("audit", ex);
            }
        }
        return Route.EXACT_TRAVEL;
    }

    private String chatMessage(TravelGuardianResult result)
    {
        String reason = result.getDecision().getReason();
        if (reason == null || reason.trim().isEmpty())
        {
            reason = "Travel is locked";
        }
        StringBuilder message = new StringBuilder()
            .append("[Fate Guardian] Blocked ")
            .append(result.getDecision().getLabel())
            .append(": ")
            .append(reason)
            .append('.');
        TravelAlternative alternative = result.getAlternative();
        if (alternative != null
            && alternative.getLabel() != null
            && !alternative.getLabel().trim().isEmpty())
        {
            message.append(" Suggested: ")
                .append(alternative.getLabel())
                .append('.');
        }
        return message.toString();
    }

    private StrictModeAuditEntry auditEntry(TravelGuardianResult result)
    {
        TravelAction action = result.getAction();
        CanonicalChunk destination = action.getDestination();
        String chunk = destination == null ? null
            : destination.getCx() + "," + destination.getCy();
        boolean paused = result.isWritePausedAudit();
        return new StrictModeAuditEntry(
            clock.millis(),
            "TRAVEL",
            result.getDecision().getLabel(),
            chunk,
            result.getDecision().getReason(),
            paused ? "ALLOWED_PAUSED" : "BLOCKED",
            paused,
            !paused && result.getAlternative() != null);
    }

    private void diagnose(String stage, Exception error)
    {
        try
        {
            diagnosticSink.record(stage, error);
        }
        catch (RuntimeException ignored)
        {
            // Diagnostics must never change fail-open or enforced outcomes.
        }
    }
}

package com.fatelocked.storage;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;

/**
 * Updates a local file that another RuneLite on this computer may also be
 * writing. Under an exclusive lock on a "&lt;file&gt;.lock" sidecar, it reads
 * the file as it is now, merges this client's change into it, writes the
 * result to a temp file of its own and moves that into place. Two clients
 * sharing a data folder then keep each other's changes, where rewriting
 * the whole file from memory let the last writer's copy win.
 */
public final class LocalFileMerge
{
    /** The file's new contents, from its current ones: null when there is no file. */
    public interface Merge
    {
        /** Null writes nothing. */
        byte[] apply(byte[] current) throws IOException;
    }

    /** Puts the merged contents in place. */
    public interface Writer
    {
        void write(Path target, byte[] bytes) throws IOException;
    }

    private LocalFileMerge()
    {
    }

    public static void update(Path target, Merge merge) throws IOException
    {
        update(target, merge, LocalFileMerge::replace);
    }

    /**
     * One update at a time within this RuneLite, since a JVM cannot hold two
     * locks on one file, and one across RuneLites, through the file lock.
     */
    public static synchronized void update(Path target, Merge merge, Writer writer)
        throws IOException
    {
        Path parent = target.toAbsolutePath().getParent();
        if (parent != null)
        {
            Files.createDirectories(parent);
        }
        Path lockPath = target.resolveSibling(target.getFileName() + ".lock");
        try (FileChannel lockChannel = FileChannel.open(lockPath,
                StandardOpenOption.CREATE, StandardOpenOption.WRITE);
             FileLock ignored = lockChannel.lock())
        {
            byte[] current = Files.exists(target) ? Files.readAllBytes(target) : null;
            byte[] next = merge.apply(current);
            if (next != null)
            {
                writer.write(target, next);
            }
        }
    }

    /**
     * Write the bytes to a temp file of this write's own, flush them to the
     * disk, and move the file into place, so a reader sees the old contents
     * or the new, never part of them.
     */
    public static void replace(Path target, byte[] bytes) throws IOException
    {
        Path parent = target.toAbsolutePath().getParent();
        Path temporary = Files.createTempFile(parent, target.getFileName() + ".", ".tmp");
        try
        {
            try (FileChannel out = FileChannel.open(temporary,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING))
            {
                ByteBuffer buffer = ByteBuffer.wrap(bytes);
                while (buffer.hasRemaining())
                {
                    out.write(buffer);
                }
                out.force(true);
            }
            try
            {
                Files.move(temporary, target,
                    StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            }
            catch (AtomicMoveNotSupportedException error)
            {
                Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            Files.deleteIfExists(temporary);
        }
    }

    /** Keep a damaged file as "&lt;file&gt;.corrupt-&lt;millis&gt;" rather than writing over it. */
    public static void moveAside(Path target) throws IOException
    {
        Files.move(target, target.resolveSibling(
                target.getFileName() + ".corrupt-" + System.currentTimeMillis()),
            StandardCopyOption.REPLACE_EXISTING);
    }
}

