package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.Collections;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Clue scroll completions. When "You have completed 12 hard Treasure
 * Trails." appears, RuneLite's loot tracker posts the reward as loot from
 * an event named "Clue Scroll (Hard)". An item called "Casket" in other
 * loot, such as Tempoross's reward pool, is not a completion, and the
 * reward caskets' item names never appear as loot.
 */
public class ClueCompletionDetector
{
    private static final Pattern CLUE_EVENT = Pattern.compile(
        "Clue Scroll \\((Beginner|Easy|Medium|Hard|Elite|Master)\\)", Pattern.CASE_INSENSITIVE);

    public Optional<DetectedEvent> detect(String lootType, String name)
    {
        if (!"EVENT".equals(lootType) || name == null)
        {
            return Optional.empty();
        }
        Matcher clue = CLUE_EVENT.matcher(name.trim());
        if (!clue.matches())
        {
            return Optional.empty();
        }
        return Optional.of(DetectedEvent.builder()
            .type(FateEventType.CLUE_CASKET)
            .canonicalLabel(name.trim())
            .confidence(EventConfidence.EXACT)
            .detectorId("clue-completion-loot-v1")
            .detectorVersion(1)
            .evidence(Collections.<String, Object>singletonMap(
                "tier", clue.group(1).toLowerCase(Locale.ROOT)))
            .build());
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public final class BossKillDetectorV2
{
    private final Map<String, String> encounters = new HashMap<>();
    private String lastKey;

    public BossKillDetectorV2()
    {
        for (String name : Arrays.asList(
            "Vorkath", "Zulrah", "Bryophyta", "Nex", "Hespori",
            "General Graardor", "Kree'arra", "Commander Zilyana",
            "K'ril Tsutsaroth"))
            encounters.put(name.toLowerCase(), name);
    }

    public Optional<DetectedEvent> detect(String lootType, String name, long cycle)
    {
        String canonical = name == null ? null : encounters.get(name.trim().toLowerCase());
        if (canonical == null) return Optional.empty();
        String key = canonical + ":" + cycle;
        if (key.equals(lastKey)) return Optional.empty();
        lastKey = key;
        return Optional.of(DetectedEvent.builder()
            .type(FateEventType.BOSS_KILL)
            .canonicalLabel(canonical)
            .confidence(EventConfidence.UNCERTAIN)
            .detectorId("boss-kill-v2")
            .detectorVersion(2)
            .evidence(Collections.<String, Object>singletonMap("lootType", lootType))
            .build());
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.Collections;
import java.util.Locale;
import java.util.Optional;

/**
 * A new pet, from the game's two lines for one, as RuneLite's screenshot
 * plugin reads them. Which pet is left for the player to say: the follower
 * at that moment may be another pet, and a table from follower ids to pets
 * had the wrong ids for two of its three.
 */
public final class PetDropDetector
{
    /** The pet starts following the player. */
    private static final String FOLLOWED = "you have a funny feeling like you're being followed";
    /** The player already has a follower, so the pet goes in the backpack. */
    private static final String BACKPACK = "you feel something weird sneaking into your backpack";

    private long lastEventAt;

    /**
     * A new pet, or nothing. "... like you would have been followed" is a
     * pet the player already owns, which is not a new one.
     */
    public Optional<DetectedEvent> detect(String message, long now)
    {
        String normalized = message == null ? "" : message.toLowerCase(Locale.ROOT);
        String signature = normalized.contains(FOLLOWED) ? "followed"
            : normalized.contains(BACKPACK) ? "backpack" : null;
        if (signature == null || now - lastEventAt < 5000)
        {
            return Optional.empty();
        }
        lastEventAt = now;
        return Optional.of(DetectedEvent.builder()
            .type(FateEventType.PET_DROP)
            .canonicalLabel(null)
            .confidence(EventConfidence.UNCERTAIN)
            .detectorId("pet-drop-v1")
            .detectorVersion(1)
            .evidence(Collections.<String, Object>singletonMap("signature", signature))
            .build());
    }
}

