package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class SkillLevelDetector
{
    private final Map<String, Integer> levels = new HashMap<>();

    public Optional<DetectedEvent> detect(String skill, int level)
    {
        Integer previous = levels.put(skill, level);
        if (previous == null || level <= previous) return Optional.empty();
        Map<String, Object> evidence = new HashMap<>();
        evidence.put("skill", skill);
        evidence.put("previousLevel", previous);
        evidence.put("level", level);
        return Optional.of(DetectedEvent.builder()
            .type(FateEventType.SKILL_LEVEL)
            .canonicalLabel(skill + " Level " + level)
            .confidence(EventConfidence.EXACT)
            .detectorId("skill-level-v1")
            .detectorVersion(1)
            .evidence(evidence)
            .build());
    }

    public void clear()
    {
        levels.clear();
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CombatAchievementDetector
{
    /**
     * The game's line, read as RuneLite's screenshot plugin reads it:
     * "Congratulations, you've completed a grandmaster combat task:
     * {@literal @}ach_comp@Egniol Diet II&lt;/col&gt; (6 points)." The colour
     * marker, the closing tag and the points are not part of the task's
     * name. Works on the line with or without its tags.
     */
    private static final Pattern TASK = Pattern.compile(
        "(?:an? (?<tier>\\w+) )?combat task: (?:@[^@]+@|<col=[0-9a-fA-F]+>)?"
            + "(?<task>.+?)(?:</col>)?(?: \\(\\d+ points?\\))?[.!]?$");

    public DetectedEvent detect(String message)
    {
        String text = message == null ? "" : message.trim();
        Matcher match = TASK.matcher(text);
        String label = null;
        Map<String, Object> evidence = new LinkedHashMap<>();
        evidence.put("signature", "combat-task");
        if (match.find())
        {
            label = match.group("task").trim();
            if (label.isEmpty()) label = null;
            if (match.group("tier") != null)
            {
                evidence.put("tier", match.group("tier").toLowerCase());
            }
        }
        return DetectedEvent.builder()
            .type(FateEventType.COMBAT_ACHIEVEMENT)
            .canonicalLabel(label)
            .confidence(label == null ? EventConfidence.UNCERTAIN : EventConfidence.EXACT)
            .detectorId("combat-achievement-chat-v1")
            .detectorVersion(1)
            .evidence(evidence)
            .build();
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class QuestDetector
{
    /**
     * Quests whose names really end in "Quest", which a title's trailing
     * "Quest" must not be cut from. RuneLite's screenshot plugin keeps the
     * same list.
     */
    private static final List<String> NAMES_ENDING_IN_QUEST = List.of(
        "Doric's", "Heroes'", "Legends'", "Observatory", "Olaf's", "Waterfall");
    /**
     * Recipe for Disaster's parts, which the tracker names "RFD: ...". The
     * parts after the first say who was freed or saved; these titles are
     * matched by that name rather than word for word, as they are not in
     * RuneLite's fixtures.
     */
    private static final Map<String, String> RFD_PARTS = rfdParts();

    /** "'One Small Favour' completed!" */
    private static final Pattern QUOTED = Pattern.compile("'(.+)' completed[!.]?");
    /** "Sins of the Father forgiven!" */
    private static final Pattern FORGIVEN = Pattern.compile("(.+) forgiven[!.]?");
    /** "You have completely completed Rag and Bone Man!": the second part. */
    private static final Pattern COMPLETELY =
        Pattern.compile("(?i:you have completely completed) (?:the )?(.+?)[!.]?");
    /**
     * "You have completed The Corsair Curse!", "... completed the Waterfall
     * Quest!" and "You have... kind of... completed the Hazeel Cult Quest!".
     * A lower-case "the" is the title's; a capital one is the quest's.
     */
    private static final Pattern COMPLETED = Pattern.compile(
        "(?i:you have)[.\\s]*(?:(?i:kind of)[.\\s]*)?(?i:completed) (?:the )?(.+?)[!.]?");

    public DetectedEvent detect(String questName)
    {
        String label = questName == null || questName.trim().isEmpty()
            ? null : questName.trim();
        return DetectedEvent.builder()
            .type(FateEventType.QUEST)
            .canonicalLabel(label)
            .confidence(label == null ? EventConfidence.UNCERTAIN : EventConfidence.EXACT)
            .detectorId("quest-widget-v1")
            .detectorVersion(1)
            .evidence(Collections.<String, Object>singletonMap("rewardWidget", true))
            .build();
    }

    /**
     * The quest a reward scroll's title (its tags removed) names, as the
     * tracker names it, or null for a line that names no quest.
     */
    public static String questName(String title)
    {
        String text = title == null ? "" : title.trim();
        if (text.isEmpty()) return null;
        String lower = text.toLowerCase(Locale.ROOT);
        if (lower.contains("defeated the culinaromancer")) return "RFD: Finale";
        if (lower.contains("another cook's quest")) return "RFD: The Cook";
        if (lower.contains("freed") || lower.contains("saved"))
        {
            for (Map.Entry<String, String> part : RFD_PARTS.entrySet())
            {
                if (lower.contains(part.getKey())) return part.getValue();
            }
        }
        Matcher match = QUOTED.matcher(text);
        if (match.matches()) return match.group(1).trim();
        match = FORGIVEN.matcher(text);
        if (match.matches()) return match.group(1).trim();
        match = COMPLETELY.matcher(text);
        if (match.matches()) return withoutQuestSuffix(match.group(1)) + " II";
        match = COMPLETED.matcher(text);
        if (match.matches()) return withoutQuestSuffix(match.group(1));
        return null;
    }

    /** The name without a trailing "Quest", unless the quest's name ends in it. */
    private static String withoutQuestSuffix(String name)
    {
        String trimmed = name.trim();
        if (!trimmed.toLowerCase(Locale.ROOT).endsWith(" quest")) return trimmed;
        String stripped = trimmed.substring(0, trimmed.length() - " quest".length()).trim();
        return NAMES_ENDING_IN_QUEST.contains(stripped) ? stripped + " Quest" : stripped;
    }

    private static Map<String, String> rfdParts()
    {
        Map<String, String> parts = new LinkedHashMap<>();
        parts.put("mountain dwarf", "RFD: Dwarf");
        parts.put("goblin generals", "RFD: Goblins");
        parts.put("pirate pete", "RFD: Pirate Pete");
        parts.put("lumbridge guide", "RFD: Lumbridge Guide");
        parts.put("evil dave", "RFD: Evil Dave");
        parts.put("skrach", "RFD: Skrach Uglogwee");
        parts.put("sir amik varze", "RFD: Sir Amik Varze");
        parts.put("awowogei", "RFD: King Awowogei");
        return Collections.unmodifiableMap(parts);
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;
import com.fatelocked.storage.LocalFileMerge;
import com.google.gson.Gson;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

public final class SlayerTaskDetector
{
    private final Gson gson;
    private final Path path;
    private State state;

    public SlayerTaskDetector(Gson gson, Path path) throws IOException
    {
        this.gson = gson;
        this.path = path;
        state = load();
    }

    /**
     * Read the saved assignment. A damaged or unreadable file (truncated,
     * hand-edited, or written by a different version) is moved aside as
     * {@code .corrupt-<millis>} and the detector starts with no assignment,
     * the same recovery the event history uses, so it can never stop the
     * plugin from starting.
     */
    private State load() throws IOException
    {
        if (!Files.exists(path)) return new State();
        try
        {
            State loaded = gson.fromJson(
                new String(Files.readAllBytes(path), StandardCharsets.UTF_8),
                State.class);
            return loaded == null ? new State() : loaded;
        }
        catch (RuntimeException error)
        {
            Files.move(path,
                path.resolveSibling(path.getFileName() + ".corrupt-"
                    + System.currentTimeMillis()),
                StandardCopyOption.REPLACE_EXISTING);
            return new State();
        }
    }

    public synchronized void assignment(
        String name, String master, int count, boolean joinedMidAssignment)
        throws IOException
    {
        State next = new State();
        next.name = name;
        next.master = master;
        next.startCount = count;
        next.joinedMidAssignment = joinedMidAssignment;
        LocalFileMerge.update(path, current -> bytes(next));
        state = next;
    }

    /**
     * The task complete, once. The saved state is re-read under the file's
     * lock, so another RuneLite on the same account can't complete the same
     * task a second time, and a task it saved is the one completed here.
     */
    public synchronized Optional<DetectedEvent> completion(String signature)
        throws IOException
    {
        State[] completed = {null};
        LocalFileMerge.update(path, current -> {
            State saved = current == null ? state : parse(current);
            state = saved;
            if (saved.name == null || saved.completed) return null;
            State done = copy(saved);
            done.completed = true;
            completed[0] = done;
            return bytes(done);
        });
        if (completed[0] == null) return Optional.empty();
        state = completed[0];
        Map<String, Object> evidence = new LinkedHashMap<>();
        evidence.put("assignment", state.name);
        if (state.master != null) evidence.put("master", state.master);
        evidence.put("startCount", state.startCount);
        evidence.put("completionSignature", signature == null ? "" : signature);
        evidence.put("joinedMidAssignment", state.joinedMidAssignment);
        return Optional.of(DetectedEvent.builder()
            .type(FateEventType.SLAYER_TASK)
            .canonicalLabel(state.name)
            .confidence(EventConfidence.UNCERTAIN)
            .detectorId("slayer-task-v1")
            .detectorVersion(1)
            .evidence(evidence)
            .build());
    }

    private byte[] bytes(State value)
    {
        return gson.toJson(value).getBytes(StandardCharsets.UTF_8);
    }

    /** The saved state; a damaged file is moved aside, and counts as no assignment. */
    private State parse(byte[] current) throws IOException
    {
        try
        {
            State loaded = gson.fromJson(new String(current, StandardCharsets.UTF_8), State.class);
            return loaded == null ? new State() : loaded;
        }
        catch (RuntimeException error)
        {
            LocalFileMerge.moveAside(path);
            return new State();
        }
    }

    private static State copy(State source)
    {
        State copy = new State();
        copy.name = source.name;
        copy.master = source.master;
        copy.startCount = source.startCount;
        copy.joinedMidAssignment = source.joinedMidAssignment;
        copy.completed = source.completed;
        return copy;
    }

    private static final class State
    {
        String name;
        String master;
        int startCount;
        boolean joinedMidAssignment;
        boolean completed;
    }
}

package com.fatelocked.detectors;

import com.fatelocked.events.EventConfidence;
import com.fatelocked.events.FateEventType;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;

/**
 * Raid completions, from the reward chest's loot. Boss kills are
 * BossKillDetectorV2's alone: a combat level says nothing about whether a
 * monster is a boss (a Mithril dragon is level 304, and Obor 106).
 */
public class RaidDetector
{
    private static final Set<String> RAIDS = new HashSet<>(Arrays.asList(
        "chambers of xeric", "theatre of blood", "tombs of amascut"));

    public Optional<DetectedEvent> detect(String lootType, String name, int combatLevel)
    {
        String normalized = name == null ? "" : name.trim().toLowerCase();
        if ("EVENT".equals(lootType) && RAIDS.contains(normalized))
        {
            return Optional.of(DetectedEvent.builder()
                .type(FateEventType.RAID_COMPLETION)
                .canonicalLabel(name)
                .confidence(EventConfidence.EXACT)
                .detectorId("raid-loot-v1")
                .detectorVersion(1)
                .evidence(java.util.Collections.<String, Object>singletonMap(
                    "combatLevel", combatLevel))
                .build());
        }
        return Optional.empty();
    }
}

