    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showHud())
        {
            return null;
        }

        FateLockedBundle bundle = plugin.getBundle();
        if (bundle.isEmpty()) return null; // no rules yet: nothing to show
        FateLockedBundle.RunState state = bundle.getState();

        // Fixed width so long area names ("Draynor Village · Misthalin") sit on
        // one line instead of wrapping to three.
        panelComponent.setPreferredSize(new Dimension(165, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text("Fate Locked")
            .color(GOLD)
            .build());

        if (state != null)
        {
            StringBuilder keyStr = new StringBuilder(String.valueOf(state.getKeys()));
            if (state.getSpecialKeys() > 0) keyStr.append(" · O").append(state.getSpecialKeys());
            if (state.getChaosKeys() > 0) keyStr.append(" · C").append(state.getChaosKeys());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Keys")
                .right(keyStr.toString())
                .rightColor(GOLD)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Fate")
                .right(String.valueOf(state.getFatePoints()))
                .rightColor(Color.WHITE)
                .build());
            String buff = state.getActiveBuff();
            if (buff != null && !"NONE".equals(buff))
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Buff")
                    .right(buff)
                    .rightColor("GREED".equals(buff) ? GOLD : GREEN)
                    .build());
            }
            List<String> goals = state.getPinnedGoals();
            if (goals != null && !goals.isEmpty())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Goal")
                    .right(truncate(goals.get(0), 20))
                    .rightColor(Color.WHITE)
                    .build());
            }
            String bound = AccountBinding.boundAccount(bundle);
            if (bound != null)
            {
                Player me = client.getLocalPlayer();
                String current = me == null ? null : me.getName();
                boolean match = current == null
                    || AccountBinding.sameAccount(bound, current);
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Account")
                    .right(truncate(bound, 14) + (match ? "" : " ⚠"))
                    .rightColor(match ? GREEN : RED)
                    .build());
            }
        }

        Player local = client.getLocalPlayer();
        WorldPoint wp = local == null ? null : local.getWorldLocation();
        if (wp != null)
        {
            CanonicalChunk chunk = CanonicalChunk.of(wp);
            String label = bundle.labelAt(chunk);
            FateLockedBundle.LockState lock = bundle.lockStateAt(chunk);

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Here")
                .right(label == null ? "(" + chunk.getCx() + ", " + chunk.getCy() + ")" : truncate(label, 22))
                .rightColor(Color.WHITE)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Status")
                .right(lock == FateLockedBundle.LockState.UNLOCKED ? "Unlocked"
                    : lock == FateLockedBundle.LockState.LOCKED ? "LOCKED" : "Unknown")
                .rightColor(lock == FateLockedBundle.LockState.UNLOCKED ? GREEN
                    : lock == FateLockedBundle.LockState.LOCKED ? RED : GRAY)
                .build());

            if (config.showNearest() && bundle.hasNearestData())
            {
                // Recompute only when the player crosses a chunk boundary or a
                // new bundle is imported — render() runs per frame.
                if (bundle != cachedBundle || !chunk.equals(cachedChunk))
                {
                    cachedBundle = bundle;
                    cachedChunk = chunk;
                    cachedBank = bundle.nearestUsableBank(chunk);
                    cachedShop = bundle.nearestUsableShop(chunk);
                }
                addNearestLine("Bank", cachedBank, chunk, bundle);
                addNearestLine("Shop", cachedShop, chunk, bundle);
            }
        }

        if (bundle.getTotalChunks() > 0)
        {
            int pct = (int) Math.round(100.0 * bundle.getUnlockedChunks() / bundle.getTotalChunks());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Unlocked")
                .right(bundle.getUnlockedAreas() + "/" + bundle.getTotalAreas() + " · " + pct + "%")
                .rightColor(GOLD)
                .build());
        }

        String slayerWarn = plugin.getSlayerTaskWarn();
        if (slayerWarn != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Slayer")
                .right(truncate(slayerWarn, 18) + " ⚠")
                .leftColor(RED)
                .rightColor(RED)
                .build());
        }

        String overTier = plugin.getOverTierSummary();
        if (overTier != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Over-tier")
                .right(truncate(overTier, 20))
                .leftColor(RED)
                .rightColor(RED)
                .build());
        }

        return super.render(graphics);
    }

    /** One "Bank:" / "Shop:" line: "here ✓", "<Area> · <dist> <dir>", or "none unlocked". */
    private void addNearestLine(String label, FateLockedBundle.Nearest near,
                                CanonicalChunk from, FateLockedBundle bundle)
    {
        if (near == null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .right("none unlocked")
                .rightColor(RED)
                .build());
            return;
        }
        if (near.getDistanceChunks() == 0)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .right("here ✓")
                .rightColor(GREEN)
                .build());
            return;
        }
        String area = bundle.labelAt(near.getChunk());
        String name = area == null
            ? "(" + near.getChunk().getCx() + ", " + near.getChunk().getCy() + ")"
            : area.split(" · ")[0];
        String dir = compass(near.getChunk().getCx() - from.getCx(),
            near.getChunk().getCy() - from.getCy());
        panelComponent.getChildren().add(LineComponent.builder()
            .left(label)
            .right(truncate(name, 13) + " · " + near.getDistanceChunks() + " " + dir)
            .rightColor(Color.WHITE)
            .build());
    }

    /** 8-way compass point for a chunk delta; a 2:1 dominant axis collapses
     *  to its cardinal (dx=+5,dy=+1 → "E"; dx=+5,dy=+4 → "NE"). World Y
     *  grows northward. Never called with dx=dy=0 (distance 0 is "here"). */
    static String compass(int dx, int dy)
    {
        String ns = dy > 0 ? "N" : "S";
        String ew = dx > 0 ? "E" : "W";
        if (dy == 0 || Math.abs(dx) >= 2 * Math.abs(dy)) return ew;
        if (dx == 0 || Math.abs(dy) >= 2 * Math.abs(dx)) return ns;
        return ns + ew;
    }

    private static String truncate(String s, int max)
    {
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Full-viewport red border flash when the player crosses into locked
 * territory — the visual counterpart to the warning sound. The plugin sets
 * {@code flashUntil}; this overlay pulses a fading frame until it expires.
 */
public class FateLockedFlashOverlay extends Overlay
{
    private static final int FRAME_THICKNESS = 14;

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedFlashOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.flashOnLocked())
        {
            return null;
        }
        long until = plugin.getLockedFlashUntil();
        long now = System.currentTimeMillis();
        if (now >= until)
        {
            return null;
        }

        // Fade out over the flash window, with a 4 Hz pulse on top.
        float remaining = (until - now) / (float) FateLockedPlugin.LOCKED_FLASH_MS;
        float pulse = 0.6f + 0.4f * (float) Math.abs(Math.sin(now / 125.0));
        int alpha = Math.min(255, Math.max(0, (int) (200 * remaining * pulse)));

        int w = client.getCanvasWidth();
        int h = client.getCanvasHeight();
        g.setColor(new Color(239, 68, 68, alpha));
        g.setStroke(new BasicStroke(FRAME_THICKNESS));
        g.drawRect(FRAME_THICKNESS / 2, FRAME_THICKNESS / 2, w - FRAME_THICKNESS, h - FRAME_THICKNESS);
        return null;
    }
}

package com.fatelocked;

import java.time.Instant;

/** The last rules the plugin accepted, as kept for the next start. */
final class SavedRules
{
    private final String payload;
    private final FateLockedPlugin.RulesSource source;
    private final Instant savedAt;
    private final String relayVersion;
    private final String pairingTag;

    /**
     * @param payload the bundle as the plugin received it, plain or "FLGZ:"
     * @param relayVersion the relay's version of these rules; relay rules only
     * @param pairingTag PairingSupport.tag of the pairing that sent them; relay rules only
     */
    SavedRules(
        String payload,
        FateLockedPlugin.RulesSource source,
        Instant savedAt,
        String relayVersion,
        String pairingTag)
    {
        if (payload == null || payload.trim().isEmpty() || savedAt == null
            || source == null || source == FateLockedPlugin.RulesSource.NONE)
        {
            throw new IllegalArgumentException("saved rules need a payload, a source and a time");
        }
        this.payload = payload;
        this.source = source;
        this.savedAt = savedAt;
        this.relayVersion = relayVersion;
        this.pairingTag = pairingTag;
    }

    String getPayload()
    {
        return payload;
    }

    FateLockedPlugin.RulesSource getSource()
    {
        return source;
    }

    Instant getSavedAt()
    {
        return savedAt;
    }

    String getRelayVersion()
    {
        return relayVersion;
    }

    String getPairingTag()
    {
        return pairingTag;
    }
}

package com.fatelocked;

/**
 * Why the tracker connection is in its state. SyncMachine picks one with
 * each state; SyncView turns it into the sidebar's words and one action.
 */
enum SyncReason
{
    /** Nothing to add to the state itself. */
    NONE(null),
    /** There is no pairing, so nothing to check. */
    NOT_PAIRED("Not connected"),
    /** Online sync is off; a pairing, if any, is kept. */
    SYNC_OFF("Online sync is off"),
    /** Paired with online sync on, and the tracker has not answered yet. */
    CHECKING("Checking the tracker"),
    /** A pairing started here waits for the player to confirm it in the browser. */
    CONFIRM_IN_BROWSER("Confirm in browser"),
    /** A pairing started here got no profile within 10 minutes. */
    NO_PROFILE("No profile received"),
    /** A re-pairing waits for its profile; the working pairing stays until it arrives. */
    CONFIRM_REPAIR("Confirm the new pairing"),
    /** A re-pairing got no profile within 10 minutes, so the working pairing was kept. */
    REPAIR_ABANDONED("Kept your pairing"),
    /** The relay's copy lapsed: it keeps a profile 24 hours after the last publish. */
    NO_RECENT_UPDATE("No recent update"),
    /** The owner pressed Disconnect in the web tracker: this code will send nothing more. */
    GONE("Disconnected in the web tracker"),
    /** The relay sent older rules than the plugin holds, which it keeps. */
    OLDER_RULES("Tracker has older rules"),
    /** No reply at all: the network, or the relay's host, failed. */
    UNREACHABLE("Could not reach tracker"),
    /** A reply the plugin cannot use, such as a captive portal's page. */
    UNREADABLE("Tracker sent an unreadable reply"),
    /** The relay asked the plugin to slow down. */
    BUSY("Tracker relay is busy; retrying later"),
    /** The relay, or something in front of it, failed. */
    UNAVAILABLE("Tracker is unavailable"),
    /** The tracker's rules are in a newer format than this plugin reads. */
    FUTURE_FORMAT("Plugin update needed"),
    /** The tracker's rules could not be read or used. */
    INVALID_RULES("Could not import tracker data");

    /** The short status the sidebar's Connection row shows, or null for the state's own. */
    final String status;

    SyncReason(String status)
    {
        this.status = status;
    }
}

