import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;

/**
 * Tints the player's current chunk on the main game scene. Gives an at-a-glance
 * sense of the chunk's status (green/red/grey) matching the web app's colors.
 */
public class FateLockedSceneOverlay extends Overlay
{
    private static final Stroke STROKE = new BasicStroke(2f);
    private static final Stroke BORDER_STROKE = new BasicStroke(3.5f);

    @Inject private Client client;
    @Inject private FateLockedPlugin plugin;
    @Inject private FateLockedConfig config;

    @Inject
    FateLockedSceneOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawScene() && !config.highlightLockedBorders() && !config.shadeNearbyLocked()) return null;
        Player local = client.getLocalPlayer();
        if (local == null) return null;
        WorldPoint wp = local.getWorldLocation();
        if (wp == null) return null;

        FateLockedBundle bundle = plugin.getBundle();
        if (bundle.isEmpty()) return null; // no rules yet: nothing to tint
        CanonicalChunk chunk = CanonicalChunk.of(wp);
        int plane = wp.getPlane();

        // Light shading for surrounding locked chunks goes first, under the
        // current-chunk tint and borders.
        if (config.shadeNearbyLocked())
        {
            drawSurroundingLocked(graphics, chunk, plane, bundle);
        }

        if (config.drawScene())
        {
            // Sub-area-aware: a Falador chunk reflects Falador's lock state, not
            // all of Asgarnia's.
            Color color;
            switch (bundle.lockStateAt(chunk))
            {
                case UNLOCKED: color = config.unlockedColor(); break;
                case LOCKED: color = config.lockedColor(); break;
                default: color = config.unauthoredColor(); break;
            }
            drawChunkOutline(graphics, chunk, plane, color);
        }

        if (config.highlightLockedBorders())
        {
            drawLockedBorders(graphics, chunk, plane, bundle);
        }
        return null;
    }

    /**
     * Trace a bright line along any edge of the current chunk that borders a
     * locked chunk — the "danger here" cue right where you'd cross over.
     */
    private void drawLockedBorders(Graphics2D g, CanonicalChunk chunk, int plane, FateLockedBundle bundle)
    {
        int cx = chunk.getCx();
        int cy = chunk.getCy();
        int bx = cx << 6;
        int by = cy << 6;

        Color c = config.lockedColor();
        g.setStroke(BORDER_STROKE);
        g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 255));

        if (isLocked(bundle, cx + 1, cy)) drawEdge(g, bx + 63, by, bx + 63, by + 63, plane); // east
        if (isLocked(bundle, cx - 1, cy)) drawEdge(g, bx, by, bx, by + 63, plane);           // west
        if (isLocked(bundle, cx, cy + 1)) drawEdge(g, bx, by + 63, bx + 63, by + 63, plane); // north
        if (isLocked(bundle, cx, cy - 1)) drawEdge(g, bx, by, bx + 63, by, plane);           // south
    }

    private static boolean isLocked(FateLockedBundle bundle, int cx, int cy)
    {
        return bundle.lockStateAt(new CanonicalChunk(cx, cy)) == FateLockedBundle.LockState.LOCKED;
    }

    /**
     * Lightly tint every locked chunk overlapping the loaded scene (except the
     * one the player is standing in, which gets the full treatment elsewhere).
     */
    private void drawSurroundingLocked(Graphics2D g, CanonicalChunk current, int plane, FateLockedBundle bundle)
    {
        int baseX = client.getBaseX();
        int baseY = client.getBaseY();
        int cxMin = baseX >> 6, cxMax = (baseX + Constants.SCENE_SIZE - 1) >> 6;
        int cyMin = baseY >> 6, cyMax = (baseY + Constants.SCENE_SIZE - 1) >> 6;

        Color light = faint(config.lockedColor());
        g.setColor(light);
        for (int cx = cxMin; cx <= cxMax; cx++)
        {
            for (int cy = cyMin; cy <= cyMax; cy++)
            {
                if (cx == current.getCx() && cy == current.getCy()) continue;
                CanonicalChunk c = new CanonicalChunk(cx, cy);
                if (bundle.lockStateAt(c) != FateLockedBundle.LockState.LOCKED) continue;
                Polygon p = chunkScenePolyClamped(c, plane);
                if (p != null) g.fillPolygon(p);
            }
        }
    }

    /** Chunk outline polygon clipped to the loaded scene, so partly-visible chunks still draw. */
    private Polygon chunkScenePolyClamped(CanonicalChunk chunk, int plane)
    {
        int minX = client.getBaseX(), minY = client.getBaseY();
        int maxX = minX + Constants.SCENE_SIZE - 1, maxY = minY + Constants.SCENE_SIZE - 1;
        int x0 = Math.max(chunk.getCx() << 6, minX);
        int y0 = Math.max(chunk.getCy() << 6, minY);
        int x1 = Math.min((chunk.getCx() << 6) + 63, maxX);
        int y1 = Math.min((chunk.getCy() << 6) + 63, maxY);
        if (x0 > x1 || y0 > y1) return null; // no overlap with the scene

        int[][] cs = { { x0, y0 }, { x1, y0 }, { x1, y1 }, { x0, y1 } };
        Polygon p = new Polygon();
        for (int[] c : cs)
        {
            LocalPoint lp = LocalPoint.fromWorld(client, c[0], c[1]);
            if (lp == null) return null;
            Point cv = Perspective.localToCanvas(client, lp, plane);
            if (cv == null) return null;
            p.addPoint(cv.getX(), cv.getY());
        }
        return p;
    }

    /** A faint version of a color for subtle background shading. */
    private static Color faint(Color c)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(20, Math.min(c.getAlpha(), 110) / 3));
    }

    private void drawEdge(Graphics2D g, int x0, int y0, int x1, int y1, int plane)
    {
        LocalPoint a = LocalPoint.fromWorld(client, x0, y0);
        LocalPoint b = LocalPoint.fromWorld(client, x1, y1);
        if (a == null || b == null) return; // edge off-scene
        Point ca = Perspective.localToCanvas(client, a, plane);
        Point cb = Perspective.localToCanvas(client, b, plane);
        if (ca == null || cb == null) return;
        g.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
    }

    private void drawChunkOutline(Graphics2D g, CanonicalChunk chunk, int plane, Color color)
    {
        int baseX = chunk.getCx() << 6;
        int baseY = chunk.getCy() << 6;

        // Build a polygon around the chunk's perimeter — draw the four corner
        // tiles and let Perspective do the projection.
        LocalPoint[] corners = new LocalPoint[] {
            LocalPoint.fromWorld(client, baseX, baseY),
            LocalPoint.fromWorld(client, baseX + 63, baseY),
            LocalPoint.fromWorld(client, baseX + 63, baseY + 63),
            LocalPoint.fromWorld(client, baseX, baseY + 63)
        };

        Polygon p = new Polygon();
        for (LocalPoint lp : corners)
        {
            if (lp == null) return; // chunk is off-scene
            Point canvas = Perspective.localToCanvas(client, lp, plane);
            if (canvas == null) return;
            p.addPoint(canvas.getX(), canvas.getY());
        }

        g.setStroke(STROKE);
        g.setColor(color);
        g.fillPolygon(p);
        g.setColor(new Color(
            Math.min(color.getRed() + 30, 255),
            Math.min(color.getGreen() + 30, 255),
            Math.min(color.getBlue() + 30, 255),
            220));
        g.drawPolygon(p);
    }
}

package com.fatelocked;

import net.runelite.client.callback.ClientThread;

/**
 * The one way onto the client thread, where all plugin state changes. The
 * sidebar, the config panel, overlay clicks and startUp run on the Swing
 * thread, and file reads and relay replies on other threads; each hands its
 * work over here.
 *
 * Work always goes through ClientThread.invoke(Runnable), which runs it at
 * once on the client thread and on the next tick from anywhere else, never
 * through the BooleanSupplier overload, which re-runs a task that returns
 * false on every tick. One gate belongs to one plugin start: work it queued
 * does nothing once that start has ended.
 */
final class ClientThreadGate
{
    private final ClientThread clientThread;
    private final PluginSession session;

    ClientThreadGate(ClientThread clientThread, PluginSession session)
    {
        this.clientThread = clientThread;
        this.session = session;
    }

    /** The gate of a plugin that is not running: nothing passes it. */
    static ClientThreadGate closed()
    {
        return new ClientThreadGate(null, PluginSession.ended());
    }

    /** Run the task on the client thread: now if already there, else next tick. */
    void run(Runnable task)
    {
        if (!session.isActive())
        {
            return;
        }
        clientThread.invoke(session.guard(task));
    }

    /** Run the task on the next client tick, even when called on the client thread. */
    void runNextTick(Runnable task)
    {
        if (!session.isActive())
        {
            return;
        }
        clientThread.invokeLater(session.guard(task));
    }

    /** The task, for another queue, run only while this gate's start lasts. */
    Runnable guard(Runnable task)
    {
        return session.guard(task);
    }

    /** End this start: work already queued through the gate does nothing. */
    void close()
    {
        session.end();
    }
}

package com.fatelocked;

import java.awt.Color;
import java.awt.Component;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JColorChooser;
import javax.swing.JComponent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;

final class FateLockedConfigBinder
{
    interface ColorChooser
    {
        Color choose(Component parent, String title, Color initialColor);
    }

    private final ConfigManager configManager;
    private final Consumer<String> statusSink;
    private final ColorChooser colorChooser;
    private final Map<String, Runnable> refreshers = new LinkedHashMap<>();

    FateLockedConfigBinder(ConfigManager configManager, Consumer<String> statusSink)
    {
        this(configManager, statusSink, JColorChooser::showDialog);
    }

    FateLockedConfigBinder(ConfigManager configManager, Consumer<String> statusSink,
        ColorChooser colorChooser)
    {
        this.configManager = configManager;
        this.statusSink = statusSink;
        this.colorChooser = colorChooser;
    }

    JCheckBox booleanSetting(String key, String label, BooleanSupplier current)
    {
        return booleanSetting(key, label, current, () -> true);
    }

    JCheckBox booleanSetting(String key, String label, BooleanSupplier current,
        BooleanSupplier confirmEnable)
    {
        final boolean[] confirmed = {current.getAsBoolean()};
        JCheckBox control = new JCheckBox(label, confirmed[0]);
        control.addActionListener(event -> {
            boolean selected = control.isSelected();
            if (selected && !confirmEnable.getAsBoolean())
            {
                control.setSelected(confirmed[0]);
                return;
            }
            save(key, selected, () -> confirmed[0] = selected,
                () -> control.setSelected(confirmed[0]));
        });
        refreshers.put(key, () -> {
            Boolean value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Boolean.class);
            if (value != null)
            {
                confirmed[0] = value;
                control.setSelected(value);
            }
        });
        return control;
    }

    JComponent keybindSetting(String key, String label, Supplier<Keybind> current)
    {
        final Keybind[] confirmed = {keybindOrNotSet(current.get())};
        KeybindCaptureButton control = new KeybindCaptureButton(confirmed[0], value -> { });
        control.setToolTipText(label);
        control.setCaptureListener(value -> save(key, value,
            () -> confirmed[0] = value,
            () -> control.setKeybind(confirmed[0])));
        refreshers.put(key, () -> {
            Keybind value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Keybind.class);
            if (value != null)
            {
                confirmed[0] = value;
                control.setKeybind(value);
            }
        });
        return control;
    }

    JComponent colorSetting(String key, String label, Supplier<Color> current)
    {
        final Color[] confirmed = {current.get()};
        JButton control = new JButton(label);
        applyColor(control, confirmed[0]);
        control.addActionListener(event -> {
            Color selected = colorChooser.choose(control, label, confirmed[0]);
            if (selected != null)
            {
                save(key, selected, () -> {
                    confirmed[0] = selected;
                    applyColor(control, selected);
                }, () -> applyColor(control, confirmed[0]));
            }
        });
        refreshers.put(key, () -> {
            Color value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Color.class);
            if (value != null)
            {
                confirmed[0] = value;
                applyColor(control, value);
            }
        });
        return control;
    }

    void refresh(String key)
    {
        Runnable refresher = refreshers.get(key);
        if (refresher != null)
        {
            refresher.run();
        }
    }

    Set<String> keys()
    {
        return Collections.unmodifiableSet(new LinkedHashSet<>(refreshers.keySet()));
    }

    private void save(String key, Object value, Runnable confirmed, Runnable rollback)
    {
        try
        {
            configManager.setConfiguration(FateLockedConfig.GROUP, key, value);
            confirmed.run();
        }
        catch (RuntimeException error)
        {
            rollback.run();
            statusSink.accept("couldn't save setting");
        }
    }

    private static void applyColor(JButton control, Color color)
    {
        Color preview = color == null
            ? Color.BLACK
            : new Color(color.getRed(), color.getGreen(), color.getBlue());
        control.setBackground(preview);
    }

    private static Keybind keybindOrNotSet(Keybind keybind)
    {
        return keybind == null ? Keybind.NOT_SET : keybind;
    }
}

package com.fatelocked;

import java.time.Duration;
import java.time.Instant;

/**
 * The tracker connection's state and timing: which relay version the plugin
 * holds, when the relay last confirmed it, when the next automatic check is
 * due, and what the sidebar says. Every transition takes the time it
 * happened and returns the snapshot to show, or changes only the timing.
 * No network, no clock, no threads: TrackerConnectionController owns those
 * and calls this under its lock.
 */
final class SyncMachine
{
    static final long CONNECTED_POLL_SECONDS = 60;
    /** How often a healthy connection is checked while the player is logged out. */
    static final long LOGGED_OUT_POLL_SECONDS = 5 * 60;
    static final long WAITING_POLL_SECONDS = 5;
    static final long FAILURE_BACKOFF_SECONDS = 30;
    /**
     * The longest a failure waits: well inside Strict Mode's 15-minute
     * freshness window, so a relay that recovers is noticed before the
     * rules count as old.
     */
    static final long MAX_FAILURE_BACKOFF_SECONDS = 5 * 60;
    /** The longest wait a relay's Retry-After is honoured for. */
    static final long MAX_RETRY_AFTER_SECONDS = 60 * 60;
    /** Check now works at most this often. */
    static final long CHECK_NOW_SECONDS = 10;
    /** How long a pairing started here waits for the browser to publish. */
    static final long PAIRING_CONFIRM_SECONDS = 10 * 60;
    /** Check every WAITING_POLL_SECONDS this long, then every PAIRING_SLOW_POLL_SECONDS. */
    static final long PAIRING_FAST_POLL_WINDOW_SECONDS = 2 * 60;
    static final long PAIRING_SLOW_POLL_SECONDS = 15;

    private String acceptedVersion;
    /** The relay version the plugin could not import, until something newer arrives. */
    private String rejectedVersion;
    /** Why it could not: a newer format or broken rules. */
    private SyncReason rejectedReason;
    private Instant lastSync;
    private Instant nextCheck = Instant.EPOCH;
    private int consecutiveFailures;
    /** When this session began the current pairing; null once it imports. */
    private Instant pairingStartedAt;
    /** Whether that pairing is a re-pairing, with another still in use until it delivers. */
    private boolean repairing;
    /** Whether the relay said the owner disconnected this pairing. */
    private boolean pairingGone;
    /** When the player last pressed Check now and it counted. */
    private Instant lastCheckNow;
    /** Whether the player is in game; taken as so until the plugin says otherwise. */
    private boolean loggedIn = true;
    /** Until when the relay asked the plugin to wait, or null. */
    private Instant retryAfterUntil;

    /** The relay version of the rules the plugin holds, or null. */
    String acceptedVersion()
    {
        return acceptedVersion;
    }

    /** The relay version the plugin could not import, or null. */
    String rejectedVersion()
    {
        return rejectedVersion;
    }

    /**
     * What the next check sends as If-None-Match: the rejected version while
     * there is one, so the relay answers 304 instead of sending it again,
     * else the version the plugin holds.
     */
    String validator()
    {
        return rejectedVersion != null ? rejectedVersion : acceptedVersion;
    }

    /** When the relay last delivered or confirmed the rules, or null. */
    Instant lastSync()
    {
        return lastSync;
    }

    /**
     * Whether an automatic check is due. If it is, the next tick is reserved
     * while the check is in flight; its reply sets the real cadence.
     */
    boolean checkDue(Instant now)
    {
        if (now.isBefore(nextCheck))
        {
            return false;
        }
        nextCheck = now.plusSeconds(WAITING_POLL_SECONDS);
        return true;
    }

    /**
     * The player logged in or out. Logged out, the rules are not in use, so
     * a healthy connection is checked every 5 minutes instead of every
     * minute. A login makes a check due at once, so the rules are current
     * when play starts, unless the relay has asked the plugin to wait. A
     * loading screen or a hop is not a login: the plugin reports them as
     * still logged in.
     */
    void loggedIn(boolean loggedIn, Instant now)
    {
        boolean login = loggedIn && !this.loggedIn;
        this.loggedIn = loggedIn;
        if (login && nextCheck.isAfter(now))
        {
            nextCheck = retryAfterUntil != null && retryAfterUntil.isAfter(now)
                ? retryAfterUntil : now;
        }
    }

    /** Whether the owner disconnected the pairing in the web tracker. */
    boolean pairingGone()
    {
        return pairingGone;
    }

    /**
     * The owner pressed Disconnect in the web tracker, which no longer sends
     * rules to this code. The rules stay in use, but their version is
     * dropped. Checked every 5 minutes, in case the code comes back.
     */
    TrackerConnectionSnapshot gone(Instant now)
    {
        acceptedVersion = null;
        rejectedVersion = null;
        rejectedReason = null;
        pairingGone = true;
        after(now, LOGGED_OUT_POLL_SECONDS);
        return show(TrackerConnectionState.EXPIRED, SyncReason.GONE);
    }

    /** Whether a re-pairing is waiting for its new pairing to deliver. */
    boolean repairing()
    {
        return repairing;
    }

    /**
     * Whether this session started a first pairing that hasn't delivered:
     * its code has never worked, so a new pairing replaces it without
     * keeping it.
     */
    boolean firstPairingWaiting()
    {
        return pairingStartedAt != null && !repairing;
    }

    /**
     * This session started a new pairing while another works. The rules stay
     * in use, with their sync time, until the new pairing delivers; their
     * version is dropped, so the new code's first check asks for everything.
     */
    TrackerConnectionSnapshot repairStarted(Instant now)
    {
        acceptedVersion = null;
        rejectedVersion = null;
        rejectedReason = null;
        resetChecks();
        pairingStartedAt = now;
        repairing = true;
        pairingGone = false;
        return TrackerConnectionSnapshot.of(
            TrackerConnectionState.WAITING, lastSync, null, SyncReason.CONFIRM_REPAIR, null);
    }

    /** The player cancelled the re-pairing: back to the working pairing, checked at once. */
    TrackerConnectionSnapshot repairCancelled()
    {
        repairing = false;
        pairingStartedAt = null;
        resetChecks();
        return TrackerConnectionSnapshot.of(
            TrackerConnectionState.WAITING, lastSync, null, SyncReason.CHECKING, null);
    }

    /** This session started a pairing and opened the browser. */
    TrackerConnectionSnapshot pairingStarted(Instant now)
    {
        forget();
        pairingStartedAt = now;
        return TrackerConnectionSnapshot.of(
            TrackerConnectionState.WAITING, null, null, SyncReason.CONFIRM_IN_BROWSER, null);
    }

    /** The pairing code changed underneath this session (or was cleared). */
    TrackerConnectionSnapshot pairingReplaced(boolean paired)
    {
        forget();
        pairingStartedAt = null;
        return paired
            ? TrackerConnectionSnapshot.of(
                TrackerConnectionState.WAITING, null, null, SyncReason.CHECKING, null)
            : TrackerConnectionSnapshot.disconnected();
    }

    /** There is no pairing: nothing to check until one appears. */
    TrackerConnectionSnapshot unpaired(Instant now)
    {
        nextCheck = now.plusSeconds(CONNECTED_POLL_SECONDS);
        return TrackerConnectionSnapshot.disconnected();
    }

    /** Online sync was allowed or refused: start over. */
    TrackerConnectionSnapshot networkAccessChanged(boolean allowed, boolean paired)
    {
        forget();
        pairingStartedAt = null;
        return idle(allowed, paired);
    }

    /**
     * Before any check: sync off, with or without a pairing to keep; no
     * pairing; or paired and about to check.
     */
    static TrackerConnectionSnapshot idle(boolean allowed, boolean paired)
    {
        SyncReason reason = !paired ? SyncReason.NOT_PAIRED
            : allowed ? SyncReason.CHECKING : SyncReason.SYNC_OFF;
        return TrackerConnectionSnapshot.of(
            TrackerConnectionState.DISCONNECTED, null, null, reason, null);
    }

    /**
     * A local import replaced the tracker's rules: forget their version, so
     * the next check, due now, fetches the relay copy in full. False when
     * there was no version to forget.
     */
    boolean localRulesReplaced()
    {
        if (acceptedVersion == null)
        {
            return false;
        }
        acceptedVersion = null;
        resetChecks();
        return true;
    }

    /**
     * Saved tracker rules from this pairing came back at startup: hold their
     * version, so the first check asks only whether they are current. False
     * once this session has accepted anything.
     */
    boolean seed(String version)
    {
        if (acceptedVersion != null || lastSync != null)
        {
            return false;
        }
        acceptedVersion = RelayContract.canonicalVersion(version);
        return true;
    }

    /** The relay confirmed the rules the plugin holds. */
    TrackerConnectionSnapshot confirmed(Instant now)
    {
        lastSync = now;
        healthy(now);
        return TrackerConnectionSnapshot.connected(now, acceptedVersion);
    }

    /**
     * A 304 for a version the plugin does not hold. Nothing changes on
     * screen, so this returns null, but the next check waits a full interval
     * instead of the few seconds reserved while this one ran.
     */
    TrackerConnectionSnapshot unconfirmed(Instant now)
    {
        healthy(now);
        return null;
    }

    /** The client thread switched to the relay's rules at this version. */
    TrackerConnectionSnapshot accepted(String version, Instant now)
    {
        acceptedVersion = version;
        rejectedVersion = null;
        rejectedReason = null;
        lastSync = now;
        pairingStartedAt = null;
        repairing = false;
        pairingGone = false;
        healthy(now);
        return TrackerConnectionSnapshot.connected(now, version);
    }

    /**
     * The relay's rules at this version could not be imported, for example
     * a newer bundle format. Remember the version, so later checks ask only
     * whether something newer has arrived.
     */
    TrackerConnectionSnapshot rejected(String version, SyncReason reason, Instant now)
    {
        rejectedVersion = RelayContract.canonicalVersion(version);
        rejectedReason = reason;
        return stillRejected(now);
    }

    /**
     * The relay still has only the version the plugin could not import. The
     * status says why, not when the next check is: another check won't help
     * until the tracker sends something else or the plugin is updated.
     */
    TrackerConnectionSnapshot stillRejected(Instant now)
    {
        failed(now, FAILURE_BACKOFF_SECONDS);
        return show(TrackerConnectionState.IMPORT_FAILED, rejectedReason);
    }

    /**
     * The relay has no profile for this code. While a pairing this session
     * started is waiting for the browser, that is expected: say "Confirm in
     * browser" and keep checking, quickly at first. After 10 minutes, say no
     * profile arrived. Otherwise the relay's copy has lapsed (it keeps one
     * for 24 hours after the web app last published): the pairing still
     * works, and opening the web tracker sends the rules again. The rules
     * stay active, but their version is forgotten, so the next check sends
     * no validator and imports whatever version the relay has next, even
     * an older one after a restore.
     *
     * @param heldVersion whether the request asked about a version the plugin held
     */
    TrackerConnectionSnapshot notFound(boolean heldVersion, Instant now)
    {
        // Whatever the plugin held, or could not import, has gone with the profile.
        acceptedVersion = null;
        rejectedVersion = null;
        rejectedReason = null;
        if (!heldVersion && pairingStartedAt != null)
        {
            long waited = Duration.between(pairingStartedAt, now).getSeconds();
            if (waited < PAIRING_CONFIRM_SECONDS)
            {
                after(now, waited < PAIRING_FAST_POLL_WINDOW_SECONDS
                    ? WAITING_POLL_SECONDS : PAIRING_SLOW_POLL_SECONDS);
                return show(TrackerConnectionState.WAITING,
                    repairing ? SyncReason.CONFIRM_REPAIR : SyncReason.CONFIRM_IN_BROWSER);
            }
            healthy(now);
            if (repairing)
            {
                // The new pairing never arrived: the working one carries on.
                repairing = false;
                pairingStartedAt = null;
                return show(TrackerConnectionState.WAITING, SyncReason.REPAIR_ABANDONED);
            }
            return show(TrackerConnectionState.EXPIRED, SyncReason.NO_PROFILE);
        }
        healthy(now);
        return show(TrackerConnectionState.WAITING, SyncReason.NO_RECENT_UPDATE);
    }

    /**
     * A check failed: back off as failed does, and show the state and why,
     * with when the next check is.
     */
    TrackerConnectionSnapshot failure(
        TrackerConnectionState state, SyncReason reason, Instant now, long minimumSeconds)
    {
        failed(now, minimumSeconds);
        return TrackerConnectionSnapshot.of(state, lastSync, acceptedVersion, reason, nextCheck);
    }

    /**
     * The relay asked the plugin to slow down. A Retry-After is honoured as
     * given, from 30 seconds to an hour, instead of being stretched like a
     * failure's back-off; without one, it backs off like any failure.
     */
    TrackerConnectionSnapshot busy(Instant now, long retryAfterSeconds)
    {
        if (retryAfterSeconds <= 0)
        {
            return failure(TrackerConnectionState.OFFLINE, SyncReason.BUSY,
                now, FAILURE_BACKOFF_SECONDS);
        }
        consecutiveFailures++;
        nextCheck = now.plusSeconds(Math.max(FAILURE_BACKOFF_SECONDS,
            Math.min(retryAfterSeconds, MAX_RETRY_AFTER_SECONDS)));
        retryAfterUntil = nextCheck;
        return TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE,
            lastSync, acceptedVersion, SyncReason.BUSY, nextCheck);
    }

    /**
     * The player pressed Check now: forget the back-off, and make a check due
     * at once. False when they pressed it under 10 seconds ago.
     */
    boolean checkNow(Instant now)
    {
        if (lastCheckNow != null && now.isBefore(lastCheckNow.plusSeconds(CHECK_NOW_SECONDS)))
        {
            return false;
        }
        lastCheckNow = now;
        resetChecks();
        return true;
    }

    /** A check failed: wait longer each time, from minimumSeconds up to 5 minutes. */
    void failed(Instant now, long minimumSeconds)
    {
        int shift = Math.min(consecutiveFailures, 5);
        long delay = minimumSeconds * (1L << shift);
        consecutiveFailures++;
        nextCheck = now.plusSeconds(Math.min(delay, MAX_FAILURE_BACKOFF_SECONDS));
    }

    /** The snapshot for a state and why, with the version and sync time held. */
    TrackerConnectionSnapshot show(TrackerConnectionState state, SyncReason reason)
    {
        return TrackerConnectionSnapshot.of(state, lastSync, acceptedVersion, reason, null);
    }

    private void forget()
    {
        acceptedVersion = null;
        rejectedVersion = null;
        rejectedReason = null;
        repairing = false;
        pairingGone = false;
        lastSync = null;
        resetChecks();
    }

    private void resetChecks()
    {
        consecutiveFailures = 0;
        nextCheck = Instant.EPOCH;
    }

    private void healthy(Instant now)
    {
        after(now, loggedIn ? CONNECTED_POLL_SECONDS : LOGGED_OUT_POLL_SECONDS);
    }

    private void after(Instant now, long seconds)
    {
        consecutiveFailures = 0;
        nextCheck = now.plusSeconds(seconds);
    }

}

package com.fatelocked;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

import java.io.IOException;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Function;

/**
 * Runs the tracker connection: the one relay request, its threads and its
 * locking. What each reply means is RelayContract's; the state and timing
 * that follow are SyncMachine's, always changed under pollLock.
 */
@Slf4j
final class TrackerConnectionController
{
    /**
     * Turns a relay payload into active rules in two steps. prepare runs on
     * the thread that read the reply, so a large bundle is parsed off the
     * game thread; commit runs on the client thread.
     */
    interface RelayBundleImporter<T>
    {
        /** Parse and check the payload: rules to commit, or why there are none. */
        Prepared<T> prepare(String payload);

        /** Switch to the prepared rules, which the relay calls version; false rejects them. */
        boolean commit(T prepared, String version);
    }

    /** What the importer made of a payload. */
    enum ImportVerdict
    {
        OK,
        /** Rules in a newer bundle format than this plugin reads. */
        FUTURE_FORMAT,
        /** Anything else the plugin can't use. */
        INVALID
    }

    /** Rules ready to commit, or the verdict that says why there are none. */
    static final class Prepared<T>
    {
        final ImportVerdict verdict;
        final T rules;

        private Prepared(ImportVerdict verdict, T rules)
        {
            this.verdict = verdict;
            this.rules = rules;
        }

        static <T> Prepared<T> ok(T rules)
        {
            return new Prepared<>(ImportVerdict.OK, rules);
        }

        static <T> Prepared<T> refused(ImportVerdict verdict)
        {
            return new Prepared<>(verdict, null);
        }
    }

    /**
     * A limit on the whole request. OkHttp limits each connect, read and
     * write, but not the whole call unless asked, so a reply that trickled
     * in slowly held the only check for as long as it liked.
     */
    static final Duration CALL_TIMEOUT = Duration.ofSeconds(20);
    /** No real reply comes near this: the relay refuses to store a bundle over 256 KiB. */
    static final long MAX_REPLY_BYTES = 1024 * 1024;

    private final OkHttpClient http;
    private final Gson gson;
    private final TrackerConnectionSettings settings;
    private final Clock clock;
    private final Consumer<Runnable> clientDispatcher;
    private final RelayBundleImporter<?> importer;
    private final Consumer<TrackerConnectionSnapshot> listener;
    private final Object pollLock = new Object();

    private final SyncMachine machine = new SyncMachine();
    /** Logs each kind of unreadable reply, and a repeat at most every 15 minutes. */
    private final RepeatedValueLimiter unreadableLimiter =
        new RepeatedValueLimiter(Duration.ofMinutes(15).toMillis());
    private long generation;
    private RelayPollToken activePoll;
    private String currentIdentityCode;
    /**
     * A re-pairing's new code, checked instead of the saved one until it
     * delivers rules and replaces it; null otherwise.
     */
    private String pendingCode;
    private boolean stopped;
    private volatile TrackerConnectionSnapshot snapshot =
        TrackerConnectionSnapshot.disconnected();

    TrackerConnectionController(
        OkHttpClient http,
        Gson gson,
        TrackerConnectionSettings settings,
        Clock clock,
        Consumer<Runnable> clientDispatcher,
        RelayBundleImporter<?> importer,
        Consumer<TrackerConnectionSnapshot> listener)
    {
        this(http, CALL_TIMEOUT, gson, settings, clock, clientDispatcher, importer, listener);
    }

    TrackerConnectionController(
        OkHttpClient http,
        Duration callTimeout,
        Gson gson,
        TrackerConnectionSettings settings,
        Clock clock,
        Consumer<Runnable> clientDispatcher,
        RelayBundleImporter<?> importer,
        Consumer<TrackerConnectionSnapshot> listener)
    {
        this.http = http.newBuilder()
            .callTimeout(callTimeout.toMillis(), TimeUnit.MILLISECONDS)
            .build();
        this.gson = gson;
        this.settings = settings;
        this.clock = clock;
        this.clientDispatcher = clientDispatcher;
        this.importer = importer;
        this.listener = listener;
        this.currentIdentityCode = settings.pairingCode();
        snapshot = SyncMachine.idle(settings.networkAccessAllowed(), settings.isPaired())
            .forPairing(settings.pairingCode());
        listener.accept(snapshot);
    }

    String beginPairing()
    {
        if (!settings.networkAccessAllowed())
        {
            throw new IllegalStateException("Online sync requires consent");
        }
        String code = PairingSupport.newCode();
        synchronized (pollLock)
        {
            // A stopped controller belongs to a plugin that was turned off;
            // a Connect queued before that must not bring it back.
            if (stopped)
            {
                throw new IllegalStateException("The tracker connection has stopped");
            }
            abandonCheckLocked();
            if (settings.isPaired() && !machine.firstPairingWaiting() && !machine.pairingGone())
            {
                // Keep the working pairing until the new one delivers.
                pendingCode = code;
                showLocked(machine.repairStarted(clock.instant()));
            }
            else
            {
                settings.replacePairingCode(code);
                settings.clearLegacySettings();
                pendingCode = null;
                currentIdentityCode = code;
                showLocked(machine.pairingStarted(clock.instant()));
            }
        }
        return PairingSupport.trackerPairingUrl(code);
    }

    /** The player cancelled a re-pairing: back to the working pairing at once. */
    void cancelRepair()
    {
        synchronized (pollLock)
        {
            if (stopped || pendingCode == null)
            {
                return;
            }
            abandonCheckLocked();
            pendingCode = null;
            showLocked(machine.repairCancelled());
        }
    }

    /** The code checks go to: a re-pairing's new code, or the saved one. */
    String activeCode()
    {
        synchronized (pollLock)
        {
            return activeCodeLocked();
        }
    }

    private String activeCodeLocked()
    {
        return pendingCode != null ? pendingCode : settings.pairingCode();
    }


    void poll()
    {
        if (!settings.networkAccessAllowed())
        {
            networkAccessOff();
            return;
        }
        String saved = settings.pairingCode();
        String code;
        String version;
        boolean clearLegacy = false;
        synchronized (pollLock)
        {
            if (stopped) return;
            if (!equal(saved, currentIdentityCode))
            {
                // Replaced underneath this session: a re-pairing was for the old one.
                abandonCheckLocked();
                pendingCode = null;
                currentIdentityCode = saved;
                clearLegacy = !saved.isEmpty();
                showLocked(machine.pairingReplaced(!saved.isEmpty()));
            }
            code = activeCodeLocked();
            if (code.isEmpty())
            {
                showLocked(machine.unpaired(clock.instant()));
                return;
            }
            version = machine.acceptedVersion();
        }
        if (clearLegacy)
        {
            settings.clearLegacySettings();
        }
        RelayPollToken token = beginPoll(code, version);
        if (token == null)
        {
            return;
        }

        Request.Builder builder = new Request.Builder()
            .url(TrackerConnectionSettings.RELAY_BASE_URL
                + "/r/" + token.code)
            .get();
        String validator = token.rejectedVersion != null
            ? token.rejectedVersion : token.acceptedVersion;
        if (validator != null)
        {
            builder.header("If-None-Match", validator);
        }
        Request request = builder.build();
        try
        {
            Call call = http.newCall(request);
            synchronized (pollLock)
            {
                // Abandoned already, by a stop, a consent change or a new pairing.
                if (activePoll != token)
                {
                    return;
                }
                token.call = call;
            }
            call.enqueue(new Callback()
            {
                @Override
                public void onFailure(Call call, IOException error)
                {
                    failCheck(token, TrackerConnectionState.OFFLINE,
                        SyncReason.UNREACHABLE, SyncMachine.FAILURE_BACKOFF_SECONDS);
                }

                @Override
                public void onResponse(Call call, Response response)
                {
                    handleResponse(token, response);
                }
            });
        }
        catch (RuntimeException error)
        {
            failCheck(token, TrackerConnectionState.OFFLINE,
                SyncReason.UNREACHABLE, SyncMachine.FAILURE_BACKOFF_SECONDS);
        }
    }

    void pollIfDue()
    {
        if (!settings.networkAccessAllowed())
        {
            networkAccessOff();
            return;
        }
        synchronized (pollLock)
        {
            if (stopped || !machine.checkDue(clock.instant()))
            {
                return;
            }
        }
        poll();
    }

    /**
     * A check found consent off. Reset once; the ticks that follow find
     * nothing held and nothing in flight, and change nothing.
     */
    private void networkAccessOff()
    {
        synchronized (pollLock)
        {
            if (activePoll == null
                && machine.acceptedVersion() == null
                && snapshot.getState() == TrackerConnectionState.DISCONNECTED)
            {
                return;
            }
        }
        networkAccessChanged();
    }

    void networkAccessChanged()
    {
        synchronized (pollLock)
        {
            abandonCheckLocked();
            pendingCode = null;
            showLocked(machine.networkAccessChanged(
                settings.networkAccessAllowed(), settings.isPaired()));
        }
    }

    /**
     * A file or clipboard import has replaced the rules this controller
     * accepted. Forget the accepted version, so the next check fetches the
     * relay copy in full instead of hearing "unchanged", and make that check
     * due now: while paired, the tracker's rules win over a local import.
     */
    void localRulesReplacedTrackerRules()
    {
        synchronized (pollLock)
        {
            if (machine.localRulesReplaced())
            {
                abandonCheckLocked();
            }
        }
    }

    /**
     * Rules this pairing's relay sent were restored from the last start.
     * Remember their version, so the first check asks only whether they are
     * still current (If-None-Match) and a 304 confirms them; newer rules
     * still arrive in full. Ignored once this start has accepted anything.
     */
    void seedAcceptedVersion(String version)
    {
        if (version == null || version.trim().isEmpty())
        {
            return;
        }
        synchronized (pollLock)
        {
            if (!stopped)
            {
                machine.seed(version.trim());
            }
        }
    }

    void stop()
    {
        synchronized (pollLock)
        {
            stopped = true;
            abandonCheckLocked();
            pendingCode = null;
            showLocked(TrackerConnectionSnapshot.disconnected());
        }
    }

    /**
     * Drop the check in flight, if any: cancel its request, and make its
     * reply, if one still comes, change nothing.
     */
    private void abandonCheckLocked()
    {
        generation++;
        if (activePoll != null && activePoll.call != null)
        {
            activePoll.call.cancel();
        }
        activePoll = null;
    }

    /** The player logged in or out; see SyncMachine.loggedIn. */
    void loggedIn(boolean loggedIn)
    {
        synchronized (pollLock)
        {
            machine.loggedIn(loggedIn, clock.instant());
        }
    }

    /**
     * The player pressed Check now: forget the back-off and make a check due
     * at once, for the next tick to send. False when there is nothing to
     * check, or when they pressed it under 10 seconds ago.
     */
    boolean checkNow()
    {
        if (!settings.networkAccessAllowed() || !settings.isPaired())
        {
            return false;
        }
        synchronized (pollLock)
        {
            return !stopped && machine.checkNow(clock.instant());
        }
    }

    TrackerConnectionSnapshot snapshot()
    {
        return snapshot;
    }

    /** Whether a relay request is in flight; its handling ends by clearing this. */
    boolean pollInFlight()
    {
        synchronized (pollLock)
        {
            return activePoll != null;
        }
    }

    private RelayPollToken beginPoll(String code, String version)
    {
        synchronized (pollLock)
        {
            if (stopped || !settings.networkAccessAllowed() || activePoll != null
                || !code.equals(activeCodeLocked())
                || !equal(version, machine.acceptedVersion()))
            {
                return null;
            }
            RelayPollToken token = new RelayPollToken(generation, code,
                RelayContract.canonicalVersion(version), machine.rejectedVersion());
            activePoll = token;
            return token;
        }
    }

    private void handleResponse(
        RelayPollToken token, Response response)
    {
        try (Response current = response)
        {
            if (!isPollCurrent(token))
            {
                clearPoll(token);
                return;
            }
            RelayContract.Reply reply = classify(token, current);
            switch (reply.outcome)
            {
                case UNCHANGED:
                    confirmUnchanged(token);
                    return;
                case UNCONFIRMED:
                    // Nothing to show, but the next check waits its turn.
                    showIfCurrent(token, now -> machine.unconfirmed(now));
                    clearPoll(token);
                    return;
                case MISSING:
                    handleNotFound(token);
                    return;
                case GONE:
                    showIfCurrent(token, now -> machine.gone(now));
                    clearPoll(token);
                    return;
                case BUSY:
                    showIfCurrent(token, now -> machine.busy(now, reply.retryAfterSeconds));
                    clearPoll(token);
                    return;
                case UNAVAILABLE:
                    failCheck(token, TrackerConnectionState.OFFLINE,
                        SyncReason.UNAVAILABLE, SyncMachine.FAILURE_BACKOFF_SECONDS);
                    return;
                case RULES:
                    if (!isPollCurrent(token))
                    {
                        clearPoll(token);
                        return;
                    }
                    if (publishIfCurrent(token, TrackerConnectionState.IMPORTING))
                    {
                        prepareImport(importer, token, reply.payload,
                            String.valueOf(reply.version));
                    }
                    return;
                case UNREADABLE:
                    // A captive portal's page or a broken reply: say so,
                    // instead of backing off with the old status showing.
                    if (unreadableLimiter.shouldReport(reply.detail, clock.millis()))
                    {
                        log.warn("Tracker relay sent an unreadable reply: {}", reply.detail);
                    }
                    failCheck(token, TrackerConnectionState.OFFLINE,
                        SyncReason.UNREADABLE, SyncMachine.FAILURE_BACKOFF_SECONDS);
                    return;
                case STILL_REJECTED:
                    showIfCurrent(token, now -> machine.stillRejected(now));
                    clearPoll(token);
                    return;
                case STALE:
                default:
                    // Kept, but shown: after a relay restore it would last until the
                    // tracker sends the rules again.
                    failCheck(token, TrackerConnectionState.WAITING,
                        SyncReason.OLDER_RULES, SyncMachine.FAILURE_BACKOFF_SECONDS);
            }
        }
        catch (Exception error)
        {
            // The reply broke off, or took too long, before it was read in full.
            failCheck(token, TrackerConnectionState.OFFLINE,
                SyncReason.UNREACHABLE, SyncMachine.FAILURE_BACKOFF_SECONDS);
        }
    }

    /** Read the reply, a 2xx body only up to MAX_REPLY_BYTES, and say what it means. */
    private RelayContract.Reply classify(RelayPollToken token, Response response)
        throws IOException
    {
        int status = response.code();
        ResponseBody content = response.body();
        String body = null;
        boolean success = status >= 200 && status < 300;
        // A 404's body can be the relay's gone marker.
        if ((success || status == 404) && content != null)
        {
            BufferedSource source = content.source();
            // Buffers at most one byte past the cap, however long the reply.
            if (source.request(MAX_REPLY_BYTES + 1))
            {
                if (success)
                {
                    return RelayContract.oversized();
                }
            }
            else
            {
                body = content.string();
            }
        }
        return RelayContract.classify(gson, token.acceptedVersion, token.rejectedVersion,
            status, response.header("ETag"), response.header("Retry-After"), body);
    }

    /** The relay says the rules the plugin holds are still current. */
    private void confirmUnchanged(RelayPollToken token)
    {
        try
        {
            clientDispatcher.accept(() -> {
                try
                {
                    if (!isPollCurrent(token)
                        || !acceptedStateUnchanged(token))
                    {
                        return;
                    }
                    Instant refreshedAt = clock.instant();
                    synchronized (pollLock)
                    {
                        if (!isPollCurrentLocked(token)
                            || !acceptedStateUnchangedLocked(token))
                        {
                            return;
                        }
                        showLocked(machine.confirmed(refreshedAt));
                    }
                }
                finally
                {
                    clearPoll(token);
                }
            });
        }
        catch (RuntimeException error)
        {
            clearPoll(token);
        }
    }

    /** Parse the payload here, on the reply's thread, and commit it on the client thread. */
    private <T> void prepareImport(
        RelayBundleImporter<T> importer,
        RelayPollToken token,
        String payload,
        String version)
    {
        Prepared<T> prepared;
        try
        {
            prepared = importer.prepare(payload);
        }
        catch (RuntimeException error)
        {
            prepared = null;
        }
        if (prepared == null || prepared.verdict != ImportVerdict.OK)
        {
            SyncReason reason = prepared != null && prepared.verdict == ImportVerdict.FUTURE_FORMAT
                ? SyncReason.FUTURE_FORMAT : SyncReason.INVALID_RULES;
            showIfCurrent(token, now -> machine.rejected(version, reason, now));
            clearPoll(token);
            return;
        }
        T rules = prepared.rules;
        dispatchImport(token, () -> importer.commit(rules, version), version);
    }

    private void dispatchImport(
        RelayPollToken token,
        BooleanSupplier commit,
        String version)
    {
        try
        {
            clientDispatcher.accept(() -> {
                try
                {
                    if (!isPollCurrent(token)
                        || !acceptedStateUnchanged(token))
                    {
                        return;
                    }
                    boolean imported;
                    try
                    {
                        imported = commit.getAsBoolean();
                    }
                    catch (RuntimeException error)
                    {
                        imported = false;
                    }
                    if (!imported)
                    {
                        showIfCurrent(token,
                            now -> machine.rejected(version, SyncReason.INVALID_RULES, now));
                        return;
                    }

                    Instant acceptedAt = clock.instant();
                    synchronized (pollLock)
                    {
                        if (!isPollCurrentLocked(token)
                            || !acceptedStateUnchangedLocked(token))
                        {
                            return;
                        }
                        if (token.code.equals(pendingCode))
                        {
                            commitPendingLocked();
                        }
                        showLocked(machine.accepted(version, acceptedAt));
                    }
                }
                finally
                {
                    clearPoll(token);
                }
            });
        }
        catch (RuntimeException error)
        {
            failCheck(token, TrackerConnectionState.IMPORT_FAILED,
                SyncReason.NONE, SyncMachine.FAILURE_BACKOFF_SECONDS);
        }
    }

    /** The relay has no profile for this code; SyncMachine.notFound says what that means. */
    private void handleNotFound(RelayPollToken token)
    {
        showIfCurrent(token, now -> {
            TrackerConnectionSnapshot next = machine.notFound(token.acceptedVersion != null, now);
            if (pendingCode != null && !machine.repairing())
            {
                // The re-pairing timed out: checks go back to the working pairing.
                pendingCode = null;
            }
            return next;
        });
        clearPoll(token);
    }

    /** A re-pairing delivered: its code becomes the pairing, and the old one is dropped. */
    private void commitPendingLocked()
    {
        settings.replacePairingCode(pendingCode);
        settings.clearLegacySettings();
        currentIdentityCode = pendingCode;
        pendingCode = null;
    }

    /**
     * For a current check: apply a machine transition, and show its snapshot
     * unless rules were accepted or forgotten since the check began.
     */
    private void showIfCurrent(
        RelayPollToken token, Function<Instant, TrackerConnectionSnapshot> transition)
    {
        synchronized (pollLock)
        {
            if (!isPollCurrentLocked(token))
            {
                return;
            }
            boolean unchanged = acceptedStateUnchangedLocked(token);
            TrackerConnectionSnapshot next = transition.apply(clock.instant());
            if (unchanged && next != null)
            {
                showLocked(next);
            }
        }
    }

    /**
     * Show a snapshot, under pollLock, unless it says exactly what the last
     * one did. Being under the lock, the listener hears the snapshots in the
     * order they were made, whichever threads made them.
     */
    private void showLocked(TrackerConnectionSnapshot shown)
    {
        TrackerConnectionSnapshot next = shown.forPairing(activeCodeLocked());
        if (next.equals(snapshot))
        {
            return;
        }
        snapshot = next;
        listener.accept(next);
    }

    /** A current check failed: back off, show why and when the next check is, and end it. */
    private void failCheck(
        RelayPollToken token, TrackerConnectionState state, SyncReason reason, long minimumSeconds)
    {
        showIfCurrent(token, now -> machine.failure(state, reason, now, minimumSeconds));
        clearPoll(token);
    }

    private boolean isPollCurrent(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            return isPollCurrentLocked(token)
                && acceptedStateUnchangedLocked(token);
        }
    }

    private boolean isPollCurrentLocked(RelayPollToken token)
    {
        return !stopped
            && settings.networkAccessAllowed()
            && token != null
            && activePoll == token
            && token.generation == generation
            && token.code.equals(activeCodeLocked());
    }

    private boolean acceptedStateUnchanged(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            return acceptedStateUnchangedLocked(token);
        }
    }

    private boolean acceptedStateUnchangedLocked(RelayPollToken token)
    {
        return equal(token.acceptedVersion,
            RelayContract.canonicalVersion(machine.acceptedVersion()));
    }

    private void clearPoll(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            if (activePoll == token)
            {
                activePoll = null;
            }
        }
    }

    private boolean publishIfCurrent(RelayPollToken token, TrackerConnectionState state)
    {
        synchronized (pollLock)
        {
            if (!isPollCurrentLocked(token)
                || !acceptedStateUnchangedLocked(token))
            {
                return false;
            }
            showLocked(machine.show(state, SyncReason.NONE));
            return true;
        }
    }

    private static boolean equal(String left, String right)
    {
        return left == null ? right == null : left.equals(right);
    }

    private static final class RelayPollToken
    {
        private final long generation;
        private final String code;
        private final String acceptedVersion;
        /** The version the plugin could not import, sent as the validator instead. */
        private final String rejectedVersion;
        /** The request, once sent; cancelled if the check is abandoned. Guarded by pollLock. */
        private Call call;

        private RelayPollToken(
            long generation,
            String code,
            String acceptedVersion,
            String rejectedVersion)
        {
            this.generation = generation;
            this.code = code;
            this.acceptedVersion = acceptedVersion;
            this.rejectedVersion = rejectedVersion;
        }
    }
}

package com.fatelocked.guardian;

import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;

/**
 * Strict Mode decides only exactly matched travel. Walking, NPCs, objects,
 * banks and equipment are never blocked; the menu tags and the locked-bank
 * and over-tier gear warnings cover them.
 */
public final class StrictModeGuard
{
    public GuardResult decideTravel(
        TravelAction action,
        TravelDecision decision,
        GuardContext context)
    {
        if (action == null || decision == null || context == null
            || !context.isEnabled() || context.isPaused()
            || !context.isAccountMatches() || !context.isFreshRules()
            || action.getConfidence() != TravelAction.Confidence.EXACT)
        {
            return allow();
        }

        RuleDecision rule = new RuleDecision(
            decision.getStatus(), decision.getLabel(), decision.getReason());
        return decision.getStatus() == PermissionStatus.LOCKED
            ? new GuardResult(GuardResult.Outcome.BLOCK, rule)
            : allow(rule);
    }

    private static GuardResult allow()
    {
        return new GuardResult(GuardResult.Outcome.ALLOW, null);
    }

    private static GuardResult allow(RuleDecision decision)
    {
        return new GuardResult(GuardResult.Outcome.ALLOW, decision);
    }
}

package com.fatelocked.guardian;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;

public final class StrictModePause
{
    private final Clock clock;
    private Instant pausedUntil;

    public StrictModePause(Clock clock)
    {
        this.clock = clock;
    }

    public synchronized void pauseFor(Duration duration)
    {
        pausedUntil = clock.instant().plus(duration);
    }

    public synchronized void resume()
    {
        pausedUntil = null;
    }

    public synchronized boolean isPaused()
    {
        return remainingSeconds() > 0;
    }

    public synchronized long remainingSeconds()
    {
        if (pausedUntil == null) return 0;
        long millis = Duration.between(clock.instant(), pausedUntil).toMillis();
        if (millis <= 0)
        {
            pausedUntil = null;
            return 0;
        }
        return (millis + 999) / 1000;
    }
}

package com.fatelocked.guardian;

import lombok.Value;

/**
 * What Strict Mode can do right now: off, paused, active, or inactive with
 * the reason it cannot block anything. Built from the same facts as the
 * travel trust gate, so the sidebar never says it is on while every click is
 * let through.
 */
@Value
public class StrictModeReadiness
{
    public enum State { OFF, PAUSED, ACTIVE, INACTIVE }

    State state;
    /** Why Strict Mode cannot act; null unless {@link State#INACTIVE}. */
    String reason;

    public static StrictModeReadiness evaluate(
        boolean enabled,
        boolean paused,
        boolean hasCurrentRules,
        String boundAccount,
        String loggedInAs,
        boolean accountMatches,
        boolean freshRules)
    {
        if (!enabled) return new StrictModeReadiness(State.OFF, null);
        if (paused) return new StrictModeReadiness(State.PAUSED, null);
        if (!hasCurrentRules) return inactive("no tracker rules are loaded");
        if (boundAccount == null || boundAccount.trim().isEmpty())
        {
            return inactive("the tracker profile has no linked account");
        }
        if (loggedInAs == null || loggedInAs.trim().isEmpty())
        {
            return inactive("you are not logged in");
        }
        if (!accountMatches)
        {
            return inactive("the profile is for " + boundAccount.trim()
                + "; you're logged in as " + loggedInAs.trim());
        }
        if (!freshRules)
        {
            return inactive("the rules are more than 15 minutes old");
        }
        return new StrictModeReadiness(State.ACTIVE, null);
    }

    private static StrictModeReadiness inactive(String reason)
    {
        return new StrictModeReadiness(State.INACTIVE, reason);
    }
}

package com.fatelocked.guardian;

import com.fatelocked.storage.LocalFileMerge;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.HashSet;
import java.util.Set;

public final class StrictModeAuditLog
{
    private static final int MAX_ENTRIES = 100;
    private static final Set<String> LEGACY_FIELDS = new HashSet<>(Arrays.asList(
        "timestamp", "actionKind", "target", "chunk", "reason"));
    private static final Set<String> CURRENT_FIELDS = new HashSet<>(Arrays.asList(
        "timestamp", "actionKind", "target", "chunk", "reason",
        "outcome", "paused", "alternativeAvailable"));
    private final Gson gson;
    private final Path path;
    private final List<StrictModeAuditEntry> entries = new ArrayList<>();

    public StrictModeAuditLog(Gson gson, Path path) throws IOException
    {
        this.gson = gson;
        this.path = path;
        load();
    }

    /**
     * Add an entry, merged with the entries on disk now, which another
     * RuneLite may have added since this one loaded: the newest 100.
     */
    public synchronized void append(StrictModeAuditEntry entry) throws IOException
    {
        if (entry == null) return;
        List<StrictModeAuditEntry> merged = new ArrayList<>();
        LocalFileMerge.update(path, current -> {
            List<StrictModeAuditEntry> all = new ArrayList<>(onDisk(current));
            all.addAll(entries);
            all.add(entry);
            all.sort(Comparator.comparingLong(StrictModeAuditEntry::getTimestamp));
            List<StrictModeAuditEntry> unique = new ArrayList<>(new LinkedHashSet<>(all));
            merged.clear();
            merged.addAll(unique.subList(Math.max(0, unique.size() - MAX_ENTRIES), unique.size()));
            State state = new State();
            state.entries = new ArrayList<>(merged);
            return gson.toJson(state).getBytes(StandardCharsets.UTF_8);
        });
        entries.clear();
        entries.addAll(merged);
    }

    public synchronized List<StrictModeAuditEntry> recent(int limit)
    {
        int count = Math.max(0, Math.min(limit, entries.size()));
        List<StrictModeAuditEntry> result = new ArrayList<>();
        for (int i = entries.size() - 1; i >= entries.size() - count; i--)
        {
            result.add(entries.get(i));
        }
        return Collections.unmodifiableList(result);
    }

    private void load() throws IOException
    {
        if (!Files.exists(path)) return;
        entries.addAll(onDisk(Files.readAllBytes(path)));
        while (entries.size() > MAX_ENTRIES) entries.remove(0);
    }

    /**
     * The entries in the file's contents; none if there is no file. A file
     * that isn't an audit log at all is moved aside, where it is kept, rather
     * than written over; entries that aren't safe to show are skipped.
     */
    private List<StrictModeAuditEntry> onDisk(byte[] contents) throws IOException
    {
        if (contents == null) return Collections.emptyList();
        JsonArray loaded = null;
        try
        {
            JsonObject state = gson.fromJson(
                new String(contents, StandardCharsets.UTF_8), JsonObject.class);
            if (state != null && state.has("entries") && state.get("entries").isJsonArray())
            {
                loaded = state.getAsJsonArray("entries");
            }
        }
        catch (JsonParseException | IllegalStateException ex)
        {
            loaded = null;
        }
        if (loaded == null)
        {
            LocalFileMerge.moveAside(path);
            return Collections.emptyList();
        }
        List<StrictModeAuditEntry> valid = new ArrayList<>();
        for (JsonElement element : loaded)
        {
            if (!element.isJsonObject()) continue;
            StrictModeAuditEntry entry = loadEntry(element.getAsJsonObject());
            if (entry != null) valid.add(entry);
        }
        return valid;
    }

    private StrictModeAuditEntry loadEntry(JsonObject object)
    {
        try
        {
            StrictModeAuditEntry entry = gson.fromJson(
                object, StrictModeAuditEntry.class);
            if (!hasSafeCommonFields(object, entry)) return null;

            if (!object.has("outcome") || object.get("outcome").isJsonNull())
            {
                if (!hasOnlyFields(object, LEGACY_FIELDS)) return null;
                return new StrictModeAuditEntry(
                    entry.getTimestamp(), entry.getActionKind(), entry.getTarget(),
                    entry.getChunk(), entry.getReason(),
                    "BLOCKED", false, false);
            }

            if (!hasOnlyFields(object, CURRENT_FIELDS)
                || !isString(object, "outcome")
                || !isBoolean(object, "paused")
                || !isBoolean(object, "alternativeAvailable"))
            {
                return null;
            }
            if ("BLOCKED".equals(entry.getOutcome()))
            {
                return entry.isPaused() ? null : entry;
            }
            if ("ALLOWED_PAUSED".equals(entry.getOutcome()))
            {
                return entry.isPaused() && !entry.isAlternativeAvailable()
                    ? entry : null;
            }
            return null;
        }
        catch (RuntimeException ex)
        {
            return null;
        }
    }

    private static boolean hasSafeCommonFields(
        JsonObject object, StrictModeAuditEntry entry)
    {
        return entry != null
            && object.has("timestamp")
            && object.get("timestamp").isJsonPrimitive()
            && object.get("timestamp").getAsJsonPrimitive().isNumber()
            && isString(object, "actionKind")
            && entry.getActionKind() != null
            && isString(object, "target")
            && entry.getTarget() != null
            && isOptionalString(object, "chunk")
            && isOptionalString(object, "reason");
    }

    private static boolean isString(JsonObject object, String field)
    {
        return object.has(field)
            && object.get(field).isJsonPrimitive()
            && object.get(field).getAsJsonPrimitive().isString();
    }

    private static boolean isBoolean(JsonObject object, String field)
    {
        return object.has(field)
            && object.get(field).isJsonPrimitive()
            && object.get(field).getAsJsonPrimitive().isBoolean();
    }

    private static boolean isOptionalString(
        JsonObject object, String field)
    {
        return !object.has(field)
            || object.get(field).isJsonNull()
            || isString(object, field);
    }

    private static boolean hasOnlyFields(
        JsonObject object, Set<String> allowed)
    {
        for (String field : object.keySet())
        {
            if (!allowed.contains(field)) return false;
        }
        return true;
    }

    private static final class State
    {
        List<StrictModeAuditEntry> entries;
    }
}

